    t[121374] = { name = "Нерозшифровна Мапа", fen = "Several layers of the same landmass appear to be stacked on top of one another, with scores of thin lines weaving all throughout.", fua = "Здається, кілька шарів однієї й тієї ж суші накладено один на одного, а безліч тонких ліній сплітаються по всій поверхні." }
    t[121375] = { name = "Соковитискач Воо", fen = "No one is sure how this juiced anything.", fua = "Ніхто не певен, як він узагалі щось вичавлював." }
    t[121376] = { name = "Меч Гвардії Королеви Азшари", fen = "Traces of an intricate etching in the sword's blade remain despite thousands of years of disuse.", fua = "Сліди вигадливого травлення на лезі меча збереглися попри тисячі років бездіяльності." }
    t[121377] = { name = "Викинута Сокира Звіроповелителя", fen = "A very large bear appears to have taken a bite out of this.", fua = "Схоже, дуже великий ведмідь відкусив від неї шматок." }
    t[121378] = { name = "Сага про Еландрула", fen = "Too long disused to hold tension, this bow was carved with great care and depicts the deeds of an ancient elven hero.", fua = "Надто довго не вживаний, щоб тримати натяг, цей лук було вирізьблено з великою старанністю, і він зображує діяння прадавнього ельфійського героя." }
    t[121379] = { name = "Механізований Мушкет", fen = "Smaller than the average musket, and engraved with the initials 'A.F'.", fua = "Менший за звичайний мушкет, із викарбуваними ініціалами 'A.F'." }
    t[121380] = { name = "Прекрасний Тесак", fen = "Discarded after its previous owner memorized its unique appearance.", fua = "Викинутий після того, як попередній власник запам'ятав його неповторний вигляд." }
    t[121381] = { name = "Щербатий Клинок Колоса", fen = "It unfortunately has no sockets.", fua = "На жаль, він не має гнізд." }
    t[121382] = { name = "Булава з Ноги Членистоногого", fen = "This enormous weapon is almost entirely the leg chitin of what must have been a huge insectoid creature, counterweighted with engraved stones.", fua = "Ця величезна зброя майже повністю складається з хітину ноги вочевидь велетенського комахоподібного створіння, врівноваженого різьбленим камінням." }
    t[121383] = { name = "Дивний Студентський Посох Нар'таласа", fen = "\"Cloudmaster 9000\" is engraved in to the haft, and a tuft of horse hair is attached to the other. What purpose could this possibly serve?", fua = "\"Хмаровладар 9000\" викарбувано на держаку, а на іншому кінці прикріплено пучок кінського волосу. Якій же меті це може слугувати?" }
    t[121384] = { name = "Стихійні Наручі", fen = "Claimed by an unknown victor from the remnants of a powerful water elemental.", fua = "Здобуті невідомим переможцем із решток могутнього елементаля води." }
    t[121385] = { name = "Зотліла Колода Hearthstone", fen = "All you can discern from the faded cards are images of trees with arms and small green humanoids.", fua = "Усе, що ви можете розгледіти на вицвілих картах, — це зображення дерев із руками й маленьких зелених гуманоїдів." }
    t[121386] = { name = "Пояс із Жвал", fen = "This primitive belt is a collection of preserved insectoid jaws the size of a man's forearm, and is completely impractical as attire.", fua = "Цей примітивний пояс — це зібрання збережених комашиних жвал завбільшки з людське передпліччя, і він геть непрактичний як убрання." }
    t[121387] = { name = "Шкіряна Кобура для Пістоля", fen = "Extra pockets contain gold and dice.", fua = "Додаткові кишені містять золото й кості." }
    t[121388] = { name = "Незримі Пута", fen = "These bindings mark the hopeless struggle of the paladin Elund.", fua = "Ці пута знаменують безнадійну боротьбу паладина Елунда." }
    t[121389] = { name = "Скам'яніле Яйце", fen = "More resembling obsidian stone than a gem, a feeling of unsettling dread nags at your thoughts as you hold this in your hands.", fua = "Більше схоже на обсидіан, ніж на самоцвіт; коли ви тримаєте його в руках, ваші думки гнітить тривожний жах." }
    t[121390] = { name = "Бинти Анунда", fen = "Korl won't admit that Anund was trying to heal himself through Kaldrigos's arcane breath with these.", fua = "Корл не визнає, що Анунд намагався зцілити себе цими бинтами від чародійного подиху Калдрігоса." }
    t[121391] = { name = "Просочені Отрутою Наручі", fen = "Covered with foul liquid and shards of glass.", fua = "Вкриті бридкою рідиною та скалками скла." }
    t[121392] = { name = "Багатокишенькові Шкіряні Штани", fen = "Dozens of hidden pockets line these torn pants, each perfectly sized for a throwing dagger.", fua = "Десятки прихованих кишень устеляють ці подерті штани, кожна точно під розмір метального кинджала." }
    t[121393] = { name = "Дратівлива Армада", fen = "Once belonged to a legend that has since fallen from grace.", fua = "Колись належала легенді, яка відтоді втратила свою славу." }
    t[121394] = { name = "Зворотний Таймер Рейдера", fen = "Let me just swap around a few items and trinkets... Alright! Ready in 25.. 24.. 23.. 22... 21..", fua = "Дайте-но я лише переставлю кілька предметів і тринкетів... Гаразд! Готовий через 25.. 24.. 23.. 22... 21.." }
    t[121395] = { name = "Покращені Кислинки", fen = "May greatly improve performance in challenging dungeons.", fua = "Можуть значно поліпшити результати в складних підземеллях." }
    t[121396] = { name = "Крихкі Хітинові Наплічники", fen = "These shoulderguards are ancient even by Azsharan standards and are etched with loa-sigils.", fua = "Ці наплічники прадавні навіть за мірками Азшари й вкриті сигілами лоа." }
    t[121397] = { name = "Сильно Обтяжені Наплічники", fen = "Why would someone want such heavy shoulderpads?", fua = "Навіщо комусь такі важкі наплічники?" }
    t[121398] = { name = "Царство Соратників", fen = "Mother Shahraz gave these to the ones that didn't quite make the cut.", fua = "Мати Шахраз дала їх тим, хто не зовсім пройшов відбір." }
    t[121399] = { name = "Незбалансовані Метальники Глеф", fen = "These surely caused much inaccuracy.", fua = "Вони, безперечно, спричинили чимало промахів." }
    t[121400] = { name = "Безпалі Рукавички Шандріс", fen = "Xalan's gloves looked better on her than on him.", fua = "Рукавички Залана на ній виглядали краще, ніж на ньому." }
    t[121401] = { name = "Рукавички Перехожого", fen = "A man who lives everywhere lives nowhere.", fua = "Хто живе всюди, не живе ніде." }
    t[121402] = { name = "Старі Закривавлені Латні Рукавиці", fen = "May have belonged to a butcher some time ago.", fua = "Колись могли належати різнику." }
    t[121403] = { name = "Випадковий Громовідвід", fen = "Some tufts of hair are melted to the sides.", fua = "Кілька пучків волосся приплавилися по боках." }
    t[121404] = { name = "Невдало Викуваний Шолом", fen = "Inferior production methods robbed this helm of much of its potential power.", fua = "Кепські методи виготовлення позбавили цей шолом значної частки його потенційної сили." }
    t[121405] = { name = "Пошкоджений Латний Шолом Берсерка", fen = "Someone became very angry while wearing this.", fua = "Хтось дуже розлютився, поки носив це." }
    t[121406] = { name = "Подертий Капелюх Дослідника", fen = "Worn down from repeated use.", fua = "Зношений від частого використання." }
    t[121407] = { name = "Порожні Ракетні Латні Поножі", fen = "These could easily launch you a great distance if refilled, if not for the components which exploded in the previous attempt.", fua = "Вони легко могли б закинути вас на велику відстань, якби їх наповнити, якби не складники, що вибухнули під час попередньої спроби." }
    t[121408] = { name = "Загублений М'яч Пуки", fen = "This was very valuable to someone once.", fua = "Колись це було комусь дуже дороге." }
    t[121409] = { name = "Роз'їдений Часом Нагрудник", fen = "Adorning this armor is the remains of a once-vivid painting of a battle between tusked humanoids and giant, faceless creatures.", fua = "Цю броню прикрашають рештки колись яскравого малюнка битви між іклатими гуманоїдами та велетенськими безликими створіннями." }
    t[121410] = { name = "Зотлілі Церемоніальні Шати", fen = "The markings on this robe resemble both the sign of Elune and several venerated Loa spirits.", fua = "Позначки на цій робі нагадують водночас знак Елуни й кількох шанованих духів-лоа." }
    t[121411] = { name = "Промоклий Шкіряний Камзол", fen = "Smells like a wet cat. And a wet bear. And a wet moonkin.", fua = "Пахне мокрим котом. І мокрим ведмедем. І мокрим місячним совобраном." }
    t[121412] = { name = "Легкі Латні Мандрівні Чоботи", fen = "Someone discovered they could walk faster without these, through other means.", fua = "Хтось виявив, що може ходити швидше без них, в інший спосіб." }
    t[121413] = { name = "Двопалі Бойові Чоботи", fen = "These boots are split down the middle at the toes, creating what were undoubtedly two very large and painful-looking spikes before centuries of decay left them dull and brittle.", fua = "Ці чоботи розділені посередині біля пальців, утворюючи те, що, без сумніву, було двома дуже великими й болючими на вигляд шипами, поки століття занепаду не зробили їх тупими й крихкими." }
    t[121414] = { name = "Незнання Ткача Снів", fen = "The only time he was counterspelled was when he wore these boots.", fua = "Єдиний раз, коли йому вдалося поставити контрзакляття, був тоді, коли він носив ці чоботи." }
    t[121415] = { name = "Безум Гекати", fen = "You'd think a warlock would have known that he couldn't wear these.", fua = "Можна було б подумати, що чорнокнижник знав би, що не зможе це вдягнути." }
