    t[128227] = "Ключ, Викуваний з Душ"
    t[128286] = { name = "Хутро Щетинистого", fen = "A thick pelt made up of dense, razor sharp hairs.", fua = "Товсте хутро, утворене з густої, гострої як бритва шерсті." }
    t[128288] = { name = "Лускоскалка", fen = "Here is whence true strength comes. From deep places... within the world, and within oneself.", fua = "Ось звідки приходить справжня сила. З глибоких місць... у світі та в самому собі." }
    t[128289] = { name = "Луска Землезахисника", fen = "...it was one of Neltharion's cast-off scales. It saved Magnar's life. The blast of flame parted around the black scale, but the sheer force carried Magnar out of the lair, sending him tumbling down the slopes of Highmountain.", fua = "...це була одна зі скинутих лусок Нелтаріона. Вона врятувала Маґнару життя. Спалах полум'я розійшовся навколо чорної луски, але сама його сила винесла Маґнара з лігва, скинувши його котитися схилами Високогір'я." }
    t[128290] = { name = "Рунописний Фоліант", fen = "Written in a language you don't understand.", fua = "Написано мовою, якої ви не розумієте." }
    t[128291] = { name = "Переклад Рунопису Фоліанта", fen = "Written in a language you DO understand.", fua = "Написано мовою, яку ви РОЗУМІЄТЕ." }
    t[128292] = { name = "Клинки Полеглого Принца", fen = "When my days have come to an end, you shall be king.", fua = "Коли настане кінець моїх днів, ти станеш королем." }
    t[128293] = { name = "Клинки Полеглого Принца", fen = "I will show you the justice of the grave... and the true meaning of fear.", fua = "Я покажу тобі правосуддя могили... і справжнє значення страху." }
    t[128304] = { name = "Насіння Ісераліни", fen = "Gathered by players with the Herbalism skill. Can be bought and sold on the auction house.", fua = "Збирається гравцями з умінням Травознавства. Можна купувати й продавати на аукціоні." }
    t[128306] = { name = "Г'Ханір, Материнське Дерево", fen = "At the beginning, there was a source of healing and balance, a place where all life could rest and revive.", fua = "На початку було джерело зцілення й рівноваги, місце, де все живе могло відпочити й відродитися." }
    t[128330] = { name = "Корінь Гнилодрева", fen = "Oily roots from the Rotwood Creeper, known for their bitterness.", fua = "Масляниста коренева пагінь повзучого гнилодрева, відома своєю гіркотою." }
    t[128335] = "Вогненна Вода Тліючої Шкури"
    t[128343] = { name = "Темнокам'яний фокус", fen = "This crystal emanates a powerful earthen energy.", fua = "Цей кристал випромінює потужну земну енергію." }
    t[128345] = { name = "Алхімічний Набір Каттерін", fen = "A collection of rare vrykul alchemical reagents, including a large supply of a potent ashen powder.", fua = "Зібрання рідкісних врайкульських алхімічних реагентів, включно з великим запасом потужного попелястого порошку." }
    t[128355] = { name = "Ящик Хадґарових Вусиків", fen = "The flower, not the facial hair.", fua = "Квітка, а не рослинність на обличчі." }
    t[128356] = { name = "Барило Риб'ячого Жиру", fen = "Apparently it wanted to be back in the ocean.", fua = "Вочевидь, воно хотіло повернутися назад в океан." }
    t[128357] = { name = "Кошик Сушених Трав", fen = "Well... they WERE dried.", fua = "Ну... колись вони БУЛИ сушеними." }
    t[128380] = { name = "Перо Карги", fen = "A harpy feather.", fua = "Перо гарпії." }
    t[128392] = { name = "Мінеральний Аналіз Глибокоземля", fen = "A detailed study of the mineral composition of Deepholm's rocks.", fua = "Докладне дослідження мінерального складу порід Глибокоземля." }
    t[128393] = { name = "Наснажений Кристал", fen = "A drogbar crystal empowered with the magic of the waters of Lifespring Cavern.", fua = "Кристал дроґбарів, наповнений магією вод печери Джерела Життя." }
    t[128396] = { name = "Аналіз Обсидіанового Лісу", fen = "A detailed study of the obsidian forest's corruption of the land through dragon fire.", fua = "Докладне дослідження того, як драконяче полум'я зіпсувало землю в Обсидіановому лісі." }
    t[128397] = { name = "Розпилювач від Комах", fen = "Pheremones used to induce fatal attraction in insects.", fua = "Феромони, що викликають у комах фатальний потяг." }
    t[128398] = { name = "Рибальське Спорядження", fen = "There are a few bite marks, but it appears this equipment doesn't agree with drogbar.", fua = "На ньому кілька слідів від укусів, але, схоже, дроґбарам це спорядження не до смаку." }
    t[128402] = { name = "Паща Проклятих", fen = "The Maw's thirst is unquenchable. If it is not fed fresh victims, it will not hesitate to drink from its wielder instead.", fua = "Спрага Пащі невгамовна. Якщо її не годувати свіжими жертвами, вона не вагаючись питиме натомість зі свого носія." }
    t[128403] = { name = "Апокаліпсис", fen = "It shall sow destruction and war. Famine and death. It shall tempt with power, and then bring an end to all life.", fua = "Він посіє руйнацію й війну. Голод і смерть. Він спокушатиме могутністю, а тоді покладе край усьому живому." }
    t[128404] = { name = "Особливе від Гелбріма", fen = "Quite potent.", fua = "Доволі міцне." }
    t[128405] = { name = "Аналіз Складу Сароніту", fen = "A detailed study of the saronite mines, and it's connection to something other-worldly.", fua = "Докладне дослідження саронітових копалень та їхнього зв'язку з чимось потойбічним." }
    t[128436] = "Палкий любовний роман: Молочка не бажаєш?"
    t[128437] = "Зілля Булькітливих Пустул"
    t[128476] = { name = "Ікла Пожирача", fen = "The hound's bite lingers, even long after its death. A surprisingly effective and subtle tool for something so crude.", fua = "Укус гончака триває ще довго після його смерті. Напрочуд дієве й витончене знаряддя як на щось таке грубе." }
    t[128479] = { name = "Ікла Пожирача", fen = "Azhir manari kirel. Akim manari galar!", fua = "Azhir manari kirel. Akim manari galar!" }
