    t[128655] = { name = "Кролик", fen = "Small enough to be used as ammo in a Critter Hand Cannon.", fua = "Достатньо малий, щоб слугувати набоєм для Ручної Гармати на Дрібноту." }
    t[128680] = { name = "Зразок Зіпсованого Кореня", fen = "A sample of corrupted root from the great Shaladrassil.", fua = "Зразок зіпсованого кореня великого Шаладрасілу." }
    t[128681] = { name = "Крихкий Тигель Демонського Подиху", fen = "This pot was crafted for mixing potent fel reagents, but appears in need of reinforcement.", fua = "Цей казанок зробили для змішування потужних реагентів скверни, але він потребує укріплення." }
