    t[128745] = { name = "Молот Саріс", fen = "The hammer of the legendary blacksmith, Saris Swifthammer.", fua = "Молот легендарної ковалихи Саріс Свіфтгаммер." }
    t[128746] = { name = "Дослідження Саріс", fen = "A book containing all of Saris Swifthammer's research of leystone smithing.", fua = "Книга, що містить усі дослідження Саріс Свіфтгаммер щодо ковальства з лейкаменю." }
    t[128751] = { name = "Нагрудник Блек-Рук", fen = "An incredibly sturdy breastplate made from the same rock as Black Rook Hold.", fua = "Неймовірно міцний нагрудник, виготовлений із того ж каменю, що й Цитадель Чорного Граку." }
    t[128752] = { name = "Темниця Душі", fen = "A fragile crystal that is capable of imprisoning a demon.", fua = "Крихкий кристал, здатний ув'язнити демона." }
    t[128753] = { name = "Череп Командування", fen = "Kobolds use skulls to designate their leadership.", fua = "Кобольди позначають черепами своїх ватажків." }
    t[128754] = { name = "Жовта Свічка", fen = "The candle burns yellow.", fua = "Свічка горить жовтим." }
    t[128755] = { name = "Зелена Свічка", fen = "The candle burns green.", fua = "Свічка горить зеленим." }
    t[128756] = "Череп Оенії"
    t[128758] = { name = "Плямистий Морокогриб", fen = "Delicate in flavor, yet lethal in large quantities.", fua = "Делікатний на смак, та смертельний у великій кількості." }
    t[128759] = { name = "Мерехтливий Пилок", fen = "Shimmers and shines in any light.", fua = "Мерехтить і сяє за будь-якого освітлення." }
    t[128760] = { name = "Орляче Яйце", fen = "A large, yet delicate egg of the Highmountain Great Eagle.", fua = "Велике, та крихке яйце Великого Орла Високогір'я." }
    t[128764] = { name = "Соковита Азсунська Фета", fen = "It has a nice creamy texture.", fua = "Вона має приємну вершкову текстуру." }
    t[128765] = { name = "Молот Каз'ґороту", fen = "This titan relic pulses with energy.", fua = "Ця реліквія титанів пульсує енергією." }
    t[128769] = { name = "Видобутий Склом Силокамінь", fen = "Carefully mined leystone.", fua = "Ретельно видобутий силокамінь." }
    t[128805] = "Зілля Захисту від Скверни"
    t[128808] = { name = "Кіготь-Пазур", fen = "The Eagle Spear. Spear of the Wild Gods. Talonclaw. Bearing many names and many blessings, this is a weapon of legends.", fua = "Орлиний Спис. Спис Диких Богів. Кіготь-Пазур. Носячи багато імен і багато благословень, це зброя легенд." }
    t[128813] = { name = "Ядро Скверни-Енергії", fen = "A pulsating core filled with fel energy.", fua = "Пульсуюче ядро, сповнене енергії скверни." }
    t[128819] = { name = "Думгаммер", fen = "A stranger will raise the hammer high, and with it justice shall reign.", fua = "Чужинець здійме молот високо, і завдяки йому запанує справедливість." }
    t[128820] = { name = "Фело'мелорн", fen = "...not elven weapons. Not when they are reforged with magic, and hatred, and a burning need for revenge. No, Arthas. Felo'melorn is stronger than ever-as am I. - Kael'thas Sunstrider", fua = "...не ельфійська зброя. Не тоді, коли її перековано з магією, ненавистю й палкою жагою помсти. Ні, Артасе. Фело'мелорн сильніший, ніж будь-коли — як і я. — Кель'тас Сонцеблукач" }
    t[128821] = { name = "Пазурі Урсока", fen = "Ursoc, brother of Ursol and guardian of the furbolg tribes... bearer of the strength of the forest itself.", fua = "Урсок, брат Урсола й охоронець племен фурболгів... носій сили самого лісу." }
    t[128822] = { name = "Пазурі Урсока", fen = "Azeroth will need you. If you do not stand ready, the world may fall.", fua = "Азерот потребуватиме тебе. Якщо не будеш напоготові, світ може загинути." }
    t[128823] = { name = "Срібна Рука", fen = "Tyr replied that he did not consider his argent hand a reminder of defeat. For him it was a symbol of the sacrifice he had made to defend Azeroth, and he wanted the world to see it that way as well.", fua = "Тір відповів, що не вважає свою срібну руку нагадуванням про поразку. Для нього вона була символом жертви, яку він приніс на захист Азероту, і він хотів, щоб світ бачив її саме так." }
    t[128824] = { name = "Фоліант Срібної Руки", fen = "Esarus thar no'Darador.", fua = "Esarus thar no'Darador." }
    t[128825] = { name = "Т'уре, Маяк Наару", fen = "Blessed are the torchbearers, who bring light to the darkness.", fua = "Благословенні смолоскипоносці, які несуть світло в темряву." }
    t[128826] = { name = "Тас'дора, Спадок Віндраннерів", fen = "When it was retrieved from the Sunwell, the bow radiated power. Talanas was humbled by the gift. He named the weapon Thas'dorah, \"Valor of the Forest.\"", fua = "Коли його дістали із Сонячного Колодязя, лук випромінював міць. Таланас був вражений цим даром. Він назвав зброю Тас'дора — \"Доблесть Лісу\"." }
    t[128827] = { name = "Ксал'атат, Клинок Чорної Імперії", fen = "Xal'atath has a mind of its own. Ignore its maddening whispers. Do not trust the lies it spins. Take from it what you need, but always remember that the dark presence in the blade is not your ally.", fua = "Ксал'атат має власну волю. Не зважайте на її божевільний шепіт. Не вірте брехні, яку вона плете. Беріть від неї те, що вам потрібно, та завжди пам'ятайте, що темна присутність у клинку — не ваш союзник." }
    t[128831] = { name = "Бойові Клинки Алдрахі", fen = "His warblades howled over the clamor of battle, rending anything that came near. Each demon Toranaar vanquished seemed to fill him with renewed vigor and strength. He was an army unto himself.", fua = "Його бойові клинки вили понад гомоном битви, шматуючи все, що наближалося. Кожен демон, якого здолав Торанаар, неначе наповнював його новою снагою й силою. Він був цілою армією у власній особі." }
    t[128832] = { name = "Бойові Клинки Алдрахі", fen = "The Aldrachi were a proud race. Too proud to serve. Millions of demons died before the Aldrachi were wiped out, and it took Sargeras himself to kill their king.", fua = "Алдрачі були гордим народом. Надто гордим, щоб служити. Мільйони демонів полягли, перш ніж алдрачі було винищено, і лише сам Сарґерас зміг убити їхнього короля." }
    t[128833] = "Калдорайське Імбирне Вино"
    t[128854] = "Дороговказ Гельгейму"
    t[128858] = { name = "Коса Елуни", fen = "There is power within that would be freed. With balance and control, the wolf may be tamed, but only for a time.", fua = "У ній криється сила, що прагне волі. Через рівновагу й самовладання вовка можна приборкати, та лише на час." }
    t[128859] = { name = "Ікла Ашамани", fen = "She ripped through the demons' ranks and then disappeared into the trees. She crept along the high branches and dove down upon the Legion commanders. She was a terror, a fearsome beast, and she held nothing back, offering no mercy.", fua = "Вона рвала ряди демонів, а тоді зникала між дерев. Вона кралася високими гілками й кидалася згори на командирів Легіону. Вона була жахіттям, грізною звіриною, і не стримувала себе, не даючи пощади." }
    t[128860] = { name = "Ікла Ашамани", fen = "The sacrifice of Ashamane is remembered to this day. We live by her grace, and her children still tread the forests with us as our closest companions.", fua = "Жертву Ашамані пам'ятають донині. Ми живемо її милістю, а її діти й досі блукають лісами поруч із нами, наші найвірніші супутники." }
    t[128861] = { name = "Удар Титана", fen = "A peerless example of techno-magical engineering, infused with the power of storms.", fua = "Неперевершений взірець техномагічної інженерії, наповнений силою бур." }
    t[128862] = { name = "Чорнохолод", fen = "Ebonchill contained only a sliver of Alodi's might, but even that was more than most magi could ever hope of wielding.", fua = "Чорнохолод містив лише крихту могутності Алоді, але навіть цього було більше, ніж будь-коли могли сподіватися опанувати більшість магів." }
    t[128864] = { name = "Скелясті Пагорби Високогір'я", fen = "Goat saliva has caused the ink to run and blur.", fua = "Козяча слина розмила чорнило, і воно розпливлося." }
    t[128866] = { name = "Сторож Істини", fen = "With the first hammer fall, rivers of magma spilled from the icy mountains. With the second, the sky howled and lightning set the heavens aflame. With the third, a single ray of sunlight pierced the storm clouds and whispered over Truthguard's surface.", fua = "Із першим ударом молота з крижаних гір ринули ріки магми. З другим небо завило, і блискавки запалили небеса. З третім єдиний промінь сонячного світла пронизав грозові хмари й прошелестів над поверхнею Сторожа Істини." }
    t[128867] = { name = "Шукач Клятви", fen = "Killing for the sake of killing... conquering for the sake of conquest... there is no honor in such things. There is only shame and regret.", fua = "Убивати заради вбивства... завойовувати заради завоювання... у цьому немає честі. Лише ганьба й каяття." }
    t[128868] = { name = "Гнів Світла", fen = "It was with our greatest hopes and prayers that we attended the ceremony that day... and it is with our greatest sorrows that we departed it.", fua = "Із найбільшими надіями та молитвами ми були присутні на церемонії того дня... і з найбільшим горем ми її покинули." }
    t[128869] = { name = "Царевбивці", fen = "It was not a pleasant death. But it was fast, quiet, and efficient. When the orc took his last breath, the wound that killed him became irregular. Nobody would be able to tell whether he had died to a knife, an axe, or a spear.", fua = "Це була неприємна смерть. Але швидка, тиха й дієва. Коли орк зробив свій останній подих, рана, що вбила його, стала нерівною. Ніхто не зміг би сказати, чи загинув він від ножа, сокири чи списа." }
    t[128870] = { name = "Царевбивці", fen = "Countless voices hushed, and countless leaders toppled... all at the whim of his foul command. There would be no redemption for these acts, only solitude and sorrow.", fua = "Незліченні голоси змовкли, незліченні вожді повалені... і все це з примхи його лиховісного наказу. За ці діяння не буде спокути — лише самотність і скорбота." }
    t[128872] = { name = "Клинки Жаху", fen = "She saw herself commanding an impossibly large pirate fleet, one that could conquer the high seas and all the nations of Azeroth. Every ship that dared to challenge her burned, and every city gave up its treasures or was destroyed.", fua = "Вона бачила себе на чолі неймовірно великого піратського флоту, здатного підкорити відкрите море і всі народи Азероту. Кожен корабель, що смів кинути їй виклик, палав, а кожне місто віддавало свої скарби або гинуло." }
    t[128873] = { name = "Лють Кам'яної Матері", fen = "Created through the power of Doomhammer and the powerful shaman who wields it.", fua = "Створена силою Молота Долі та могутнього шамана, який ним володіє." }
