    t[128908] = { name = "Бойові Мечі Валар'ярів", fen = "Helya's betrayal shall never be forgiven. Let her rot beneath the waves, far from the Halls of Valor.", fua = "Зраду Гельї ніколи не буде прощено. Хай гниє під хвилями, далеко від Чертогів Звитяги." }
    t[128910] = { name = "Стромкар, Зброєлам", fen = "The steel of the barbarian king shall strike the final blow. It shall silence the din of battle, and bring the first kingdom into an age of peace.", fua = "Сталь короля-варвара завдасть останнього удару. Вона змусить замовкнути гуркіт битви й приведе перше королівство в епоху миру." }
    t[128911] = { name = "Шарас'дал, Скіпетр Припливів", fen = "They drifted into the abyss, but Azshara and her Highborne remained unbroken. The darkness around them was absolute, and so the queen willed Sharas'dal to bring them light...", fua = "Вони занурилися в безодню, та Азшара і її Високороджені лишилися незламні. Темрява довкола них була цілковита, тож королева наказала Шарас'далу принести їм світло..." }
    t[128933] = { name = "Праве Око Рашара", fen = "The amber eye has a soft, warm glow that invites a closer look.", fua = "Бурштинове око має м'яке, тепле сяйво, що вабить придивитися ближче." }
    t[128934] = { name = "Щит Морської Королеви", fen = "As the ocean crushed the life from their bodies, ancient creatures stirred in the darkness. Their whispers flowed through the currents. Their powers wrapped tight around the queen and her servants.", fua = "Коли океан вичавлював життя з їхніх тіл, у темряві заворушилися прадавні істоти. Їхній шепіт линув течіями. Їхня сила міцно обвила королеву та її слуг." }
    t[128935] = { name = "Кулак Ра-дена", fen = "To seal Al'Akir's demise, Master Ra slammed his fist into the mountaintop. The heavens split wide, and all the fire and fury they contained crashed down atop the Windlord's head.", fua = "Щоб запечатати загибель Аль'Акіра, Майстер Ра вдарив кулаком об вершину гори. Небеса розкололися навпіл, і весь вогонь та лють, що вони містили, обрушилися на голову Володаря Вітру." }
    t[128936] = { name = "Захист Верховного Хранителя", fen = "Ra and Helya crafted a shield, the Highkeeper's Ward, to act as a key to the Elemental Plane. It thrummed with the energies of the four elements, which Ra could call upon whenever he desired.", fua = "Ра і Хелья викували щит, Захист Верховного Хранителя, щоб він слугував ключем до Стихійного Виміру. Він гудів енергіями чотирьох стихій, до яких Ра міг закликати, коли забажає." }
    t[128937] = { name = "Шейлун, Посох Туманів", fen = "You seek the calm, inevitable force of a deep river, the kind that carves canyons into the toughest stone and carries away warriors on its currents without so much as a ripple. Sheilun is the embodiment of that idea.", fua = "Ви прагнете спокійної, неминучої сили глибокої річки, тієї, що вирізає каньйони в найтвердішому камені й несе воїнів своєю течією, не лишаючи й брижів. Шейлун — утілення цієї ідеї." }
    t[128938] = { name = "Фу Цзань, Супутник Мандрівника", fen = "From the beginning, this staff has accompanied legendary creatures and immortal spirits as they carried out important, lasting work all across Azeroth.", fua = "Від самого початку цей посох супроводжував легендарних істот та безсмертних духів, поки вони звершували важливу, тривку справу по всьому Азероту." }
    t[128940] = { name = "Кулаки Небес", fen = "When Irmaat hefted his two weapons and tested the power within them, uncontrollable fury spilled forth.", fua = "Коли Ірмаат здійняв дві свої зброї й випробував силу в них, з них вихлюпнулася некерована лють." }
    t[128941] = { name = "Скіпетр Саргераса", fen = "When at last the moment arrived for Ner'zhul to act, he did so with wild abandon, heedless of the consequences. It mattered not to him if Draenor was destroyed; in fact, he welcomed it as part of his legacy.", fua = "Коли нарешті настала мить Нер'зулу діяти, він зробив це з шаленою нестримністю, не зважаючи на наслідки. Йому було байдуже, чи буде знищено Дренор; ба більше, він вітав це як частину своєї спадщини." }
    t[128942] = { name = "Ултхалеш, Жниварка Мертвого Вітру", fen = "The scythe's master will either overcome Sataiel or be consumed, which will only make the blade more powerful. And then another bearer will take their place. And another.", fua = "Володар коси або здолає Сатаїель, або буде поглинутий, що лише зробить клинок сильнішим. А тоді інший носій посяде його місце. І ще інший." }
    t[128943] = { name = "Череп Ман'арі", fen = "When finally Thal'kiel emerged, he was changed. He had aged by centuries, alone in the dark with his thoughts and his thralls. His back was twisted and stooped, and there was an odd glimmer in his eye. He summoned his Wakeners, and we answered the call...", fua = "Коли Тал'кіель нарешті з'явився, він був змінений. Він постарів на століття, на самоті в темряві зі своїми думками й рабами. Спина його викривилася й згорбилася, а в очах був дивний полиск. Він прикликав своїх Пробудників, і ми відповіли на поклик..." }
