    t[129070] = "Перстень Жахливого Пірата Боба"
    t[129072] = { name = "Фіалкова Перлина", fen = "Mrrgrl claimed this from Troggl, who stole it from Ruggrr, who killed Purgg for it, who...", fua = "Мрргрл забрав її в Троґла, який украв її в Рутрра, який убив за неї Пурґа, який..." }
    t[129073] = { name = "Перстень-Печатка Гіркосолі", fen = "Bitterbrine's ring is one of a kind amongst the Gilblin of the Broken Isles.", fua = "Перстень Гіркосолі — єдиний у своєму роді серед ґілблінів Зламаних Островів." }
    t[129075] = "Шкіра Гнівопащі"
    t[129078] = { name = "Розкішні Сссандалі Сссуріни", fen = "A lady of the high court doesn't throw away good shoes, for any reason.", fua = "Дама вищого двору нізащо не викине гарне взуття." }
    t[129079] = { name = "Стійкі до Жовчі Чоботи", fen = "While Bilebrain's many experiments have not been successful, his boots are surprisingly impervious to bile.", fua = "Хоч численні досліди Жовчомозка й не мали успіху, його чоботи напрочуд несприйнятливі до жовчі." }
    t[129080] = "Обмотки на руки альфа-тюленя"
