    t[129084] = { name = "Гніздові Поножі Кинджалодзьоба", fen = "Twigs and bits of straw are stuck in the ringmail.", fua = "У кольчузі застрягли гілочки й соломинки." }
    t[129085] = "Звільнені Наплічники Аркавеллуса"
