    t[132357] = { name = "Стовпи Темного Порталу", fen = "Corrupted by the demonlord Sargeras, Medivh contacted the orc warlock Gul'dan and together they opened the Dark Portal, allowing the Burning Legion to begin its invasion of Azeroth.", fua = "Зіпсутий демоном-лордом Сарґерасом, Медів зв'язався з орком-чорнокнижником Ґул'даном, і разом вони відчинили Темний Портал, давши Палаючому Легіону почати вторгнення в Азерот." }
    t[132359] = "Кайдани Поневолювача"
    t[132365] = { name = "Кайдани Бріндаора", fen = "For his misdeeds, Bryndaor was charged with guarding the gates of Helheim for eternity.", fua = "За свої лиходійства Бріндаор був приречений вічно вартувати ворота Гельгайму." }
    t[132366] = { name = "Віднайдена Воля Колтіри", fen = "Following the Battle for Light's Hope Chapel, the two comrades parted ways. Thassarian opted to serve his king, while Koltira, former defender of Quel'Thalas, chose to join his people, the blood elves.", fua = "Після Битви за Каплицю Надії Світла двоє товаришів розійшлися. Тассаріан обрав служити своєму королю, тоді як Колтіра, колишній захисник Кель'Таласу, обрав приєднатися до свого народу, кровних ельфів." }
    t[132367] = { name = "Служба Кровожера", fen = "After his demise, Gorefiend returned as the first death knight and swore allegiance to Orgrim Doomhammer.", fua = "Після своєї загибелі Кровожер повернувся як перший лицар смерті й присягнув на вірність Оґриму Молоту Долі." }
    t[132368] = { name = "Перший Уламок Персня Фарондіса", fen = "A broken piece of the Band of Farondis.", fua = "Зламаний уламок Персня Фарондіса." }
    t[132369] = { name = "Сигіл Вищого Прикликання Вілфреда", fen = "Left at home on a crucial day during the Argent Tournament.", fua = "Залишено вдома вирішального дня Срібного Турніру." }
    t[132370] = { name = "Браслет Солеока", fen = "A crude ring, suitable for murloc nostrils, lips, and fins.", fua = "Грубий перстень, придатний для мурлоцьких ніздрів, губ і плавців." }
    t[132374] = { name = "Остання Прокляття Каззака", fen = "As the Doom Lord crossed through the Dark Portal to Outland, he left his enemies with a parting gift...", fua = "Коли Лорд Загибелі проходив крізь Темний Портал до Запределля, він лишив своїм ворогам прощальний дарунок..." }
    t[132375] = { name = "Одр, Шаль Імірьярів", fen = "Found pristine under burnt rubble in the village of Ymirheim.", fua = "Знайдено незаплямованим під обгорілими руїнами в селищі Іміргайм." }
    t[132376] = { name = "Накидка Ахеруса", fen = "For you do not face me alone, but the host of the Ebon Blade itself. We are undying, we are unceasing, and we hunger for life!", fua = "Бо ти стаєш не проти мене одного, а проти всього воїнства Чорного Клинка. Ми невмирущі, ми невпинні, і ми спраглі життя!" }
    t[132377] = { name = "Компас Арідена", fen = "A battered old compass with ties to the Dark Riders of Deadwind Pass.", fua = "Старий пошарпаний компас, пов'язаний із Темними Вершниками Перевалу Мертвого Вітру." }
    t[132378] = { name = "Темний Удар Сакролаша", fen = "Misery... confusion... mistrust. These are the hallmarks.", fua = "Журба... сум'яття... недовіра. Ось ознаки." }
    t[132379] = { name = "Злоба Сін'дореїв", fen = "So many of our people have been twisted and dominated by the Burning Legion. It's only fitting that we in turn use their own armies against them.", fua = "Так багато наших людей було спотворено й поневолено Палаючим Легіоном. Тож цілком справедливо, що ми у відповідь обернемо його ж війська проти нього." }
    t[132381] = { name = "Безсонні Кайдани Стретена", fen = "The only risk is that you'll go insane.", fua = "Єдиний ризик — це те, що ти збожеволієш." }
    t[132393] = { name = "Повторюваний Ритуал", fen = "It was always a wonder to outsiders how certain Vrykul warlocks managed to summon and command enormous packs of felstalkers.", fua = "Сторонніх завжди дивувало, як деяким вріколам-чорнокнижникам вдавалося прикликати й скеровувати величезні зграї скверножерів." }
    t[132394] = { name = "Каптур Вічної Зневаги", fen = "Whoever dons this hood gains unholy strength and resolve, but will forever lose all kindness and compassion. Beware...", fua = "Хто вдягне цей каптур, набуде нечестивої сили й рішучості, та назавжди втратить усю добрість і співчуття. Стережися..." }
    t[132406] = { name = "Незрівнянні Пута Сонячного Короля", fen = "Contrary to popular belief, Kael'thas's favored, and usually final, utterance to his enemies was actually 'PYROBLAST!'.", fua = "Усупереч поширеній думці, улюбленим — і зазвичай останнім — словом Кель'таса до ворогів насправді було «ПІРОВИБУХ!»." }
    t[132407] = { name = "Пута Магоудару", fen = "Varo'then was madly in love with the queen. Unfortunately, he never had the opportunity to use these restraints on her.", fua = "Варо'тен був до нестями закоханий у королеву. На жаль, йому так і не випало нагоди застосувати на ній ці пута." }
    t[132409] = { name = "Обпалені Кайдани Анунда", fen = "Why Anund was standing in front of Kaldrigos is anyone's guess. However, legend has it that Anund's final Shadow Word: Pain was key in helping Korl defeat the dread wyrm.", fua = "Чому Анунд стояв перед Калдріґосом — годі вгадати. Однак легенда оповідає, що останнє Анундове Слово Тіні: Біль стало ключем, який допоміг Корлу здолати жахливого вірма." }
    t[132410] = { name = "Скалка Екзодара", fen = "The draenei capital city is able to transcend dimensions and even warp time itself. What could a sliver of its power do in the hands of a mere mortal?", fua = "Столиця дренеїв здатна долати виміри й навіть викривлювати сам час. На що ж здатна крихта її сили в руках простого смертного?" }
    t[132411] = { name = "Хватка Леді Вайш", fen = "Imbued with the power of the naga sea witch, your fingers inside feel frigid but surprisingly limber and highly energized.", fua = "Просякнуті силою морської відьми наг, твої пальці всередині відчувають холод, але напрочуд гнучкі й сповнені енергії." }
    t[132413] = { name = "Штурмові Наручі Роніна", fen = "Mages who wield as much power as Rhonin, a former leader of the Kirin Tor, often use arcane bindings to steady the magic unleashing from their fingertips.", fua = "Маги, що володіють такою ж силою, як Ронін, колишній очільник Кірін-Тору, часто використовують арканні пута, щоб приборкати магію, яка вивільняється з кінчиків їхніх пальців." }
    t[132436] = { name = "Ск'йолдр, Прихисток Івагонта", fen = "Ivagont fought at Kakushan's side, as he always does, during their massacre of the Stormscale naga in Darkshore. By virtue of his protection, they left unscathed.", fua = "Івагонт бився пліч-о-пліч із Какушаном, як завжди, під час їхньої різанини наг Штормової Луски у Темнобережжі. Завдяки його захисту вони вийшли неушкодженими." }
    t[132437] = { name = "Спокуса Матері Шахраз", fen = "You seem a little tense...", fua = "Ти, здається, трохи напружений..." }
    t[132440] = { name = "Свалнґард", fen = "Greatshield of Odyn, lord of the Halls of Valor.", fua = "Великий щит Одіна, володаря Палат Звитяги." }
    t[132441] = { name = "Драуґр, Пояс Вічного Короля", fen = "Legend holds that the bodies of the titanspawn are so saturated with the energy of the creators that they leave behind fragments when the mortal host dies. This girdle is said to have been painstakingly sewn together from those fragments.", fua = "Легенда оповідає, що тіла породжень титанів настільки насичені енергією творців, що по смерті смертного носія лишають по собі уламки. Кажуть, цей пояс було дбайливо зшито з таких уламків." }
    t[132442] = { name = "Пояс Нескінченності", fen = "The magic contained inside seems to be as endless as the Burning Legion.", fua = "Магія, що міститься всередині, здається такою ж нескінченною, як Палаючий Легіон." }
    t[132443] = { name = "Хода Аґрамара", fen = "Time and space are one. To a watcher of the universe, distance is nearly meaningless.", fua = "Час і простір — єдине ціле. Для спостерігача всесвіту відстань майже не має значення." }
    t[132444] = { name = "Прайдаз, Шедевр Ксаварика", fen = "Bearers of this amulet whistle a haunting tune, and those nearby attest to a distant cry of anguish between the notes.", fua = "Власники цього амулета насвистують моторошну мелодію, а ті, хто поруч, запевняють, що між нотами чути далекий зойк страждання." }
    t[132445] = { name = "Ал'майеш, Пояс Надії", fen = "It is said that this once belonged to the original Val'kyr.", fua = "Кажуть, колись він належав першій вал'кірі." }
    t[132446] = { name = "Коштовності Джабрула", fen = "A large sack containing various jewels.", fua = "Великий мішок із різноманітними коштовностями." }
    t[132447] = { name = "Чарівливі Штани Ан'джуни", fen = "Bearers of these trousers often go above and beyond the call of duty.", fua = "Власники цих штанів часто роблять значно більше, ніж велить обов'язок." }
    t[132448] = { name = "Четвертий Урок Інструктора", fen = "Thought to be given by Razuvious to his most gifted acolytes, it is unclear how this band escaped the walls of Naxxramas. Could the Lich King have sent his own agents to the Broken Isles?", fua = "Кажуть, Разувіус дарував цей перстень своїм найобдарованішим послушникам. Та незрозуміло, як він вибрався за мури Наксрамасу. Невже Король-Ліч послав власних агентів на Зламані Острови?" }
    t[132449] = { name = "Обійми Фірікс", fen = "Phyrix was a legendary priest who led adventurers through Molten Core and Blackwing Lair. She met an unfortunate demise at the hands of Nefarian, but her spirit still protects Azeroth's champions to this day.", fua = "Фірікс була легендарною жрицею, що вела шукачів пригод крізь Розплавлене Ядро та Лігво Чорнокрила. Вона спіткала злощасну загибель від руки Нефаріана, та її дух і донині оберігає захисників Азероту." }
    t[132450] = { name = "Непохитна Воля Мьюз", fen = "From their humble beginnings in Silvermoon to the depths of Blackrock Mountain, Muze always remained steadfast, faithfully healing her companions and saving them from the brinks of death.", fua = "Від скромних початків у Сільвермуні до глибин Блекрока Мьюз завжди лишалася стійкою, віддано зціляючи своїх супутників і рятуючи їх від порогу смерті." }
    t[132451] = { name = "Містичний Кілт Майстра Рун", fen = "While Northrend's half-giants naturally know little to no magic, the mystic vrykul of Stormheim are masters of rune magic.", fua = "Хоча напіввелетні Нордскола за природою знають мало магії або й зовсім її не знають, містичні вріколи Штормгейму — майстри рунної магії." }
    t[132452] = { name = "Таємниця Сефуза", fen = "Intangibility is a curious concept. The word suggests some magical ability, but in the physical world, it simply means the power to be here or there, now or later.", fua = "Невловність — цікаве поняття. Слово натякає на якусь магічну здатність, але у фізичному світі воно означає лише силу бути тут чи там, зараз чи згодом." }
    t[132453] = { name = "Кістяні Поножі Брязкотрупа", fen = "Parts of the shambling horror Rattlegore still contain potent necromantic energies that respond to the will of those strong enough to command them.", fua = "Частини човгаючого жахіття Брязкотрупа досі містять потужні некромантські енергії, що коряться волі тих, хто достатньо сильний, аби ними керувати." }
    t[132454] = { name = "Палючий Дотик Коралона", fen = "Deep within the vault protected by Wintergrasp, Koralon the Flame Watcher was furious when intruders entered.", fua = "Глибоко у сховищі під захистом Зимохватки Коралон Полум'яний Вартовий лютував, коли заходили зайди." }
    t[132455] = { name = "Передбачливість Норґаннона", fen = "Magic must be regulated, managed, and controlled. But it must also be appreciated and valued, not hoarded. Such is the paradox that you must comprehend.", fua = "Магію слід унормовувати, керувати нею й контролювати її. Та її водночас слід цінувати й шанувати, а не накопичувати. Такий парадокс ти мусиш осягнути." }
    t[132456] = { name = "Скриня Душ", fen = "Viewed from different angles, there seems to be faint reflection of three different faces.", fua = "Під різними кутами здається, ніби видно слабке відображення трьох різних облич." }
    t[132457] = { name = "Пояс Сили Леттендріс", fen = "Lethtendris constructed a device to siphon Dire Maul's overwhelming corrupt power for herself.", fua = "Леттендріс створила пристрій, щоб викачати для себе всепереможну зіпсуту силу Грізної Сокири." }
    t[132458] = { name = "Сніжні Пута Торавона", fen = "Deep within the vault protected by Wintergrasp, Toravon the Ice Watcher was relentless in smashing interlopers.", fua = "Глибоко у сховищі під захистом Зимохватки Торавон Льодяний Вартовий невпинно трощив непроханих гостей." }
    t[132459] = { name = "Завзятість Чорного Мученика", fen = "Cold steel rests heavily on the brow of this crown's bearer.", fua = "Холодна сталь важко лягає на чоло того, хто носить цей вінець." }
    t[132460] = { name = "Піроґеніка Алітесс", fen = "Depravity... hatred... chaos. These are the pillars.", fua = "Розбещеність... ненависть... хаос. Ось опори." }
    t[132461] = { name = "Хватка Ксалана Грізного", fen = "Ripped from Xalan's hands by night elves during the War of the Satyr.", fua = "Вирвана з рук Ксалана нічними ельфами під час Війни Сатирів." }
    t[132462] = { name = "Бочок Громорога", fen = "Enough meat for the bellies of a thousand warriors.", fua = "М'яса вистачить, щоб наповнити животи тисячі воїнів." }
    t[132463] = { name = "Хребет Хребторуба", fen = "Mature basilisk spines can be used to make broth for vast quantities of stew.", fua = "З хребтів дорослих базилісків можна зварити юшку на величезну кількість рагу." }
    t[132464] = { name = "Стейк із Лей-Іклача", fen = "Ley-infused boar meat is said to grow one-hundred fold in size when cooked.", fua = "Кажуть, лей-просякле кабаняче м'ясо при готуванні розростається у сто разів." }
    t[132466] = { name = "Коріння Шаладрассілу", fen = "The ties of the earth are deep, consistent, and rarely waver.", fua = "Зв'язки землі глибокі, незмінні й рідко вагаються." }
    t[132467] = { name = "Креслення: Амулет з Небокаменя", fen = "Teaches you how to craft a Skystone Pendant.", fua = "Навчає вас виготовляти Амулет з Небокаменя." }
    t[132468] = { name = "Креслення: Амулет з Глибинного Бурштину", fen = "Teaches you how to craft a Deep Amber Pendant.", fua = "Навчає вас виготовляти Амулет з Глибинного Бурштину." }
    t[132469] = { name = "Креслення: Амулет з Азсуніту", fen = "Teaches you how to craft an Azsunite Pendant.", fua = "Навчає вас виготовляти Амулет з Азсуніту." }
    t[132472] = { name = "Скверний Деконструктор", fen = "If all you have is a hammer...", fua = "Коли все, що ти маєш, — це молот..." }
    t[132484] = { name = "Майстерно Огранований Сапфір Виру", fen = "A sparkling blue gem.", fua = "Іскристий блакитний самоцвіт." }
