    t[132560] = { name = "Сутність Вихору", fen = "Small and lightweight, it feels like it could float away on a breeze.", fua = "Мала й легка, наче от-от спурхне з подихом вітру." }
    t[132738] = { name = "Серце Зін-Азшарі", fen = "Said to spread Azshara's grace across her people and force her wrath upon her enemies. Lightning arcs across it fervently.", fua = "Кажуть, воно несе ласку Азшари її народу й обрушує її гнів на ворогів. По ньому несамовито проскакують блискавки." }
    t[132744] = { name = "Брухт Адамантієвої Обшивки", fen = "A remnant of the plating used to reinforce Deathwing the Destroyer's molten scales.", fua = "Залишок плит, якими колись зміцнювали розплавлену луску Дезвінга Руйнівника." }
    t[132751] = { name = "Спотворені Рунні Пута", fen = "Worn by the most powerful eredar to amplify their abilities.", fua = "Носять наймогутніші ередари, щоб посилити свої здібності." }
