    t[132859] = { name = "Щоденник Делаєта: самоцвіти островів", fen = "A day by day account of Delayeth's studies, describing the various gems he found around the Broken Isles and how he cut them into remarkable designs.", fua = "Щоденний запис досліджень Делаєта, що описує різноманітні самоцвіти, знайдені ним на Зламаних островах, і те, як він огранював їх у дивовижні візерунки." }
    t[132860] = { name = "Чорний фоліант", fen = "It hurts to look upon the demonic sigils skittering and burning across the black leather.", fua = "Боляче дивитися на демонічні сигіли, що снують і палають по чорній шкірі." }
    t[132861] = { name = "Естель, натхнення Деджани", fen = "Faith is the beginning of all things. If your skill with the arcane is passable, but not strong, you may still become a sorceress. But if your faith is only passable and not strong, you will never become a priestess.", fua = "Віра — початок усіх речей. Якщо ваша вправність в арканній магії стерпна, та не сильна, ви все одно можете стати чарівницею. Та якщо ваша віра лише стерпна, а не сильна, ви ніколи не станете жрицею." }
    t[132862] = { name = "Перстень полеглих", fen = "Set upon the top of the ring is a black opal, with a swirling mist that resembles something akin to a soul.", fua = "На вершині персня вставлений чорний опал із вируючим туманом, що нагадує щось схоже на душу." }
    t[132863] = { name = "Діадема драконячого вогню Дарклі", fen = "Among Archmage Darckli's innumerable achievements was mastering the art of breathing dragonfire directly from his mouth.", fua = "Серед незліченних звершень архімага Дарклі було опанування мистецтва дихати драконячим вогнем прямо з рота." }
    t[132864] = { name = "Божевілля Мангази", fen = "Mangaza of the Kaldorei was innovative among his brethen for his dedication to a different form of magic, choosing to assault the mind over the body. Tragically, this method eventually proved maddening to himself in addition to his victims.", fua = "Мангаза з калдореїв вирізнявся серед побратимів відданістю іншій формі магії, обравши удар по розуму замість тіла. На жаль, цей метод врешті виявився згубним для його власного глузду на додачу до жертв." }
    t[132866] = { name = "Тримья, перстень богів", fen = "The ring of Odyn, king of the gods in the Halls of Valor.", fua = "Перстень Одіна, короля богів у Палатах Звитяги." }
    t[132867] = { name = "Лупа нічнонароджених", fen = "A magically-ground optical lens, suitable for inspecting documents or gems.", fua = "Магічно відшліфована оптична лінза, придатна для огляду документів чи самоцвітів." }
    t[132875] = { name = "Другий уламок персня Фарондіса", fen = "A broken piece of the Band of Farondis.", fua = "Зламаний уламок Персня Фарондіса." }
