    t[133714] = { name = "Сріблолускова Мересниця", fen = "Too small to eat, but can be used as bait. Useful when fishing in Stormheim.", fua = "Замала, щоб її їсти, але годиться як наживка. Корисна при риболовлі у Штормгеймі." }
