    t[133721] = { name = "Послання в Пляшці з-під Пива", fen = "Includes a note: \"Hope this comes in handy, angler!  - Nat\"", fua = "Містить записку: «Сподіваюся, це стане у пригоді, рибалко! — Нат»" }
    t[133722] = { name = "Принада на Рибу-Сокиру", fen = "Useful when fishing in the oceanic waters of the Broken Isles.", fua = "Корисна при риболовлі в океанічних водах Розламаних островів." }
    t[133723] = { name = "Приголомшена Розлючена Акула", fen = "He's not quite dead yet, but he won't survive long out of the water.", fua = "Вона ще не зовсім здохла, але без води довго не протягне." }
    t[133724] = { name = "Згнилий Китовий Жир", fen = "It smells... not good.", fua = "Пахне... недобре." }
    t[133725] = { name = "Силомерехтлива Собача Риба", fen = "Notoriously shy and difficult to catch.", fua = "Сумнозвісно полохлива й важка для вилову." }
    t[133726] = { name = "Самітник Нар'таласу", fen = "These crabs spend their days hidden beneath the sands of Azsuna's rivers and lagoons.", fua = "Ці краби проводять дні, ховаючись під пісками річок і лагун Азсуни." }
    t[133727] = { name = "Примарна Риба-Королева", fen = "A spectre of the queenfish as they once were, ten thousand years ago.", fua = "Привид риби-королеви, якою вона була колись, десять тисяч років тому." }
    t[133728] = { name = "Жахоплавець", fen = "Succumbed to the nightmare that plagues Val'Sharah.", fua = "Піддався кошмару, що мучить Вал'шару." }
    t[133729] = { name = "Колючий Камбала", fen = "Covered with spines, from gill to tail.", fua = "Укрита шипами від зябер до хвоста." }
    t[133730] = { name = "Прадавня Моховійка", fen = "The moon-blessed waters of Val'sharah allow the mossgill to grow indefinitely.", fua = "Благословенні місяцем води Вал'шари дають моховійкам рости безмежно." }
    t[133731] = { name = "Гірська Риба-Куля", fen = "Revered by the murlocs of Highmountain.", fua = "Шанована мерлоками Високогір'я." }
    t[133732] = { name = "Холодноводний Короп", fen = "This breed detests warmth, preferring the icy waters of snowy Highmountain.", fua = "Ця порода ненавидить тепло, віддаючи перевагу крижаним водам засніженого Високогір'я." }
    t[133733] = { name = "Прадавній Лосось Високогір'я", fen = "With the drogbar hunting them so voraciously, Highmountain salmon rarely get this old.", fua = "Оскільки дроґбари полюють на них так жадібно, лосось Високогір'я рідко доживає до такого віку." }
    t[133734] = { name = "Уделфіск", fen = "The oodelfjisk were fished to extinction long ago.", fua = "Уделфісків давно виловили до повного зникнення." }
    t[133735] = { name = "Сірочеревий Омар", fen = "Attracted to anything shiny.", fua = "Його приваблює все блискуче." }
    t[133736] = { name = "Громовий Штормовий Скат", fen = "The largest stormrays are the most deadly.", fua = "Найбільші штормові скати — найсмертоносніші." }
    t[133737] = { name = "Жаба-Магоїд", fen = "Much like the nightborne, the frogs of Suramar have developed an insatiable appetite for magic.", fua = "Як і Нічнонароджені, жаби Сурамару виробили невгамовний апетит до магії." }
    t[133738] = { name = "Риба-Куля Провидця", fen = "On rare occasions, murlocs have been known to use these fish as weapons.", fua = "У рідкісних випадках мерлоки, як відомо, використовують цих риб як зброю." }
    t[133739] = { name = "Опоганений Рунолуский Коі", fen = "The skin of a fish but the heart of a demon. Even the fish are not safe from the Legion.", fua = "Шкіра риби, але серце демона. Навіть риби не убезпечені від Легіону." }
    t[133740] = { name = "Риба-Сокира", fen = "Similar to a swordfish, but with a slower attack speed.", fua = "Схожа на рибу-меч, але з повільнішою швидкістю атаки." }
    t[133741] = { name = "Глибоководний Кальмар", fen = "Cannot be fished, as they never come within a mile of the ocean's surface. These squid must be obtained through... alternative methods.", fua = "Його неможливо виловити, адже він ніколи не наближається до поверхні океану ближче ніж на кілометр. Цих кальмарів доводиться здобувати... іншими способами." }
    t[133742] = { name = "Прадавня Чорна Баракуда", fen = "Outside of the notorious whale shark, this is one of the largest fish in the seas of Azeroth.", fua = "Окрім сумнозвісної китової акули, це одна з найбільших риб у морях Азероту." }
    t[133743] = { name = "Свіжа Плоть Скверни", fen = "The fel-infused flesh of a Felfire Basilisk.", fua = "Просякнута скверною плоть вогнескверного василіска." }
