    t[133927] = { name = "Міцна Дошка", fen = "A large wooden plank salvaged from shipwrecks in Azuregale Bay.", fua = "Велика дерев'яна дошка, дістана з корабельних уламків у Лазурній затоці." }
    t[133934] = { name = "Червоний Феєрверк Діді", fen = "Didi's high-propulsion, pocket-sized, saronite fireworks.", fua = "Кишеньковий саронітовий феєрверк Діді з потужним розгоном." }
    t[133935] = { name = "Синій Феєрверк Діді", fen = "Didi's high-propulsion, pocket-sized, saronite fireworks. Now in blue.", fua = "Кишеньковий саронітовий феєрверк Діді з потужним розгоном. Тепер у синьому." }
    t[133936] = { name = "Фіолетовий Феєрверк Діді", fen = "Didi's high-propulsion, pocket-sized, saronite fireworks. Now in purple.", fua = "Кишеньковий саронітовий феєрверк Діді з потужним розгоном. Тепер у фіолетовому." }
    t[133940] = "Шовкоткана Пов'язка"
    t[133942] = "Шовкоткана Шина"
    t[133946] = { name = "Плазмовий Лазерний Засув", fen = "Used to secure the most complex of prison cells.", fua = "Слугує для замикання найскладніших тюремних камер." }
    t[133947] = { name = "Необроблений Самоцвіт", fen = "This unrefined gem holds tremendous power for those who know how to harness it.", fua = "Цей необроблений самоцвіт таїть величезну силу для тих, хто вміє нею скористатися." }
    t[133948] = { name = "Кулаки Небес", fen = "There was a great flash of light and a great rush of air, and when it was done, Irmaat could feel his weapons, Al'burq and Alra'ed trembling with elemental power.", fua = "Спалахнуло яскраве світло, війнув потужний порив вітру, а коли все стихло, Ірмаат відчув, як його зброя, Ал'бурк і Алра'ед, тремтить від стихійної сили." }
    t[133956] = { name = "Нестабільний Фокус Чарів", fen = "Hums with energy.", fua = "Гуде енергією." }
    t[133958] = { name = "Таємниці Порожнечі", fen = "The moment I touched the blade, a name was spoken in my mind: Xal'atath. I knew then that I could not destroy the dagger. Not yet. How can one defeat a power she does not understand?", fua = "Тієї миті, коли я торкнувся клинка, у моїй свідомості пролунало ім'я: Ксал'атат. Тоді я зрозумів, що не зможу знищити кинджал. Ще ні. Як можна здолати силу, якої не розумієш?" }
    t[133959] = { name = "Серце Фенікса", fen = "When the fighting was done, Dath'Remar stood painted in demon blood. As night fell, we knew that more battles remained, and yet, with this elf and this blade among us, we held out hope that victory did not lie beyond our grasp.", fua = "Коли битву було завершено, Дат'Ремар стояв, заплямований кров'ю демонів. Коли настала ніч, ми знали, що попереду ще багато боїв, і все ж, маючи серед нас цього ельфа й цей клинок, ми плекали надію, що перемога нам по силі." }
    t[133960] = { name = "Око Сокирохвоста", fen = "These eyeballs have a surprising amount of liquid inside of them.", fua = "У цих очах напрочуд багато рідини." }
    t[133961] = { name = "Повітряний Міхур Сашж'тар", fen = "Naga use this bladder to help with their buoyancy while swimming.", fua = "Наги використовують цей міхур, щоб краще триматися на плаву під час плавання." }
    t[133962] = { name = "Кров Сирени", fen = "Dark blood from a Sashj'tar Siren.", fua = "Темна кров сирени Сашж'тар." }
    t[133963] = "Зелена Іклата Глефа"
    t[133964] = "Глефа, Злита з Демоном"
    t[133965] = "Проста Глефа"
    t[133966] = "Червона Іклата Глефа"
    t[133967] = "Підсилена Помаранчева Глефа"
    t[133970] = { name = "Подорож Занн'есу", fen = "The Zann'esu mage clan left their home village of Brunnhildar in search of the perfect magic to defeat the Lich King. They never returned.", fua = "Маги клану Занн'есу покинули рідне село Бруннгільдар у пошуках досконалої магії, щоб здолати Короля-Ліча. Вони так і не повернулися." }
    t[133971] = { name = "Зенк'арам, Вінець Іріді", fen = "Constructed from the finest felcloth, Iridi drew power from this anadem to defeat Dargonax.", fua = "Виготовлений з найкращої скверно-тканини, цей вінець дав Іріді силу здолати Дарґонакса." }
    t[133973] = { name = "Болісний Дотик Близнючок", fen = "'Enough with these orbs, Fjola. Let's finish these challengers.' -Eydis Darkbane", fua = "«Досить уже цих сфер, Ф'йоло. Покінчимо з цими зухвальцями». — Ейдіс Темнопогуба" }
    t[133974] = { name = "Плач Лана'тель", fen = "Lana'thel shed tears for the lives of the elven kin she expected to lose during their war march to Northrend. She had no idea at the time that she would be the cause of many more.", fua = "Лана'тель проливала сльози за життями ельфійських родичів, які, як вона гадала, загинуть під час їхнього воєнного походу до Нордролу. Тоді вона й гадки не мала, що сама стане причиною ще багатьох смертей." }
    t[133976] = { name = "Сінідарія, Симбіот", fen = "This demonic symbiote adapted to draw power from the thrill of combat, sometimes mimicking the actions of its host.", fua = "Цей демонічний симбіот пристосувався черпати силу з гарячки бою, інколи повторюючи дії свого носія." }
    t[133977] = { name = "Останній Бій Бело'віра", fen = "The final act of Belo'vir Salonar, Grand Magister of Quel'Thalas during the Third War, was to teleport Lady Liadrin to safety as the city fell.", fua = "Останнім вчинком Бело'віра Салонара, Великого Магістра Квел'Таласа під час Третьої війни, було телепортувати леді Ліадрін у безпечне місце, коли місто впало." }
    t[133978] = { name = "Деталі Розгортного Роздавача Куль", fen = "They appear to be entangled with vines and scratched by their thorns.", fua = "Схоже, вони обплутані ліанами й подряпані їхніми колючками." }
    t[134014] = { name = "Тіньоцвіт", fen = "These delicate petals contain a potent toxin.", fua = "Ці тендітні пелюстки містять потужну отруту." }
    t[134015] = { name = "Смердюча Риб'яча Голова", fen = "The oils of this fish are used in a number of drogbar alchemical concoctions.", fua = "Жир цієї риби використовується в численних алхімічних варивах дроґбарів." }
    t[134016] = { name = "Глек Флуґу", fen = "This substance of questionable origin is of great value to drogbar brewbruls.", fua = "Ця речовина сумнівного походження дуже цінується пиворобами дроґбарів." }
