    t[134049] = { name = "Останки Місячного Вартового", fen = "A favorite Felhunter snack dating back to the War of the Ancients...", fua = "Улюблений присмак скверно-хортів, відомий ще з часів Війни Прадавніх..." }
    t[134050] = { name = "Неперетравлений Зуб", fen = "Even the felhunter digestive tract has its limits.", fua = "Навіть травний тракт скверно-хорта має свої межі." }
    t[134051] = { name = "Частково Перетравлена Карта Hearthstone", fen = "This one is still mostly good... it just smells funny, that's all.", fua = "Ця ще здебільшого годяща... просто дивно пахне, та й по всьому." }
    t[134052] = { name = "Нашийник Улюбленця", fen = "The inscription reads... \"Fluffy.\"", fua = "Напис гласить... «Пухнастик»." }
    t[134053] = { name = "Загублена Мапа Скарбів", fen = "The ink appears to be smudged. On closer inspection you realize it isn't ink.", fua = "Чорнило, схоже, розмазалося. Придивившись, ви розумієте, що це не чорнило." }
    t[134054] = { name = "Невпізнана Рука", fen = "Anybody need a hand?", fua = "Комусь потрібна рука допомоги?" }
    t[134055] = { name = "Ключ від Зміцненої Клітки", fen = "Angus Stormbrew was looking for this...", fua = "Ангус Штормоварн шукав саме це..." }
