    t[134065] = { name = "Голова Грімвінга", fen = "The massive fangs and dripping fel blood of Grimwing's lifeless head is the stuff of nightmares.", fua = "Велетенські ікла й скверно-кров, що скрапує з безживної голови Грімвінга, — це справжнє кошмарне видовище." }
