    t[134083] = { name = "Надщерблений Уламок Диску Титанів", fen = "One small section of a much larger titan disc.", fua = "Невелика частина значно більшого диску титанів." }
    t[134084] = { name = "Частина Пекельного Пристрою", fen = "A part of the infernal device that Brann found.", fua = "Частина пекельного пристрою, який знайшов Бранн." }
    t[134085] = { name = "Уламок Ключа від Палати", fen = "A fragment of a key to a secret chamber in Suramar.", fua = "Уламок ключа від таємної палати в Сурамарі." }
    t[134089] = { name = "Багряні Пагорби Ередату", fen = "A story written about Eredath, one of Argus' most illustrious cities, before the demons invaded.", fua = "Оповідь про Ередат, одне з найславетніших міст Аргуса, до вторгнення демонів." }
    t[134090] = { name = "Останній Розділ «Багряних Пагорбів Ередату»", fen = "The missing chapter from The Purple Hills of Eredath.", fua = "Загублений розділ з «Багряних Пагорбів Ередату»." }
    t[134091] = { name = "Розкришена Частина Диску Титанів", fen = "One small section of a much larger titan disc.", fua = "Невелика частина значно більшого диску титанів." }
    t[134092] = { name = "Скриня Покровів", fen = "This chest is sealed tight and very lightweight.", fua = "Ця скриня щільно запечатана й дуже легка." }
    t[134093] = { name = "Стародавній Артефакт Високогір'я", fen = "It appears to be a spear. Perhaps Lessah will know more.", fua = "Схоже на спис. Можливо, Лесса знатиме більше." }
    t[134094] = { name = "Стародавнє Намисто Високогір'я", fen = "A crudely constructed jeweled necklace resonating with power.", fua = "Грубо виготовлене намисто із самоцвітами, що пульсує силою." }
    t[134095] = { name = "Уламок Кістки Ече'ро", fen = "A bone fragement of the remains of Eche'ro, Huln Highmountain's mount.", fua = "Уламок кістки з останків Ече'ро, верхового звіра Гульна з Високогір'я." }
