    t[134105] = "Шпичак, Вкритий Фелшифером"
    t[134106] = "Багате на Лейстоун Осердя"
    t[134108] = { name = "Стародавній Артефакт Високороджених", fen = "It appears to be some sort of device, but to what purpose, you're unable to tell.", fua = "Схоже на якийсь пристрій, але для чого він — ви визначити не можете." }
    t[134114] = { name = "Самоцвіт Айлліс", fen = "One of the jewels from the Crown of the Grand Magistrix.", fua = "Один із самоцвітів з Корони Великої Магістрикс." }
    t[134115] = { name = "Звільнений Уламок Артефакту", fen = "The fragment appears to be intact considering the explosion that occurred.", fua = "Уламок здається цілим, як на той вибух, що стався." }
    t[134116] = { name = "Подертий Сувій Високороджених", fen = "A small clue as to where and where not the Orb of Sciallax resides.", fua = "Невелика підказка про те, де є, а де немає Сфери Сіаллакса." }
    t[134117] = { name = "Частина Азсунської Форми для Ключа", fen = "A small section of a larger mold, from which a key can be forged.", fua = "Невелика частина більшої форми, з якої можна викувати ключ." }
    t[134120] = { name = "Нашийник Панування", fen = "Your mind feels fuzzy in the mere presence of the collar.", fua = "Від самої лише близькості нашийника думки туманяться." }
    t[134125] = { name = "Матриця Відбитку Меха-Зв'язку", fen = "Allows you to tame and track pets in the Mechanical family.", fua = "Дозволяє приборкувати й вистежувати улюбленців з механічної родини." }
    t[134128] = { name = "Тайна Пастка", fen = "The runes on the trap pulse faintly.", fua = "Руни на пастці слабко пульсують." }
    t[134129] = { name = "Товста Шкура Залізорога", fen = "High-altitude ironhorn tend to have thicker, more productive coats.", fua = "Високогірні залізороги зазвичай мають товстішу й продуктивнішу шкуру." }
    t[134130] = { name = "Кошлата Шкура Шаблезуба", fen = "The sabers of Highmountain tend to have more fur than those found elsewhere.", fua = "Шаблезуби Високогір'я зазвичай мають густіше хутро, ніж ті, що трапляються деінде." }
    t[134131] = { name = "Щетиниста Ведмежа Шкура", fen = "Large, durable, and incredibly useful when crafting mail armor.", fua = "Велика, міцна й неймовірно корисна для виготовлення кольчужної броні." }
    t[134132] = { name = "Закам'яніла Лусочка Хробака", fen = "The scales on the back of the Highmountain worms are notoriously tough.", fua = "Луска на спинах хробаків Високогір'я славиться своєю міцністю." }
