    t[136820] = { name = "Серце Нітендри", fen = "The corrupted heart of the green dragon Nythendra. While the corruption has quenched its outer fire, its inner fire still blazes as hot as the sun.", fua = "Зіпсуте серце зеленого дракона Нітендри. Хоч псування й погасило її зовнішнє полум'я, внутрішній вогонь палає й досі, гарячий, мов сонце." }
    t[136821] = { name = "Лей-Пігмент", fen = "A glittering purple pigment, suitable for tattooing.", fua = "Мерехтливий фіолетовий пігмент, придатний для татуювання." }
