    t[136832] = { name = "Нерозбірливі Писання", fen = "The text scrawled upon these scrolls is impossible to read unaided.", fua = "Текст, нашкрябаний на цих сувоях, неможливо прочитати без сторонньої допомоги." }
    t[136833] = { name = "Віщунська Сфера Оракула", fen = "This seems to be what allows the Oracle to decipher the writings of the lost priestesses.", fua = "Схоже, саме це дозволяє Оракулу розшифровувати писання загиблих жриць." }
    t[136834] = { name = "Підсилена Скалка Душі", fen = "It does not reflect the face of the viewer, but rather the face of the soul trapped within.", fua = "Вона відображає не обличчя того, хто дивиться, а обличчя ув'язненої всередині душі." }
    t[136835] = { name = "Листя Сльози Сновидця", fen = "Leaves from the Dreamer's Tear, a rare plant among the woods of Val'sharah.", fua = "Листя зі Сльози Сновидця, рідкісної рослини в лісах Вал'шари." }
