    t[136986] = { name = "Зразок Оленячої Крові", fen = "Warm to the touch.", fua = "Теплий на дотик." }
    t[136987] = { name = "Витриманий Бренді зі Сніжної Сливи", fen = "Aged for four years, an excellent vintage.", fua = "Витриманий чотири роки, чудовий врожай." }
    t[137008] = "Діамант Шаленої Бурі"
    t[137011] = { name = "Закоркована Пляшка", fen = "A gift from Ly'leth to Thalyssra.", fua = "Подарунок від Лілет для Таліссри." }
    t[137014] = { name = "Ахор, Вічний Голод", fen = "Demon hunters possess a thirst for battle as endless as the legions of their most hated enemy.", fua = "Мисливці на демонів мають жагу до битви, таку ж нескінченну, як легіони їхнього найненависнішого ворога." }
    t[137015] = { name = "Екоспектр, Творець Світів", fen = "We could not only evoke, but conjure a place of our own. And that everywhere... that has ever existed... it was all in service of our dream. Now please... Hear what I hear.", fua = "Ми могли не лише викликати, а й прикликати власне місце. І все, що будь-коли... існувало... усе це служило нашій мрії. Тепер прошу... Почуй те, що чую я." }
    t[137016] = { name = "Загублена Туніка Сал'салабіма", fen = "Sal'salabim might have lost this when he blacked out for 6 hours...", fua = "Сал'салабім, можливо, загубив це, коли провалився в забуття на 6 годин..." }
    t[137017] = { name = "Нагрудник Золотої Вал'кіри", fen = "The remnant of a great commander who descended upon her enemies from the heavens, shining with the radiance of the sun.", fua = "Решток великої командирки, що спадала на ворогів із небес, сяючи сонячним промінням." }
    t[137018] = { name = "Стерничий Долі", fen = "Bend time itself to protect the world from devastation.", fua = "Скори сам час, щоб захистити світ від спустошення." }
    t[137019] = { name = "Сенедріл, Відбивач Ненависті", fen = "If you know the enemy and know yourself, you need not fear the result of a hundred battles.", fua = "Якщо знаєш ворога й знаєш себе, тобі не варто боятися наслідку сотні битв." }
    t[137020] = { name = "Шепіт Натрезімів", fen = "Pitiful... Is that the best you can do?", fua = "Жалюгідно... Це все, на що ти здатен?" }
    t[137021] = { name = "Підступ Жахолорда", fen = "I've been preparing for you, young prince. I am Mal'Ganis. As you can see, your people are now mine...", fua = "Я готувався до тебе, юний принце. Я Мал'Ганіс. Як бачиш, твій народ тепер мій..." }
    t[137022] = { name = "Жертва Лорамуса Таліпедеса", fen = "These boots are the only thing that remained after the Stone Knife of Sealing trapped Rakh'likh within Loramus the Defiled's body.", fua = "Ці чоботи - єдине, що лишилося після того, як Кам'яний Ніж Запечатання ув'язнив Рах'ліха в тілі Лорамуса Оскверненого." }
    t[137023] = { name = "Обітниця Елуни, Богині Місяця", fen = "When others receive life and energy from you, you too shall receive life and energy from me.", fua = "Коли інші отримують життя й енергію від тебе, ти теж отримаєш життя й енергію від мене." }
    t[137024] = { name = "Стрибуни Айлуро", fen = "The madness within Marl Wormthorn is said to have empowered these boots.", fua = "Кажуть, божевілля всередині Марла Червоточа наділило ці чоботи силою." }
    t[137025] = { name = "Хватка Скайсека", fen = "During the Battle for Mount Hyjal, Skysec, guardian of Nordrassil, endured endless waves of scourge and legion. In the end, he proudly gave his life in defense of the ancient world tree.", fua = "Під час Битви за Гору Гіджал Скайсек, охоронець Нордрассілу, витримав нескінченні хвилі Покари й Легіону. Зрештою він гордо віддав життя, захищаючи прадавнє світове дерево." }
    t[137026] = { name = "Сутність Вливання", fen = "Feel nature flowing through your veins.", fua = "Відчуй, як природа плине твоїми жилами." }
    t[137027] = { name = "Чоботи з Вогнекаменю", fen = "'Brother Adam and Brother David were brilliant mathematicians and monks, always blabbing about abacuses and parabolas.' -Brynild the Brewmaster", fua = "\"Брат Адам і брат Девід були блискучими математиками й монахами, завжди торочили про рахівниці та параболи\". - Брунгільда Пивоварка" }
    t[137028] = { name = "Ей'тас, Місячні Ковзуни Ерамаса", fen = "Eramas Brightblaze always remarked how comfortable these were.", fua = "Ерамас Яснополум'я завжди зауважував, які вони зручні." }
    t[137029] = { name = "Затемнення Кацуо", fen = "Said Kaulder to his brother Katsuo: 'With training, your reactions can become faster and your fists can become more furious than any foe can handle.'", fua = "Сказав Каулдер своєму братові Кацуо: \"З тренуваннями твої реакції стануть швидшими, а кулаки - лютішими, ніж здатен витримати будь-який ворог\"." }
    t[137030] = { name = "Підошви Присмеркохода", fen = "If an SI:7 agent like Caelvana has you in her sights, you'd better run. You better run far, and you better do it quickly.", fua = "Якщо агентка ШІ:7 на кшталт Каелвани взяла тебе на приціл, краще тікай. Краще тікай далеко й роби це швидко." }
    t[137031] = { name = "Хитрі Чоботи Тракси", fen = "Thraxi often disguised herself as a brewmaster monk to deceive her enemies.", fua = "Тракса часто прикидалася монахинею-пивоваркою, щоб одурити ворогів." }
    t[137032] = { name = "Хода Тіньового Сатира", fen = "While the exact origins of the Shadow satyr are unidentified, they are known to be incorporeal creatures that not only exist inside the Emerald Nightmare but in places on Azeroth as well.", fua = "Хоч точне походження тіньових сатирів невідоме, знано, що це безтілесні створіння, які існують не лише в Смарагдовому Жахітті, а й у місцях по всьому Азероту." }
    t[137033] = { name = "Снігоступи Ульра з Пір'я", fen = "They provided the huntress with a feeling of weightlessness- a calm and serenity amid the storm.", fua = "Вони дарували мисливиці відчуття невагомості - спокій і безтурботність посеред бурі." }
    t[137034] = { name = "Мисливські Чоботи Несінгварі", fen = "Something with very large teeth tried taking a bite out of these boots.", fua = "Щось із дуже великими зубами намагалося відкусити шмат від цих чобіт." }
    t[137035] = { name = "Кривавий Пакт Дурисвіта", fen = "Ner'zhul, Elder Shaman of the Shadowmoon Clan, wanted to save his people and finally obtain the power and respect he so dearly desired. But he was deceived...", fua = "Нер'зул, старійшина-шаман клану Тіньомісяччя, прагнув урятувати свій народ і нарешті здобути силу й повагу, яких так жадав. Та його ошукали..." }
    t[137036] = { name = "Стихійні Врівноважувачі", fen = "Originally used by a powerful doomguard to rain down fiery death, these were repurposed for a more benevolent cause in order to balance out the destruction they had previously caused.", fua = "Спершу їх використовувала могутня варта погибелі, щоб насилати вогняну смерть, та потім їх перепризначили для шляхетнішої мети - урівноважити руйнування, яке вони раніше чинили." }
    t[137037] = { name = "Уванімор Негарний", fen = "The corrupting power of the Nightwell flows through this ring, allowing the wielder to siphon power from those under their command.", fua = "Спотворча сила Нічної Криниці плине крізь цей перстень, дозволяючи власнику висмоктувати силу з тих, хто під його командою." }
    t[137038] = { name = "Гнів Напіввелетнів", fen = "Those oversized Vrykul are not the first thing you want to run into in Northrend. Try the undead of Borean Tundra instead.", fua = "Ті здоровезні врайкули - не перші, з ким хочеться зіткнутися в Нордсколі. Спробуй краще нежить Бореальної Тундри." }
    t[137039] = { name = "Бездоганна Скверна Сутність", fen = "The druids of the Emerald Circle manipulated the fel energy within this stone to enhance their attunement with the wild.", fua = "Друїди Смарагдового Кола маніпулювали скверною енергією всередині цього каменю, щоб посилити свій зв'язок із дикою природою." }
    t[137040] = { name = "Мерехтливий Перстень-Печатка", fen = "The fire within Leyara enchants this signet. You can feel that she has finally found peace.", fua = "Внутрішній вогонь Леяри зачаровує цей перстень. Ти відчуваєш, що вона нарешті знайшла спокій." }
    t[137041] = { name = "Подвійна Рішучість", fen = "Druids of the Claw have the ability to transform, becoming either faster or tougher. They typically choose the latter.", fua = "Друїди Пазура мають здатність перетворюватися, стаючи або швидшими, або витривалішими. Зазвичай вони обирають останнє." }
    t[137042] = { name = "Сльозокамінь Елуни", fen = "The myth surrounding Elune, one of the few true deities of Azeroth, suggest her true identity might not yet have been fully understood.", fua = "Міф навколо Елуни, однієї з небагатьох справжніх божеств Азероту, натякає, що її істинна сутність, можливо, ще не до кінця осягнута." }
    t[137043] = { name = "Пастка для Пальців Фріззо", fen = "Apply a little butter and it comes right off!", fua = "Намасти трохи масла - і вона легко знімається!" }
    t[137044] = { name = "Самоцвіт Загубленого Абатства", fen = "Originally a gift from the mage, Veri'thas, this trinket was allegedly stolen from the Lost Abbey after a conflict between the monks and the elves.", fua = "Спершу дарунок мага Вері'таса, цей тринкет нібито вкрали із Загубленого Абатства після сутички між монахами та ельфами." }
    t[137045] = { name = "Око Коллідуса Сторожа Викривлення", fen = "Well... one of his eyes.", fua = "Що ж... одне з його очей." }
    t[137046] = { name = "Ілтеренді, Перлина Корони Сільвермун", fen = "Silvermoon was constructed out of radiant white stone and adorned in crimson tapestry. However, the city's renown was not merely for its beauty. Silvermoon is a seat of magical learning and home to master manipulators of mana.", fua = "Сільвермун збудоване з осяйного білого каменю й оздоблене багряними гобеленами. Однак місто славне не лише красою. Сільвермун - осідок магічного навчання й дім майстерних володарів мани." }
    t[137047] = { name = "Безсмертя Гіткліфа", fen = "Heathcliff, known as the Immortal Object, was said to be immune to any grave injury. Some questioned whether the Blood Knight's fortitude transcended the natural laws of the world.", fua = "Гіткліф, знаний як Безсмертний Предмет, нібито був несприйнятливий до будь-яких тяжких ран. Дехто питав, чи не виходить стійкість Лицаря Крові за межі природних законів світу." }
    t[137048] = { name = "Вивільнена Лють Ліадрін", fen = "We were betrayed by the man we called our prince. I pledge the blades of my Blood Knights to the defeat of Kil'jaeden and the restoration of Silvermoon. We will fight beside you, A'dal.", fua = "Нас зрадив чоловік, якого ми звали своїм принцом. Я присягаю клинки своїх Лицарів Крові поразці Кіл'джедена та відродженню Сільвермун. Ми битимемося пліч-о-пліч із тобою, А'дале." }
    t[137049] = { name = "Відзнака Рейвенголдту", fen = "An insignia only given to those who have demonstrated mastery of the shadows, and killed in service to Ravenholdt.", fua = "Відзнака, що дається лише тим, хто довів майстерність над тінями й убивав на службі Рейвенголдту." }
    t[137050] = { name = "Око Викривленого Нижнього Світу", fen = "In the nether, though the elements of the world are twisted and barely recognizable, their power is without equal.", fua = "У нижньому світі, хоч стихії викривлені й заледве впізнавані, їхня сила не має рівних." }
    t[137051] = { name = "Зосереджувач Джоната Старшого", fen = "Under the training of Jonat Han, new shamans of the Dragonflayer clan mastered the ways of the waters - healing the one and the many.", fua = "Під навчанням Джоната Хана нові шамани клану Драконодерів опановували шляхи вод - зціляючи одного й багатьох." }
    t[137052] = { name = "Кам'яне Серце Аяли", fen = "In the pits of Valhalas, Ayala the Relentless cut down foe after foe on his way to legend. Becoming more lethal as his opponents weakened, he was truly terrifying to spectate.", fua = "У ямах Валхаласу Аяла Невпинний валив ворога за ворогом на шляху до легенди. Стаючи смертоноснішим, коли супротивники слабшали, він був справді жахливим видовищем." }
    t[137053] = { name = "Каззалакс, Лють Фуджієди", fen = "Jinyu whisper tales of the great warrior, Fujieda, who slew a mighty fel demon after lying in wait in a shallow pool for hours.", fua = "Джінью пошепки переказують оповіді про великого воїна Фуджієду, який убив могутнього скверного демона, годинами вичікуючи в мілкій калюжі." }
    t[137054] = { name = "Мури Впали", fen = "Midst the third war, when the walls of Kalimdor defenders fell, Shaka, the Ancient of War, refused.", fua = "Посеред третьої війни, коли впали мури захисників Калімдору, Шака, Прадавній Війни, відмовився." }
    t[137055] = { name = "Голод Зеврима", fen = "Its power was extracted from hunters who were sacrificed in Dire Maul.", fua = "Його силу видобули з мисливців, принесених у жертву в Лютомлині." }
    t[137056] = { name = "Обмотки з Люфи", fen = "Nothing works quite like a good luffa.", fua = "Ніщо не діє так добре, як гарна люфа." }
    t[137057] = { name = "Заборонений Дотик Прихованого Майстра", fen = "For thousands of years, ancient understandings of lifeflow manipulation have been passed in secret from one master to another.", fua = "Тисячоліттями прадавні знання про маніпуляцію потоком життя таємно передавали від одного майстра до іншого." }
    t[137058] = { name = "Припливоклики Преторіанця", fen = "Working together to defeat Azeroth's greatest enemies, the best minds congregated in a forum dedicated to intellectual discussion and war strategy while their champions battled on the frontlines.", fua = "Об'єднавшись, щоб перемогти найбільших ворогів Азероту, найкращі уми збиралися на форумі, присвяченому інтелектуальним дискусіям і воєнній стратегії, тоді як їхні чемпіони билися на передовій." }
    t[137059] = { name = "Рука Віри Тіра", fen = "After losing his hand to the massive proto-dragon Galakrond, Jotun forged Tyr a new one.", fua = "Утративши руку через велетенського протодракона Галакронда, Йотун викував Тірові нову." }
    t[137060] = { name = "Важка Рука Архавона", fen = "Deep within the vault protected by Wintergrasp, Archavon the Stone Watcher was hateful of all trespassers.", fua = "Глибоко у сховищі, яке захищає Льодолапа, Архавон Кам'яний Сторож ненавидів усіх порушників." }
    t[137061] = { name = "Каскадні Очі Раддона", fen = "As the world... goes by... we'll go on forever.", fua = "Поки світ... минає... ми житимемо вічно." }
    t[137062] = { name = "Смарагдовий Ловець Снів", fen = "Ysera dreams and the world trembles.", fua = "Ісера снить, і світ тремтить." }
    t[137063] = { name = "Фундаментальне Спостереження", fen = "Sit back, relax, and observe the world around you.", fua = "Відкинься, розслабся та спостерігай за світом довкола себе." }
    t[137064] = { name = "Вудуїстська Маска Тіньового Мисливця", fen = "'If dey want to kill me, dey betta' kill me da first time. Dey betta' kill me dead. Dey betta' kill me when I'm in my sleep.' -Vol'jin, after surviving Garrosh's assassination attempt.", fua = "\"Як хочуть мене вбити, хай уб'ють із першого разу. Хай уб'ють мене насмерть. Хай уб'ють мене, коли я сплю\". - Вол'джин, переживши спробу вбивства Гаррошем." }
    t[137065] = { name = "Погляд Справедливості", fen = "This helm was once worn by Highlord Alexandros Mograine, and had things gone differently, would have been passed on to his sons, Renault and Darion Mograine.", fua = "Цей шолом колись носив верховний лорд Александрос Мограйн, і, склади все інакше, він перейшов би до його синів, Рено та Даріона Мограйнів." }
    t[137066] = { name = "Плащ Скверних Вогнів", fen = "Appearing like any other found in the molten depths, this one appears to burn with a greater purpose.", fua = "На вигляд такий самий, як будь-який інший у розплавлених глибинах, та цей наче горить із вищою метою." }
    t[137067] = { name = "Вічна Оболонка Елізи", fen = "'100% all natural fury' was an apt description of its owner during the Sundering.", fua = "\"Стовідсоткова натуральна лють\" була влучним описом її власниці під час Розколу." }
    t[137068] = { name = "Поножі Чорного Полум'я", fen = "The Black Flame specializes in providing the finest services and entertainment money can buy, whether they happen to be hard to find items, gladiatorial combat, or lucrative games of chance.", fua = "Чорне Полум'я спеціалізується на наданні найкращих послуг і розваг, які лиш можна купити за гроші, чи то важкодоступні предмети, гладіаторські бої, чи прибуткові азартні ігри." }
    t[137069] = { name = "Воля Валіри", fen = "At a young age, Valeera survived the death of her parents, imprisonment, and slavery. Her enemies have always underestimated her will to survive.", fua = "У юному віці Валіра пережила смерть батьків, ув'язнення та рабство. Її вороги завжди недооцінювали її волю до виживання." }
    t[137070] = { name = "Тієлка, Постава Феррена Маркуса", fen = "Power comes from strength, and true strength comes from strong legs bolting you to the ground.", fua = "Могутність походить від сили, а справжня сила походить від міцних ніг, що приковують тебе до землі." }
    t[137071] = { name = "Наплічники Майстра Рун", fen = "Molgeim of the Assembly of Iron mastered the use of runes for a myriad of devastating effects.", fua = "Молгейм зі Зборища Заліза опанував застосування рун для безлічі руйнівних ефектів." }
    t[137072] = { name = "Мудрість Аман'Тула", fen = "Unto you is charged the great task of keeping the purity of time. Know that there is only one true timeline, though there are those who would have it otherwise. You must protect it.", fua = "Тобі покладено велике завдання - берегти чистоту часу. Знай, що існує лише одна справжня лінія часу, хоча є ті, хто бажав би іншого. Ти мусиш її захистити." }
    t[137073] = { name = "Наплічники Єдності", fen = "Every place you've ever imagined- it is real. It is a fictional city in your mind and you know every corner of it. Your mind is a world. Each of us is a place.", fua = "Кожне місце, яке ти будь-коли уявляв - воно реальне. Це вигадане місто у твоєму розумі, і ти знаєш кожен його закуток. Твій розум - це світ. Кожен із нас - це місце." }
    t[137074] = { name = "Відлуння Великого Розколу", fen = "10,000 years ago, the Well of Eternity imploded. The effects are still felt today.", fua = "10 000 років тому Криниця Вічності зруйнувалася всередину. Її наслідки відчуваються й донині." }
    t[137075] = { name = "Наплічники Так'теритрікс", fen = "During the first invasion of Azeroth, legion commander Tak'theritrix was key in peeling apart the initial night elf defense.", fua = "Під час першого вторгнення в Азерот командирка Легіону Так'теритрікс відіграла ключову роль у розшматуванні першого захисту нічних ельфів." }
    t[137076] = { name = "Обсидіанові Кам'яні Наплічники", fen = "These appear to emanate the same power as the dark portal.", fua = "Від них наче струмує та сама сила, що й від темного порталу." }
    t[137077] = { name = "Вага Землі", fen = "All living creatures trust in the stillness of the earth. They know nothing of the currents that flow beneath its surface. They do not comprehend its weight. They cannot understand its power.", fua = "Усі живі створіння вірять у непорушність землі. Вони нічого не знають про течії, що плинуть під її поверхнею. Вони не осягають її ваги. Вони не здатні зрозуміти її сили." }
    t[137078] = { name = "Порада Темного Титана", fen = "Patience, young one, and you someday will have it all.", fua = "Терпіння, юначе, і колись ти матимеш усе." }
    t[137079] = { name = "Заспокійливий Пояс Гай Пліна", fen = "Gai Plin extracted the healing powers of the Ru'shan River to infuse this belt with its soothing sensations.", fua = "Гай Плін видобув цілющі сили ріки Ру'шан, щоб просочити цей пояс її заспокійливими відчуттями." }
    t[137080] = { name = "Рев Сімох Левів", fen = "Woven from the manes of the fabled Seven Lions, this belt was crafted by the night elf sentinel Tyven.", fua = "Зітканий із грив легендарних Сімох Левів, цей пояс викувала вартова нічних ельфів Тивен." }
    t[137081] = { name = "Бойовий Пояс Армії Вартових", fen = "Sentinels are the expert marksmen and elite fighters among the night elves. Few warriors can match the proud archers' speed and cunning.", fua = "Вартові - вправні стрільці й добірні бійці серед нічних ельфів. Мало хто з воїнів може зрівнятися зі швидкістю й хитрістю гордих лучниць." }
    t[137082] = { name = "Гельбрайн, Линва Туманного Мародера", fen = "Ghostly howls hang in the fog long after Helheim has taken another.", fua = "Примарне виття висить у тумані ще довго по тому, як Хельгайм забрав чергову жертву." }
    t[137083] = { name = "Бездоганний Пояс із Протолуски", fen = "Crafted from a massive proto-dragon scale that appears ancient, yet feels still hot.", fua = "Викуваний із велетенської луски протодракона, що виглядає прадавньою, та все ще гаряча на дотик." }
    t[137084] = { name = "Абсолютна Справедливість Акайну", fen = "His molten powers could shape an entire landscape.", fua = "Його розплавлена сила могла переінакшити цілий ландшафт." }
    t[137085] = { name = "Ціла Линька з Назжатару", fen = "The naga of Nazjatar are masters of sorcery and natural dwellers of the ocean deeps. It makes sense that wearing their discarded skin would grant you a greater control over the tides.", fua = "Наги Назжатару - майстри чаклунства й природні мешканці океанських глибин. Тож зрозуміло, що носіння їхньої скинутої шкіри надає тобі більшої влади над припливами." }
    t[137086] = { name = "Ланцюг Трейна", fen = "The prayer of an ancient Valhalas champion resonates through the links: 'If you stand in the light, you will never stand alone.'", fua = "Молитва прадавнього чемпіона Валхаласу відлунює крізь ланки: \"Якщо ти стоїш у світлі, ти ніколи не стоятимеш на самоті\"." }
    t[137087] = { name = "Хребет Надж'ентуса", fen = "Few naga matched the strength of Naj'entus, champion of Lady Vashj and servant to Illidan Stormrage.", fua = "Мало хто з наг рівнявся силою з Надж'ентусом, чемпіоном леді Вашж і слугою Іллідана Стормрейджа." }
    t[137088] = { name = "Бойовий Кінь Кеанн-Ара", fen = "Legendary fighters always take their opponents head-on.", fua = "Легендарні воїни завжди стрічають супротивників віч-на-віч." }
    t[137089] = { name = "Снага Громового Бога", fen = "And the god of thunder struck down transgressors with great fury and vengeance...", fua = "І бог грому вражав злочинців із великою люттю та помстою..." }
    t[137090] = { name = "Біонічні Стабілізатори Мо'аргів", fen = "If you can stabilize a saw you can stabilize a glaive.", fua = "Якщо можеш стабілізувати пилку, зможеш стабілізувати й глефу." }
    t[137091] = { name = "Загублені Наручі Осквернителя", fen = "While in battle with Loramus Thalipedes atop the Rise of the Defiler, these vambraces flew off the wrists of Razelikh toward the Dark Portal.", fua = "Під час битви з Лорамусом Таліпедесом на Підвищенні Осквернителя ці наручі зірвалися із зап'ясть Разеліха в бік Темного Порталу." }
    t[137092] = { name = "Інтуїція Онета", fen = "Aglaya would have called it Oneth's Overconfidence.", fua = "Аглая назвала б це Самовпевненістю Онета." }
    t[137094] = { name = "Хватка Дикоформера", fen = "Twisted druids of the Wildspawn hoped to one day wield the power that Alzzin bestowed upon these.", fua = "Збочені друїди Дикого Поріддя сподівалися колись опанувати силу, яку Алззін наділив цим предметам." }
    t[137095] = { name = "Едрейт, Пута Аглаї", fen = "Crafted from the hide of an ancient bull that had been graced with a disposition of eternal happiness.", fua = "Викувані зі шкіри прадавнього бика, благословенного вічним щастям." }
    t[137096] = { name = "Дарунок Петрикору", fen = "Ah... It smells like rain today.", fua = "Ах... Сьогодні пахне дощем." }
    t[137097] = { name = "Накривка Питного Рога", fen = "The hearty vrykul of Northrend were able to weather all elements if they had enough drink.", fua = "Дужі врайкули Нордскола могли витримати будь-яку негоду, аби лиш мали досить питва." }
    t[137098] = { name = "Тренувальні Кайдани Родини Золдик", fen = "The Zoldyck family are trained from birth in the art of assassination. In the lower levels of their estate, members learn to resist the effects of and master the use of deadly poisons.", fua = "Родину Золдик від народження вчать мистецтва вбивства. У нижніх рівнях свого маєтку її члени навчаються опиратися дії смертельних отрут і досконало володіти ними." }
    t[137099] = { name = "Промоклі Наручі Зеленошкірого", fen = "In the lawless world of tavern brawls and spontaneous duels, accuracy is of critical importance.", fua = "У беззаконному світі шинкових бійок і спонтанних дуелей влучність має вирішальне значення." }
    t[137100] = { name = "Заперечення Напіввелетнів", fen = "If you think a Tauren trying to hide in the shadows is laughable, you should see one of those Vrykul half-giants try to be sneaky in broad daylight!", fua = "Якщо тобі смішно дивитися, як таврен намагається сховатися в тінях, то поглянь, як один із тих врайкульських напіввелетнів силкується скрадатися серед білого дня!" }
    t[137101] = { name = "Поклик Дикої Природи", fen = "Hunters have a powerful connection to the wild - the ability to call upon the animal aspects to empower themselves and to befriend even the wildest of beasts.", fua = "Мисливці мають могутній зв'язок із дикою природою - здатність прикликати тваринні аспекти, щоб посилити себе й заприязнитися навіть із найдикішими звірами." }
    t[137102] = { name = "Гнів Аль'Акіра", fen = "Lightning still courses through these bindings. Your power feels infinite and ever increasing...", fua = "Блискавки досі струмують крізь ці пута. Твоя сила здається безмежною і дедалі більшою..." }
    t[137103] = { name = "Грозові Шквали", fen = "Crafted from the scales of an ancient storm dragon, these release uncontrollable magic at everything nearby.", fua = "Викувані з луски прадавнього грозового дракона, вони вивільняють некеровану магію на все довкола." }
    t[137104] = { name = "Спокута Нобундо", fen = "Farseer Nobundo left the city broken, but returned empowered by the elements.", fua = "Далекоглядець Нобундо покинув місто зломленим, та повернувся, наділений силою стихій." }
    t[137105] = { name = "Захист Утера", fen = "Uther the Lightbringer, leader of the Silver Hand, commanded such presence on the battlefield that his knights at times seemed both invincible and unstoppable.", fua = "Утер Світоносний, очільник Срібної Длані, мав на полі бою таку могуть, що його лицарі часом здавалися водночас незборимими й нестримними." }
    t[137107] = { name = "Кровопускні кайдани Маннорота", fen = "Come, feast in my blood, and soon you shall feast in the blood of your enemies.", fua = "Прийди, упийся моєю кров'ю, і скоро ти впиватимешся кров'ю своїх ворогів." }
    t[137108] = { name = "Грозолускі латні рукавиці Какушана", fen = "The great warrior Kakushan created these from skins of the Stormscale after he and Ivagont laid waste to their villages in Darkshore. While the naga fled in fear, the Vrykul drank the blood of their tribe members.", fua = "Великий воїн Какушан створив їх зі шкур грозолуских після того, як він та Івагонт спустошили їхні селища на Темнобережжі. Поки наги в страху тікали, врайкули пили кров своїх одноплемінців." }
    t[137109] = { name = "Кс'анші, саван архієпископа Бенедикта", fen = "Is it possible to succeed without any act of betrayal?", fua = "Чи можливо досягти успіху без жодного акту зради?" }
    t[137110] = { name = "Книга звеличених діянь", fen = "Contains tales of the greatest Valarjar.", fua = "Містить оповіді про найвеличніших Валар'ярів." }
    t[137119] = { name = "Скалка Жахіття", fen = "The horrors within are merely a reflection of the beholder.", fua = "Жахіття всередині — то лиш відображення того, хто дивиться." }
    t[137185] = { name = "Руна панування", fen = "An enchanted runestone seething with fel energy.", fua = "Зачарований руновий камінь, що вирує скверною енергією." }
    t[137187] = { name = "Чорнило скверної душі", fen = "A vial of demonic ink.", fua = "Флакон демонічного чорнила." }
    t[137188] = "Гліф полум'яного рятівника"
    t[137190] = { name = "Руна відкриття", fen = "A fel-inscribed rune.", fua = "Скверновикарбувана руна." }
    t[137191] = "Гліф ока інквізитора"
    t[137193] = { name = "Підсилений кристал бурштинової скалки", fen = "An empowered chunk of crystal, taken from the body of an enraged ambershard.", fua = "Підсилений шмат кристала, вийнятий із тіла розлюченого бурштиношкірого." }
    t[137195] = { name = "Обладунок Високогір'я", fen = "A piece of armor, once worn by a fallen Highmountain defender.", fua = "Частина обладунку, яку колись носив полеглий захисник Високогір'я." }
    t[137196] = { name = "Громовий пил", fen = "A magically imbued dust used to enchant the armor of the Thunder Totem tribe.", fua = "Магічно насичений пил, що використовують для зачарування обладунків племені Громового тотема." }
