    t[137211] = { name = "Книга чарів Наламії", fen = "A book woven out of bark and leaf with fey symbols written within the pages.", fua = "Книга, сплетена з кори й листя, зі знаками фейрі на сторінках." }
    t[137212] = { name = "Огранований небокамінь", fen = "Suitable for putting into a ring.", fua = "Годиться для оздоблення персня." }
    t[137213] = { name = "Воронячий пил", fen = "Ebony dust from disenchanting sigils of the Black Rook night elves.", fua = "Чорний як смола пил, отриманий від розчаклування сигілів нічних ельфів Воронячого замку." }
    t[137214] = { name = "Огранований глибинний бурштин", fen = "Suitable for putting into a ring.", fua = "Годиться для оздоблення персня." }
    t[137215] = { name = "Огранований азсуніт", fen = "Suitable for putting into a ring.", fua = "Годиться для оздоблення персня." }
    t[137220] = { name = "Похід Легіону", fen = "From his seat upon the Throne of Kil'jaeden, Doom Lord Kazzak raised his sword and called the demonic army into battle.", fua = "Зі свого місця на Троні Кіл'джедена лорд погибелі Каззак здійняв меч і повів демонічну армію в бій." }
    t[137223] = { name = "Печатка некрофантазії", fen = "Dark whispers from the Twisting Nether suggest that this seal was forged by the Nathrezim before the Third War, and given to one of the scourge's most powerful lieutenants.", fua = "Темні шепоти з Викривленої Порожнечі натякають, що цю печатку викували натрезими ще до Третьої війни й віддали одному з найсильніших підручних Полчища." }
    t[137227] = { name = "Ка'пла, бойовий наказ ередунською", fen = "With this kill, we will be the victors.", fua = "Із цією смертю ми станемо переможцями." }
    t[137235] = { name = "Архана Тіґрід", fen = "A very old bag of arkhana, but its potency still seems good.", fua = "Дуже давня торбинка архани, та її сила, схоже, досі добра." }
