    t[138017] = { name = "Викрійка Скрині з Одягом: Опера Каражану", fen = "Teaches you how to craft a Clothes Chest: Karazhan Opera House.", fua = "Навчає вас виготовляти Скриню з Одягом: Опера Каражану." }
    t[138018] = { name = "Викрійка Скрині з Одягом: Вогняна Серцевина", fen = "Teaches you how to craft a Clothes Chest: Molten Core.", fua = "Навчає вас виготовляти Скриню з Одягом: Вогняна Серцевина." }
    t[138020] = { name = "М'ясисті Ребра Мускена", fen = "The best in vrykul barbeque.", fua = "Найкраще з вердзикулського барбекю." }
    t[138021] = { name = "Жмут Тонкої Козячої Шерсті", fen = "This would make a fine sweater.", fua = "З цього вийшов би гарний светр." }
    t[138022] = { name = "Дзьоб Злопера", fen = "This thing nearly took a finger off.", fua = "Ця штука мало не відірвала вам палець." }
    t[138023] = { name = "Щелепа Кам'янозуба", fen = "On closer inspection, the fangs are not actually made of stone.", fua = "Як придивитися, зуби насправді не з каменю." }
    t[138024] = { name = "Плавець Сталелуски", fen = "A fin this size could make quite a bit of soup.", fua = "З плавця такого розміру вийшло б чимало юшки." }
    t[138111] = { name = "Грозокований Гаковомет", fen = "Used to access grapple points throughout Stormheim.", fua = "Слугує для дістання гакових точок по всьому Штормгейму." }
    t[138112] = { name = "Череп Невинного", fen = "Powerful demonic rituals often call for the intact skull of a pure soul.", fua = "Потужні демонічні ритуали нерідко вимагають цілого черепа чистої душі." }
    t[138113] = { name = "Кров Невинного", fen = "Only the darkest magic requires the blood of the truly innocent.", fua = "Лише найтемніша магія потребує крові справді невинного." }
    t[138117] = { name = "Духовна Подорож", fen = "'In order to master the wolf, you must BECOME the wolf!' -Advice of a crazed Vrykul shaman", fua = "«Щоб опанувати вовка, треба САМОМУ СТАТИ вовком!» — порада навіженого шамана врайкулів" }
    t[138139] = { name = "Гримуар Таємних Шляхів", fen = "The magic knowledge contained in this book will enable Matron Mother Malevolence to pierce the holy barrier preventing teleportation into the Black Temple.", fua = "Магічні знання в цій книзі дозволять Матір-настоятельку Малеволенс пробити священну завісу, що перешкоджає телепортації до Чорного Храму." }
    t[138140] = { name = "Вигнанські Наручі Магтерідона", fen = "Using a Manticron Cube occasionally renders these useless.", fua = "Використання Куба Мантикрона часом робить їх непридатними." }
    t[138142] = { name = "Голова Оджин'би", fen = "The severed head of Ojin'ba, leader of the Witherbark Trolls.", fua = "Відрубана голова Оджин'би, ватажка тролів Зів'ялокорих." }
    t[138148] = { name = "Трол'Калар", fen = "The legendary blade of the Trollbane family, passed down for generations.", fua = "Легендарний клинок роду Троллбейнів, який передавали з покоління в покоління." }
    t[138149] = { name = "Прадавня Табличка з Дрейрґрота", fen = "The vrykul markings on this stone look like signs of warning.", fua = "Знаки врайкулів на цьому камені скидаються на застереження." }
    t[138150] = { name = "Рубіновий Амулет Зламозуба", fen = "The light refracting through the crystal gives it an almost liquid appearance.", fua = "Світло, заломлюючись у кристалі, надає йому майже рідкого вигляду." }
    t[138151] = { name = "Ящик Прадавніх Реліквій", fen = "Likely not worth much, but may contain a wealth of knowledge.", fua = "Навряд чи коштує багато, зате може містити справжній скарб знань." }
