    t[138242] = { name = "Заплямована Водою Колода Таро", fen = "Superstitious elves believed these cards could reveal the future.", fua = "Забобонні ельфи вірили, що ці карти можуть розкрити майбутнє." }
    t[138243] = { name = "З'їдений Іржею Меч", fen = "Only hints of ancient Azsharan craftsmanship remain.", fua = "Лишилися тільки натяки на прадавню азшарську майстерність." }
    t[138244] = { name = "Зіпсовані Самоцвіти Мани", fen = "The Legion's presence has tainted these 'snacks' favored by the Nightborne.", fua = "Присутність Легіону споганила ці 'ласощі', улюблені нічнонародженими." }
    t[138245] = { name = "Зіпсований Азшарський Бурдюк з Вином", fen = "A rare vintage left to age a bit too long.", fua = "Рідкісне вино, яке витримували трохи задовго." }
    t[138246] = { name = "Прадавній Маринований Короп", fen = "There's only one way to tell if this was pickled last year or 10,000 years ago, and opening the jar is best left to someone else.", fua = "Є лише один спосіб дізнатися, чи його замаринували торік, чи 10 000 років тому, і відкривати банку краще лишити комусь іншому." }
    t[138247] = { name = "Пошкоджена Арфа", fen = "The favored instrument of the Nightborne aristocracy, though easily ruined by rough handling.", fua = "Улюблений інструмент аристократії нічнонароджених, хоча його легко зіпсувати недбалим поводженням." }
    t[138248] = { name = "Важкий Тотем Бруля", fen = "The quality of this tiny statue's stonework belies the otherwise rough nature of the Drogbar.", fua = "Якість обробки каменю цієї крихітної статуї суперечить інакше грубій вдачі дроґбарів." }
    t[138249] = { name = "Зруйнована Книга Заклять", fen = "Time and the elements have erased any secrets once held by this tome.", fua = "Час і стихії стерли всі таємниці, які колись зберігав цей фоліант." }
    t[138250] = { name = "Статуя Королеви Азшари", fen = "A beautiful likeness of the Queen, this statue is centuries old.", fua = "Прекрасна подоба королеви, цій статуї багато сторіч." }
    t[138251] = { name = "Закам'яніле Драконяче Яйце", fen = "It's all but impossible to tell if this is a dragon egg snatched from a nest ages ago, or merely a carved replica.", fua = "Майже неможливо сказати, чи це драконяче яйце, викрадене з гнізда віки тому, чи лише різьблена копія." }
    t[138270] = { name = "Дуб Жахіття", fen = "Twisted and splintered, this small piece of wood is more resilient than it looks.", fua = "Покручений і потрісканий, цей маленький шматок дерева витриваліший, ніж здається." }
    t[138271] = { name = "Флакон Таємної Води", fen = "The water brightly swirls with arcane energies.", fua = "У воді яскраво вирують таємні енергії." }
    t[138273] = { name = "Лазурова Руда", fen = "Sometimes found when mining leystone, this ore can be used in weapon crafting by skilled smiths.", fua = "Іноді трапляється під час видобутку леїстону. Цю руду вмілі ковалі можуть використати для виготовлення зброї." }
    t[138274] = { name = "Ящик Лазурової Зброї", fen = "Filled with a collection of arrowheads, ammo, and spear tips crafted by Blacksmith Kyriel.", fua = "Наповнений колекцією наконечників стріл, набоїв і вістер списів, виготовлених ковалем Кірілем." }
    t[138296] = { name = "Різьблений Самоцвіт Зміїв Ненависті", fen = "A small carved gem, used as a magic focus.", fua = "Маленький різьблений самоцвіт, що править за магічний фокус." }
    t[138299] = { name = "Прадавні Кістки", fen = "Covered with dirt and the scent of decay.", fua = "Вкриті брудом та запахом тліну." }
    t[138307] = { name = "Зіпсований Смердючий Сир", fen = "It is unclear when this expired, but this wedge of cheese is definitely expired.", fua = "Незрозуміло, коли в нього вийшов термін, але цей шматок сиру однозначно зіпсувався." }
