    t[138397] = { name = "Саргеритовий Ключ", fen = "The power of Sargeras flows through this fel-corrupted titan device. It is a skeleton key to any and all Legion worlds, even Argus itself.", fua = "Крізь цей зіпсований Скверною пристрій титанів струмує сила Сарґераса. Це універсальний ключ до будь-якого світу Легіону, навіть до самого Аргуса." }
    t[138398] = { name = "Велетенська Азсунська Перлина", fen = "Light arcs within, like a storm in a cloud.", fua = "Усередині грають дуги світла, наче буря в хмарі." }
