    t[138419] = { name = "Пута Сплітача", fen = "Inscribed with magical runes whose ink glows with power.", fua = "Вкриті магічними рунами, чорнило яких сяє силою." }
    t[138420] = { name = "Викрадена Жила Еттіна", fen = "Ettin string is highly prized by condors as they require less materials for their nests.", fua = "Жилу еттіна високо цінують кондори, бо тоді їм потрібно менше матеріалів для гнізд." }
