    t[138422] = "Гнівоткач"
    t[138432] = { name = "Зброя Сутінкової Варти", fen = "Kept sharp by arcane magics.", fua = "Залишається гострою завдяки таємній магії." }
    t[138435] = { name = "Плекана Манаквітка", fen = "Meticulously cultivated for thousands of years.", fua = "Дбайливо плекана впродовж тисяч років." }
    t[138450] = { name = "Перстень-Печатка Стормвінду", fen = "Granted to heroes of the Alliance shipping out to the battle of the Broken Shore.", fua = "Надається героям Альянсу, що вирушають на битву за Розколотий Берег." }
    t[138451] = { name = "Креслення: Смертоносний Глибинний Бурштин", fen = "Teaches you how to cut a Deadly Deep Amber.", fua = "Навчає вас гранити Смертоносний Глибинний Бурштин." }
    t[138452] = { name = "Креслення: Швидкий Азсуніт", fen = "Teaches you how to cut a Quick Azsunite.", fua = "Навчає вас гранити Швидкий Азсуніт." }
    t[138453] = { name = "Креслення: Майстерний Опал Королеви", fen = "Teaches you how to cut a Masterful Queen's Opal.", fua = "Навчає вас гранити Майстерний Опал Королеви." }
    t[138454] = { name = "Креслення: Смертоносне Око Пророцтва", fen = "Teaches you how to cut a Deadly Eye of Prophecy.", fua = "Навчає вас гранити Смертоносне Око Пророцтва." }
    t[138455] = { name = "Креслення: Швидке Світанкове Сяйво", fen = "Teaches you how to cut a Quick Dawnlight.", fua = "Навчає вас гранити Швидке Світанкове Сяйво." }
    t[138456] = { name = "Креслення: Майстерний Тіньорубін", fen = "Teaches you how to cut a Masterful Shadowruby.", fua = "Навчає вас гранити Майстерний Тіньорубін." }
    t[138469] = "Скриня Чемпіона"
    t[138474] = "Скриня Чемпіона"
    t[138477] = { name = "Осердя Чистої Води", fen = "The corruption had not yet spread to it when it was removed.", fua = "Псування ще не торкнулося його, коли його вийняли." }
    t[138480] = { name = "Фоліант Чорного Жнива", fen = "A musty tome, its pages are covered with a scribblings in an ancient language.", fua = "Затхлий фоліант, сторінки якого вкриті писаниною давньою мовою." }
    t[138482] = { name = "Велична Душа", fen = "Collect enough to power the Fel Hammer's jump engines.", fua = "Зберіть достатньо, щоб живити стрибкові двигуни Скверномолота." }
    t[138483] = { name = "Інжектор Скверного Двигуна", fen = "Yes, but what exactly is it injecting?", fua = "Так, але що саме він упорскує?" }
