    t[138485] = { name = "Перетворювач Мерзенних Духів", fen = "Whatever this things does, it's not good. At least it only does it to vile spirits. Or, so the name says.", fua = "Хоч що ця штука робить, нічого доброго в цьому нема. Принаймні робить вона це лише з мерзенними духами. Чи так каже назва." }
