    t[139396] = { name = "Ревербієва Галька", fen = "A new mineral that is nigh indestructible! If only we had enough to do something with it, like make a shield...", fua = "Новий мінерал, майже незнищенний! Якби ж нам його вистачило, щоб щось із нього зробити, наприклад щит..." }
    t[139397] = { name = "Мертвий Тягар", fen = "Super dense, it weighs a lot, but it is also starting to smell.", fua = "Надзвичайно щільний, важить чимало, та ще й починає тхнути." }
    t[139398] = { name = "Штани-Буханець", fen = "Laid out nicely it 'looks' like a pair of pants. Plus if Alchemy doesn't pan out...", fua = "Якщо гарно розкласти, це 'схоже' на штани. До того ж, якщо з алхімією не вийде..." }
    t[139399] = { name = "Драглиста Грудка", fen = "Floating chunks of metal, fur and teeth are suspended in the Ooze.", fua = "Уламки металу, шерсть і зуби плавають у слизу." }
    t[139404] = { name = "Запалювання Скверномотора", fen = "Sounds very important. Hopefully, Jace will know what to do with it.", fua = "Звучить дуже важливо. Сподіваймося, Джейс знатиме, що з цим робити." }
