    t[139465] = { name = "Настоянка Демонічної Крові", fen = "The liquid bubbles and seethes as if alive.", fua = "Рідина булькає й вирує, неначе жива." }
    t[139466] = { name = "Пута Володаря Вітрів", fen = "The left half of a prison intended for Thunderaan the Windlord.", fua = "Ліва половина в'язниці, призначеної для Тандераана Володаря Вітрів." }
    t[139468] = { name = "Пута Володаря Вітрів", fen = "The right half of a prison intended for Thunderaan the Windlord.", fua = "Права половина в'язниці, призначеної для Тандераана, Володаря вітрів." }
    t[139469] = "Сутність Лютості"
    t[139471] = { name = "Послання Блек-Рук", fen = "Lord Ravencrest, the Legion accepts your terms. The reinforcements will arrive as expected. Be sure to honor your side of this agreement.", fua = "Лорде Рейвенкрест, Легіон приймає ваші умови. Підкріплення прибуде, як і домовлено. Подбайте, щоб ви теж дотрималися своєї частини угоди." }
    t[139472] = { name = "Запрошення на Розкішну Гулянку", fen = "You are cordially invited to the Jeweled Estate, where we will enjoy delectable treats and drinks, and may have a surprise guest...", fua = "Ласкаво запрошуємо вас до Самоцвітного Маєтку, де ми насолоджуватимемося смаковитими ласощами й напоями, а може, навіть зустрінемо несподіваного гостя..." }
    t[139473] = { name = "Флакон Отруєної Крові", fen = "Blood taken from an unfortunate, corrupted creature within Darkheart Thicket.", fua = "Кров, узята в нещасної спотвореної істоти в Хащі Темносердя." }
    t[139474] = { name = "Різьблена Мушля", fen = "Holding it to your ear, you can hear a distant, malevolent voice.", fua = "Притуливши її до вуха, ви чуєте далекий лиховісний голос." }
    t[139475] = { name = "Розмоклий Лист", fen = "My beloved, I fear that my evil deeds have finally caught up to me, and I face an eternity in the underworld, sailing the seas at the mercy of Helya. Do not forget about me.", fua = "Кохана моя, боюся, мої лихі вчинки врешті наздогнали мене, і на мене чекає вічність у потойбіччі, де я блукатиму морями з ласки Гелії. Не забувай про мене." }
    t[139476] = { name = "Зламана Драконяча Луска", fen = "The drogbar kept it in a place of privilege, reminding themselves of the power that Deathwing once had.", fua = "Дроґбари тримали її на почесному місці, нагадуючи собі про могутність, яку колись мав Дезвінг." }
    t[139477] = { name = "Вичерпана Куля Мани", fen = "Once teeming with energy, the mana from this orb has been completely consumed.", fua = "Колись повна енергії, мана цієї кулі тепер вичерпана дощенту." }
