    t[140317] = { name = "Зламана Тарілка Лей-Радара", fen = "This seems like an important component.", fua = "Схоже, це важлива складова." }
    t[140318] = { name = "Уламок Живлення Лей-Лінії", fen = "They pulse in synchrony with the larger column.", fua = "Вони пульсують у такт з більшою колоною." }
    t[140322] = "Прозріння Наставника"
    t[140324] = "Мобільний Телемантичний Маяк"
    t[140325] = "Саморобна Святкова Маска"
    t[140336] = "Ідол Брулфіста"
    t[140337] = { name = "Імпортована Жорстка В'ялена М'ясивина", fen = "The excessive use of a salt makes this extremely popular in the small country towns of Azeroth.", fua = "Через щедру кількість солі вона дуже популярна в маленьких сільських містечках Азероту." }
    t[140341] = { name = "Дикий Імператорський Лосось у Воді", fen = "From the waters far to the north.", fua = "З вод далекої півночі." }
    t[140347] = "Духові Ягоди"
    t[140349] = "Запасний Чародійний Оберіг"
    t[140351] = "Сонячний Плід"
    t[140356] = { name = "Демонічні Карлючки", fen = "The handwriting is illegible even by the standards of demons.", fua = "Почерк нерозбірливий навіть за демонічними мірками." }
    t[140357] = { name = "Камінь Лави Скверни", fen = "It's always a little bit warm.", fua = "Він завжди трохи теплий." }
    t[140358] = { name = "Застібка Обладунку Ередарів", fen = "It appears to be well-maintained, until recently.", fua = "Схоже, до нещодавнього часу за нею добре доглядали." }
    t[140359] = { name = "Затемнене Очне Яблуко", fen = "One Eye of Zoth wasn't avoided, and was taken care of a different way.", fua = "Одного Ока Зота не вдалося уникнути, тож із ним розібралися інакше." }
    t[140360] = { name = "Шпичак Скелевірма", fen = "It isn't terribly sharp, but is strong enough to cut through stone.", fua = "Не надто гострий, але достатньо міцний, щоб різати камінь." }
    t[140361] = { name = "Пульсівний Рунний Камінь", fen = "It doesn't have any magic left in it, but it hums rather nicely.", fua = "Магії в ньому вже не лишилося, проте він доволі приємно гуде." }
    t[140362] = { name = "Пил із Тіньових Земель", fen = "Though it does not possess any power, an otherwordly feel permeates this powder.", fua = "Хоч він і не має жодної сили, цей порошок просякнутий потойбічним відчуттям." }
    t[140363] = { name = "Кишеньковий Розсіювач Скверни", fen = "Not actually a good idea to leave in your pocket.", fua = "Тримати таке в кишені — не найкраща ідея." }
    t[140364] = { name = "Уламок Кістки Крижаного Вірма", fen = "Still humming with power, this must have broken off while flying over Icecrown.", fua = "Усе ще гуде від сили - мабуть, відколовся під час польоту над Крижаною Короною." }
    t[140365] = { name = "Засушена Лілія зі Стратгольма", fen = "Once, they bloomed all over Lordaeron. Someone cared enough to preserve a few petals in a book.", fua = "Колись вони квітнули по всьому Лордеронові. Хтось любив їх настільки, щоб зберегти кілька пелюсток у книзі." }
    t[140366] = { name = "Багряний Збірник Гімнів", fen = "A collection of hymns to the Light, collected and arranged by the Scarlet Crusade.", fua = "Збірка гімнів Світлу, зібрана й упорядкована Багряним Хрестовим Походом." }
    t[140367] = { name = "Подерті Ноти", fen = "For those musically inclined, it appears to be the accompaniment to \"Romulo and Julianne.\"", fua = "Для тих, хто тямить у музиці, це, схоже, акомпанемент до \"Ромуло й Джуліанни\"." }
    t[140368] = { name = "Потьмянілий Заручний Перстень", fen = "Death took it all away.", fua = "Смерть забрала геть усе." }
    t[140369] = { name = "Нашкрябаний Рецепт", fen = "It appears to be a recipe for a refreshing mint julep. Or the plague to end all life on Azeroth. Maybe both.", fua = "Схоже, це рецепт освіжного м'ятного коктейлю. Або чуми, що покладе край усьому життю на Азероті. Можливо, і те, й інше." }
    t[140370] = { name = "Скалка Бурштину", fen = "A tiny insect is trapped inside.", fua = "Усередині застрягла крихітна комаха." }
    t[140371] = { name = "Лист від Екзарха Маладаара", fen = "The letter begins, \"Dear Nyami, It is with regret that I must tell you that your son is among those kidnapped by the orcs. We fear the worst.\"", fua = "Лист починається словами: \"Люба Найямі, з прикрістю мушу сповістити Вас, що Ваш син серед тих, кого викрали орки. Ми боїмося найгіршого.\"" }
    t[140372] = "Маніпулятор Прадавнього Артифісера"
    t[140373] = { name = "Оздоблений Ремінець Чобота", fen = "It appears to have broken off at some point from what once were very nice boots.", fua = "Схоже, він колись відірвався від того, що було дуже гарними чобітьми." }
    t[140374] = { name = "Зазубрене Ікло Воргена", fen = "It's unclear who it once belonged to, but it's long and menacing.", fua = "Незрозуміло, кому воно колись належало, але воно довге й грізне." }
    t[140375] = { name = "Вживані Клинки Скверни", fen = "The previous owner won't be needing them anymore.", fua = "Попередній власник вони вже не знадобляться." }
    t[140376] = { name = "Налаштований під Мардум Балансир", fen = "Attuned for the unique properties of living on Mardum.", fua = "Пристосований до унікальних умов життя на Мардумі." }
    t[140377] = { name = "Зламаний Медальйон Карабора", fen = "Once belonging to a priest of Karabor, it's seen better days.", fua = "Колись належав жерцю Карабора й бачив кращі часи." }
    t[140378] = { name = "Аріана Полум'яне Серце", fen = "Allows you to recruit Illidari Adepts.", fua = "Дозволяє вам набирати адептів іллідарі." }
    t[140379] = { name = "Зламаний Клинок Глефи Вартової", fen = "A great deal of force was required to snap the blade.", fua = "Щоб переламати клинок, знадобилася неабияка сила." }
    t[140380] = { name = "Хвостова Пір'їна Бистрокрила", fen = "The plumage is vibrant shades of blue and purple.", fua = "Оперення яскраво виграє відтінками синього й фіолетового." }
    t[140381] = { name = "Перстень і Палець Ярла з Яндвіка", fen = "The ring pulses with ancient power and holds tightly onto the stump.", fua = "Перстень пульсує прадавньою силою й міцно тримається на оцупку." }
    t[140382] = { name = "Крихітний Бойовий Барабан", fen = "Far too small for a full-grown Feltotem.", fua = "Надто малий для дорослого Скверно-тотема." }
    t[140383] = { name = "Сяйливий Печерний Гриб", fen = "It's been nibbled on.", fua = "Його вже понадгризали." }
    t[140384] = { name = "Скіпетр Двору Азшари", fen = "Entrusted to advisors of the Queen.", fua = "Довірявся радникам Королеви." }
    t[140385] = { name = "Памфлет Легіону", fen = "It's been folded and re-folded so many times, the writing is almost unreadable.", fua = "Його згортали й розгортали стільки разів, що текст майже неможливо прочитати." }
    t[140386] = "Тіньова Сфера Інквізитора"
    t[140387] = { name = "Самоцвіт для Наручів", fen = "Even Imp Mothers know the value of tasteful accessories.", fua = "Навіть матінки бісенят знають ціну вишуканим прикрасам." }
    t[140388] = { name = "Самоцвіт Фаланаара", fen = "Shiny and bright, Oreth has kept his precious stone close.", fua = "Блискучий і яскравий - Орет тримав цей коштовний камінь при собі." }
    t[140389] = { name = "Скам'яніле Полум'я", fen = "The stone flickers every now and then, as though still burning inside.", fua = "Камінь час від часу спалахує, наче всередині досі палає вогонь." }
    t[140390] = { name = "Червоне Яйце Ор'лігай", fen = "Created by the artisan Or'ligai for the High Magistrix, the eggs were lost while being delivered to the palace.", fua = "Створені майстром Ор'лігай для Верховної Магістрикс, ці яйця загубилися дорогою до палацу." }
    t[140391] = { name = "Аргуський Діамант", fen = "Carried for thousands of years and polished to a shine.", fua = "Його носили тисячі років і відполірували до блиску." }
    t[140392] = { name = "Запобіжний Клапан", fen = "Never installed.", fua = "Так і не встановлений." }
    t[140393] = { name = "Батіг Репентії", fen = "Well worn from use.", fua = "Добряче зношений від використання." }
    t[140396] = { name = "Ставка Дружнього Забіяки", fen = "One enchanted coin to the winner.", fua = "Переможцю - одна зачарована монета." }
    t[140399] = { name = "Жовте Яйце Ор'лігай", fen = "Created by the artisan Or'ligai for the High Magistrix, the eggs were lost while being delivered to the palace.", fua = "Створені майстром Ор'лігай для Верховної Магістрикс, ці яйця загубилися дорогою до палацу." }
    t[140400] = { name = "Бездоганна Квітка Снового Гаю", fen = "The petals are all perfectly intact.", fua = "Усі пелюстки цілісінькі." }
    t[140401] = { name = "Синє Яйце Ор'лігай", fen = "Created by the artisan Or'ligai for the High Magistrix, the eggs were lost while being delivered to the palace.", fua = "Створені майстром Ор'лігай для Верховної Магістрикс, ці яйця загубилися дорогою до палацу." }
    t[140402] = { name = "Зелене Яйце Ор'лігай", fen = "Pinchshank thought he was ready to protect his egg.", fua = "Тискогомілка думав, що готовий захистити своє яйце." }
    t[140403] = "Скверний Кристал Лайландре"
    t[140404] = "Ціле Ядро Вартового"
    t[140405] = "Кристал Матриці Ілюзій"
    t[140406] = "Споряджений Чаротворний Заряд"
    t[140409] = { name = "Фоліант Вимірного Усвідомлення", fen = "You were wise to grab this book. It has absorbed immense knowledge resting in the Arcway all these years.", fua = "Ви вчинили мудро, прихопивши цю книгу. За всі ці роки вона ввібрала величезні знання, що зберігалися в Аркусі." }
    t[140410] = { name = "Знак Розбійників", fen = "It seems you did make your mark. Arluin passed this enchanted coin along to aid you.", fua = "Схоже, ви таки лишили свій слід. Арлуїн передав вам цю зачаровану монету на допомогу." }
    t[140411] = "Ясність Переконання"
    t[140412] = "Реактивна Інтуїція"
    t[140413] = "Моторошний Сувенір"
    t[140414] = { name = "Гральні Кості з Лиховійною Силою", fen = "Definitely not possessed by minor demons.", fua = "Точно не одержимі дрібними демонами." }
    t[140415] = "Полум'я Слави"
    t[140416] = "Сумління Переможців"
    t[140417] = "Загартований у Бою Ефес"
    t[140418] = { name = "«Позичена» Сутність Душі", fen = "As if you have any plans of giving it back.", fua = "Наче ви взагалі збираєтеся її повертати." }
    t[140419] = { name = "Раптовий Підступ", fen = "The king of the hill casts the tallest shadow.", fua = "Король пагорба відкидає найдовшу тінь." }
    t[140420] = "Нищівна Буря"
    t[140421] = { name = "Прадавній Ідол Кіраджі", fen = "It was rumored that this idol was the prized possession of Duke Stelleris. It appears that someone who knew he wouldn't be home relieved him of it.", fua = "Подейкували, що цей ідол був найціннішим скарбом герцога Стеллеріса. Схоже, хтось, знаючи, що його не буде вдома, позбавив його цього майна." }
    t[140422] = { name = "Ідол Місячного Сяйва", fen = "From Ly'leth's private collection. It glows with the blessing of Elune.", fua = "З приватної колекції Лілет. Сяє благословенням Елуни." }
    t[140423] = "Ретельне Дослідження"
    t[140424] = "Заборонені Знання"
    t[140425] = "Спраглий Кровокамінь"
    t[140426] = "Шал Бою"
    t[140427] = "Дивовижа для Посилення"
    t[140428] = "Союз із розрахунку"
    t[140429] = "Полум'я Полеглих"
    t[140430] = "Смолоскип Змагання"
    t[140431] = "Зневага Вищості"
    t[140432] = "Холодний Піт"
    t[140433] = "Осяйний Сонячний Камінь"
    t[140434] = "Сяйво Світанку"
    t[140435] = "Непохитна Завзятість"
    t[140436] = "Непохитне Переконання"
    t[140437] = "Цвіт Могильного Бур'яну"
    t[140438] = "Великий Палець Скам'янілого Прадавнього"
    t[140440] = "Полірований Тінекамінь"
    t[140441] = "Оповідь Мерця"
    t[140442] = "Громовий Удар"
    t[140443] = "Рев Натовпу"
    t[140444] = { name = "Сльоза Сну", fen = "From the essence, a single Dream Tear also falls.", fua = "З сутності спадає й одна-єдина Сльоза Сну." }
    t[140445] = "Аркоплід"
    t[140458] = { name = "Насінина Батожника", fen = "It's the color of dried blood, and prickly.", fua = "Кольору засохлої крові й колюча." }
    t[140459] = { name = "Місячна Лілія", fen = "A thank-you gift from one of the priestesses at the temple.", fua = "Подарунок на знак подяки від однієї зі жриць храму." }
    t[140460] = { name = "Бойові Пазурі Тісалі", fen = "They're sharp enough to cut through sea giant flesh, and apparently did.", fua = "Достатньо гострі, щоб розтяти плоть морського велета, що, схоже, і сталося." }
    t[140461] = { name = "Понівечена Трофейна Відзнака", fen = "The harpies dragged it back to their nest as treasure many years ago. The inscriptions have long since worn off.", fua = "Багато років тому гарпії притягли її до свого гнізда як скарб. Написи вже давно стерлися." }
    t[140462] = { name = "Шпори Приборкувача Дрейків", fen = "Cruel and sharp, they only fit vrykul-sized boots.", fua = "Жорстокі й гострі, вони підходять лише до чобіт розміру врайкулів." }
    t[140463] = { name = "Зламаний Клинок Ередарів", fen = "The material is not as high quality as one might expect.", fua = "Матеріал не такий якісний, як можна було б очікувати." }
    t[140464] = { name = "Мініатюрний Тотем", fen = "Crudely whittled, it may have been made by a child.", fua = "Грубо вистругано - можливо, його зробила дитина." }
    t[140465] = { name = "Шкура Сутінкошкурого", fen = "Even the most rigorous treatment wouldn't make it any softer.", fua = "Навіть найретельніша обробка не зробить її м'якшою." }
    t[140466] = { name = "Роз'їдена Етерніумна Троянда", fen = "Someone threw this into the sewers, and the chemicals damaged it badly.", fua = "Хтось викинув її в каналізацію, і хімікати добряче її пошкодили." }
    t[140467] = { name = "Просякнутий Скверною Панцир", fen = "Fel magic melted right into the shell of the poor, deceased creature that once lived inside.", fua = "Магія скверни вплавилася просто в панцир бідолашного загиблого створіння, що колись жило всередині." }
    t[140468] = { name = "Уламок Шкаралупи Орлиного Яйця", fen = "It was broken a long time ago, but was once massive.", fua = "Розбилося давним-давно, але колись було величезним." }
    t[140469] = { name = "Наконечник Стріли зі Скверносланцю", fen = "Someone tried to shoot back. Key word: tried.", fua = "Хтось намагався відстрілюватися. Ключове слово: намагався." }
    t[140470] = { name = "Прадавній Ґілнеаський Медальйон", fen = "From a time long past, before the curse and the wall.", fua = "З давно минулих часів, ще до прокляття й стіни." }
    t[140471] = { name = "Реліквія Лорда Шалзару", fen = "Once the property of Naga royalty, discovered below the waves off the coast of Azsuna.", fua = "Колись належала назькій знаті, знайдена під хвилями біля узбережжя Азсуни." }
    t[140472] = { name = "Прадавній Фоліант Нічнонароджених", fen = "The language is so archaic, only the oldest elves might be able to read it.", fua = "Мова така архаїчна, що прочитати її здатні хіба що найстаріші ельфи." }
    t[140473] = { name = "Викувана Ніччю Алебарда", fen = "Not a delicate or subtle weapon.", fua = "Не вишукана й не витончена зброя." }
    t[140474] = { name = "Уламок Кераміки з Нар'таласа", fen = "Once a fine work of art before being shattered decades ago.", fua = "Колись витвір мистецтва, поки десятиліття тому його не розбили." }
    t[140475] = { name = "Лоза Іпомеї", fen = "This weed grows throughout the ruined sections of Suramar.", fua = "Цей бур'ян розрісся по всіх зруйнованих кварталах Сурамара." }
    t[140476] = { name = "Глобус з Астранаара", fen = "Broken at some point during the siege by the orcs, it no longer spins.", fua = "Розбитий під час облоги орками, він більше не обертається." }
    t[140477] = { name = "Безживний Попіл", fen = "Not everyone survived Archmage Khadgar's trials on Draenor.", fua = "Не всі пережили випробування архімага Хадґара на Дреноре." }
    t[140478] = { name = "Розмальована Кора", fen = "Life is a magical thing.", fua = "Життя - це чарівна річ." }
    t[140479] = { name = "Зламаний Комунікатор Легіону", fen = "It plays the same angry-sounding message over and over.", fua = "Знову й знову програє те саме сповнене люті повідомлення." }
    t[140480] = { name = "Виснажене Ядро Конструкта", fen = "It once powered a Nightborne Construct. Now it is only a pretty paperweight.", fua = "Колись живило конструкта нічнонароджених. Тепер це лише гарне прес-пап'є." }
    t[140481] = { name = "Мерехтливий Пісковий Годинник", fen = "Keeps very precise time - for someplace else entirely.", fua = "Веде час дуже точно - тільки для зовсім іншого місця." }
    t[140482] = { name = "Ікло Штормового Дрейка", fen = "It's enormous, sharp, and contains no magic whatsoever. How disappointingly prosaic.", fua = "Воно величезне, гостре й геть позбавлене магії. Аж розчаровує своєю буденністю." }
    t[140483] = { name = "Уламок Нефриту", fen = "Once a piece of a small serpent figurine.", fua = "Колись був частиною маленької фігурки змії." }
    t[140484] = { name = "Добряче Вживаний Ріг для Питва", fen = "It still smells of several kinds of brew.", fua = "Усе ще пахне кількома сортами хмільного." }
    t[140485] = { name = "Ікло Сутінкошкурого", fen = "Slightly chipped.", fua = "Трохи надщерблене." }
    t[140486] = { name = "Луска Штормового Дрейка", fen = "One of the soft, shiny underbelly scales.", fua = "Одна з м'яких блискучих лусочок із черева." }
    t[140487] = { name = "Пошкоджений у Бою Шолом Врайкулів", fen = "A large piece of the face guard is missing.", fua = "Великого шматка забрала бракує." }
    t[140488] = { name = "Велетенський Ковальський Молот", fen = "It's too large for a normal blacksmith.", fua = "Завеликий для звичайного коваля." }
    t[140489] = { name = "Перстень з Пальця Еттіна", fen = "It could be used as a belt if not for the unbearable stench.", fua = "Міг би правити за пояс, якби не нестерпний сморід." }
    t[140490] = { name = "Дерев'яні Снігоступи", fen = "The Highmountain thought they were too small to use in the snow.", fua = "Високогірні таурени вважали їх замалими, щоб ходити по снігу." }
    t[140491] = { name = "Викрадений Перлинний Перстень", fen = "The harpies stole it and stuffed it under a nest.", fua = "Гарпії викрали його й запхали під гніздо." }
    t[140492] = { name = "Осяйний Льодовиковий Камінець", fen = "Rubbed smooth by tons of ice and the passage of time.", fua = "Відполірований тоннами криги та плином часу." }
    t[140493] = { name = "Посібник Адепта з Вимірних Розломів", fen = "This advanced guide allows access to the wider Ley Lines of the Broken Isles.", fua = "Цей просунутий посібник відкриває доступ до ширших Силових Ліній Зламаних Островів." }
    t[140494] = { name = "Хвостова Манжета Ередарів", fen = "The more decorative the cuff, the more prestigious the individual.", fua = "Що оздобленіша манжета, то поважніша особа." }
    t[140495] = { name = "Розірване Запрошення", fen = "Clearly an invitation to an exclusive Nightborne noble event.", fua = "Вочевидь, запрошення на ексклюзивний захід вельмож нічнороджених." }
    t[140496] = { name = "Запрошення на Полювання на Лиса", fen = "Further pieces of the puzzle.", fua = "Нові частини головоломки." }
    t[140497] = { name = "В'язка Крихітних Списів", fen = "Individually they are no more dangerous than a sewing needle. A score of them could do some serious damage.", fua = "Поодинці вони не небезпечніші за швацьку голку. Та десятки таких можуть завдати серйозної шкоди." }
    t[140498] = { name = "Записка Прихильника Легіону", fen = "While undercover, someone passed this note expressing admiration.", fua = "Під прикриттям хтось передав цю записку, висловлюючи захоплення." }
    t[140499] = { name = "Дивнобарвний Камінь Скверни", fen = "Still warm to the touch.", fua = "Досі теплий на дотик." }
    t[140501] = { name = "Застарілі Розвіддані", fen = "At one point this would have been valuable information, a clerical error means it is now worthless.", fua = "Колись це були б цінні відомості, та через канцелярську помилку вони тепер нічого не варті." }
    t[140502] = { name = "Подерта Пов'язка на Око", fen = "The former owner doesn't need it any more.", fua = "Колишньому власнику вона більше не потрібна." }
    t[140503] = { name = "Чистий Список Справ", fen = "Hidden writing appears when this paper is left in the sun.", fua = "Прихований напис проявляється, коли цей папір лишити на сонці." }
    t[140504] = { name = "Якірний Линв Квалдирів", fen = "Heavy, crude, and covered in marine life.", fua = "Важкий, грубий і вкритий морською живністю." }
    t[140505] = { name = "Спітніла Бандана", fen = "A poor facsimile of a pirate's swagger.", fua = "Жалюгідне наслідування піратської удалі." }
    t[140507] = { name = "Зілля без Етикетки", fen = "It's probably best not to drink it.", fua = "Краще його не пити." }
    t[140508] = { name = "Перстень Майстра Нічнороджених", fen = "It contains no magic, but glitters even in the absence of light.", fua = "Магії в ньому немає, але він мерехтить навіть без світла." }
    t[140509] = { name = "Демонічна Мазанина", fen = "It seems a lesser demon tried to sketch the landscape. Maybe it's an abstract doodle?", fua = "Схоже, нижчий демон намагався зобразити краєвид. А може, це абстрактна каракуля?" }
    t[140510] = { name = "Залізний Ключ від Блек-Рук-Голд", fen = "Fits no lock you can find.", fua = "Не пасує до жодного замка, який ви можете знайти." }
    t[140511] = { name = "Кайдани Душі", fen = "Whatever this binding once restrained is long gone.", fua = "Хоч би що ці пута колись утримували, воно давно зникло." }
    t[140512] = { name = "Велетенський Кухоль", fen = "It's three times the normal size even by vrykul standards and has an otherworldly glow.", fua = "Він утричі більший за звичайний навіть за мірками вікулів і має потойбічне сяйво." }
    t[140513] = { name = "Похвальний Знак Жахолорда", fen = "For nefarious deeds perpetrated by the Legion on other worlds.", fua = "За мерзенні діяння, скоєні Легіоном на інших світах." }
    t[140514] = { name = "Флакон Повітря", fen = "It appears empty, but is it? Is anything truly empty?", fua = "Здається порожнім, але чи так це? Чи буває щось справді порожнім?" }
    t[140515] = { name = "Дарунок Аль'Акіра", fen = "For Mistius' loyalty over the years. It's unclear where the lieutenant kept it.", fua = "За багаторічну вірність Містіуса. Невідомо, де лейтенант його зберігав." }
    t[140516] = { name = "Стихійні Наручі", fen = "Purely decorative.", fua = "Суто декоративні." }
    t[140517] = "Слава Ордену"
    t[140518] = { name = "Блискавка в Пляшці", fen = "The label reads, \"Caution: Do not open on a clear day.\"", fua = "На етикетці написано: «Обережно: не відкривати в ясну погоду»." }
    t[140519] = { name = "Шепітливий Тотем", fen = "It may be a totem of air, or it might be haunted.", fua = "Може, це тотем повітря, а може, він проклятий." }
    t[140520] = { name = "Аметистова Жеода", fen = "Completely inert, the gems inside are still very pretty.", fua = "Цілком неактивна, та самоцвіти всередині все одно дуже гарні." }
    t[140521] = { name = "Уламок Панцира Вогняної Черепахи", fen = "Still hot to the touch, and as heavy as obsidian.", fua = "Досі гарячий на дотик і важкий, мов обсидіан." }
    t[140522] = { name = "Скам'яніле Павутиння", fen = "Very brittle.", fua = "Дуже крихке." }
    t[140523] = { name = "Багряний Печерний Гриб", fen = "Red and pulsing, and probably not edible.", fua = "Червоний і пульсуючий, та, мабуть, неїстівний." }
    t[140524] = { name = "Гострий Сутінковий Зуб", fen = "Broken off during the battle.", fua = "Відламаний під час битви." }
    t[140525] = { name = "Обсидіанове Дзеркало", fen = "Your reflection appears warped in a manner you can't quite describe.", fua = "Ваше відображення спотворене так, що ви й описати не можете." }
    t[140526] = { name = "Перстень-Печатка Ередарів", fen = "It's at least several hundred years old, but contains no magic.", fua = "Йому щонайменше кілька сотень років, але магії в ньому немає." }
    t[140527] = { name = "Медальйон Гнівоварта", fen = "Earned from a battle on a long-forgotten world.", fua = "Здобутий у битві на давно забутому світі." }
    t[140528] = { name = "Даларанський Винний Келих", fen = "Has a fruity aroma.", fua = "Має фруктовий аромат." }
    t[140529] = { name = "Кільце Скверноловця", fen = "The more rings they have in their manes, the older they are.", fua = "Що більше кілець у їхніх гривах, то старіші вони." }
    t[140530] = { name = "Опалесцентна Мушля", fen = "Obtained via an opportunistic round of beach-combing.", fua = "Здобута під час вдалого прочісування пляжу." }
    t[140531] = { name = "Родова Печатка Рейвенкрестів", fen = "Discovered on a gravestone.", fua = "Знайдена на надгробку." }
    t[140532] = { name = "Карбований Рунний Камінь Вікулів", fen = "Carved with a great deal of care, the stone is cold to the touch.", fua = "Вирізьблений із великою старанністю, камінь холодний на дотик." }
