    t[140635] = { name = "Визначні Старожитності Прадавнього Азероту", fen = "The binding is worn, but the book radiates power. Its author's name is scribed in glowing letters: 'Alodi'.", fua = "Палітурка зношена, але книга випромінює силу. Ім'я її автора виписано осяйними літерами: «Алоді»." }
