    t[141672] = { name = "Відзнака Командира Нічнонароджених", fen = "Adorning Domitille's helm, the gem contains swirling essence just beyond its face, almost as if the waters of the Nightwell were slowed to craft the gem.", fua = "Цей самоцвіт, що оздоблював шолом Домітилль, береже вируючу сутність попід своєю поверхнею, наче води Нічної Криниці вповільнили, аби його витворити." }
    t[141673] = { name = "Сповнена Любов'ю Стріла", fen = "With Latara's release at long last a great power enveloped one of the arrows left in her quiver.", fua = "Коли Латару нарешті визволили, велика сила огорнула одну зі стріл, що лишилися в її сагайдаку." }
    t[141674] = { name = "Тавро Кровного Брата", fen = "The enchanted blood pulses on the stone tablet waiting to be unleashed.", fua = "Зачарована кров пульсує на кам'яній табличці, чекаючи, доки її вивільнять." }
