    t[141678] = { name = "Нічний Щоденник: Досконалість Арквина", fen = "Containing the secrets to perfecting Arcwine, this simple looking tome has absorbed an immense amount of residual power being at the heart of the Nightwell operations.", fua = "Цей скромний на вигляд фоліант містить таємниці вдосконалення арквина і, перебуваючи в осерді всіх дій Нічного Криниці, увібрав величезну кількість залишкової сили." }
