    t[142535] = { name = "Душолов Навального Туману", fen = "Grasping a soul just as it passes the threshold is a despicable act, made even worse with powerful talismans.", fua = "Схопити душу саме тоді, коли вона переступає поріг, — мерзенний учинок, ще ганебніший із застосуванням могутніх талісманів." }
