    t[143330] = { name = "Підвіска Зі Скверного Каменя", fen = "The gem at the center glows with fel energy.", fua = "Самоцвіт у центрі сяє скверною енергією." }
    t[143331] = { name = "Щоденник Неруса", fen = "The text on these tattered and torn pages was penned long ago by Nerus Moonfang.", fua = "Текст на цих пошарпаних і подертих сторінках давним-давно написав Нерус Місячне Ікло." }
    t[143332] = { name = "Чистий Сувій", fen = "Otherwise blank, a small crescent moon is the only recognizable symbol on the scroll.", fua = "В усьому іншому чистий, цей сувій має єдиний помітний символ — маленький півмісяць." }
    t[143333] = { name = "Відзнака Помсти", fen = "A powerful token that Silgryn has held on to from before the shield went up.", fua = "Потужний знак, який Сілґрін зберігає ще з часів до того, як піднявся бар'єр." }
