    t[143478] = { name = "Запрошення на Арену", fen = "A carefully handwritten note, penned in the blood of the fallen.", fua = "Ретельно написана від руки нотатка, виведена кров'ю полеглих." }
    t[143479] = { name = "Подертий Стяг", fen = "Blood-stained and torn, which simply adds to its splendor.", fua = "Заплямований кров'ю та роздертий, що лише додає йому величі." }
    t[143486] = { name = "Бар'єр Дугоплавця", fen = "The Arcshaper fashioned the crystal well. The power, while it can be suppressed, will always remain strong.", fua = "Дугоплавець майстерно вигранив цей кристал. Його силу можна приборкати, але вона завжди лишатиметься потужною." }
    t[143487] = { name = "Зачарована Сутінкова Лілія", fen = "From time to time, Dusk Lilies can be found with a great innate power. This may be why it became such a powerful symbol.", fua = "Час від часу серед сутінкових лілій трапляються квіти з великою вродженою силою. Можливо, саме тому вона стала таким могутнім символом." }
    t[143488] = { name = "Зачарована Монета Нічнонароджених", fen = "Handed down for generations, this coin holds lingering knowledge from all its previous holders.", fua = "Передавана з покоління в покоління, ця монета зберігає відлуння знань усіх своїх колишніх власників." }
    t[143494] = { name = "Загадкова Записка", fen = "It appears to be from one of the cultists Karam spoke of.", fua = "Схоже, вона від одного з культистів, про яких казав Карам." }
    t[143495] = "Чарівна Паличка Інквізитора"
    t[143496] = { name = "Маніфест Заприсяглих Безкраю", fen = "These writings detail the aims of the Nethersworn cult.", fua = "Ці писання докладно викладають цілі культу Заприсяглих Безкраю." }
    t[143498] = { name = "Палець Зарядженого Конструкта", fen = "The Magistrix is getting reckless. The devastating power that thing has in its pinky alone could have leveled half the palace.", fua = "Магістрикс стає необачною. Нищівної сили, яку ця штука має в одному лише мізинці, вистачило б, щоб зрівняти із землею половину палацу." }
    t[143499] = { name = "Перезаряджена Маска Лазутчика", fen = "Hastily put together, this mask was infused with too much power and is coming apart at the seams.", fua = "Поспіхом зібрана, ця маска була просочена надмірною силою й розповзається по швах." }
