    t[143533] = { name = "Просочене Ікло Володаря Безодні", fen = "Already a powerful demon, Rozzeleth appears to have absorbed a lot of Ancient Mana while stationed in Suramar. Severed from his fel form his tusk hums with it.", fua = "Уже й так могутній демон, Роззелет, схоже, увібрав силу-силенну Прадавньої Мани, поки перебував у Сурамарі. Відірване від його скверної подоби, ікло досі нею гуде." }
    t[143534] = { name = "Чарівна Паличка Удаваного Життя", fen = "Crafted by the magus Willem West", fua = "Виготовлено магусом Віллемом Вестом." }
    t[143536] = "Перевантажена Сфера Віщування"
    t[143537] = { name = "Осереддя Мани", fen = "Light bends and distorts curiously as it passes through this object...", fua = "Світло цікаво заломлюється й викривлюється, проходячи крізь цей предмет..." }
    t[143538] = { name = "Заплутана Куля Телемантії", fen = "Containing all possible telemancy results at once, theoretically it could take you exactly where you needed to go. In practice it only seemed reliable for when nature was calling.", fua = "Містячи водночас усі можливі результати телемантії, теоретично вона могла б перенести вас точно туди, куди вам потрібно. На практиці ж вона видавалася надійною лише тоді, коли кликала природа." }
    t[143540] = { name = "Недоналаштований Кристал Узгодження", fen = "Don't be fooled, just because it is not up to taking out a ley line manipulator does not mean it is not extremely powerful.", fua = "Хай вас не вводить в оману те, що йому забракло сил знешкодити маніпулятор силових ліній, — це не означає, що він не надзвичайно потужний." }
    t[143543] = "Дванадцятиструнна Гітара"
    t[143544] = { name = "Череп Зіпсуття", fen = "Not all of a demon's power returns to the Twisting Nether.", fua = "Не вся сила демона повертається до Викривленого Нижнього Світу." }
    t[143545] = { name = "Скверний Зосереджувальний Кристал", fen = "Etched by the beam of a great watcher demon, it can direct immense fel energy.", fua = "Викарбуваний променем велетенського демона-спостерігача, він здатен спрямовувати незмірну скверну енергію." }
    t[143548] = { name = "Торба Зі Скверних Жил", fen = "Strung together from the tendons and fibers of a fel beast, this bag reeks with fel energies.", fua = "Зшита з жил і волокон скверної звірюки, ця торба тхне скверною енергією." }
    t[143549] = "Порожня Скриня з Кристалами-Мотиваторами"
    t[143550] = "Коробка \"Нових\" Підків"
    t[143551] = { name = "Букет Троянд", fen = "They won't miss them, the last performance was dead anyway.", fua = "За ними ніхто не скучить, остання вистава й так була мертва." }
    t[143552] = { name = "Позитивна Рецензія", fen = "A true performance just about blossomed before the demise of the two heroes.", fua = "Справжня гра вистави майже розквітла перед загибеллю двох героїв." }
    t[143553] = { name = "Негативна Рецензія", fen = "It is no wonder Julianne is relegated to such Off Canal venues. She should take her own dose of poison.", fua = "Не дивно, що Джуліанну загнали на таку жалюгідну сцену. Їй варто було б скуштувати власної отрути." }
    t[143554] = { name = "Негативна Рецензія", fen = "Relegated to rotating venue, the only highlight of Romulo and Julianne is their off night.", fua = "Виставу «Ромуло і Джуліанна» спекали на змінну сцену недарма: найкраще в ній — вихідний вечір без вистави." }
    t[143555] = "Плащ Червоної Шапочки"
    t[143556] = { name = "Обвуглені Уламки Кісток", fen = "The bones are smoldering, and should be handled with care.", fua = "Кістки ще тліють, тож поводитися з ними слід обережно." }
    t[143561] = { name = "Догоріла Тіньова Свічка", fen = "Not very helpful for lightning dark places, but will serve as proof of your champion's victory.", fua = "Не надто помічна, щоб освітлювати темні місця, але слугуватиме доказом перемоги вашого захисника." }
