    t[143738] = { name = "Летючий Пісковий Годинник", fen = "Previously a gift Arluin gave to Arluelle.", fua = "Колись це був дарунок Арлуїна для Арлуелли." }
    t[143739] = { name = "Знак Душеруба", fen = "Aargoss was vain and intended for everyone to know of his deeds.", fua = "Ааргосс був марнославний і прагнув, щоб усі знали про його діяння." }
    t[143740] = { name = "Зачарований Прапор Сін'дорай", fen = "Marked by a powerful ward, the blood elves use these banners to mark out their borders and discourage attackers.", fua = "Позначені потужним оберегом, ці прапори криваві ельфи використовують, щоб окреслити свої кордони й відлякати нападників." }
    t[143741] = { name = "Благословенний Прапор Калдорай", fen = "Blessed by Elune, these banners are placed around forward night elf camps to grant protection and aid.", fua = "Благословенні Елуною, ці прапори встановлюють довкола передових таборів нічних ельфів, щоб дарувати захист і підмогу." }
    t[143742] = { name = "Скіпетр Керксана", fen = "A powerful scepter brought with Ingra from another world.", fua = "Потужний скіпетр, що його Інгра принесла з іншого світу." }
    t[143743] = { name = "Високозаряджена Манова Затичка", fen = "Having been stopped up for millennia, it is brimming with power.", fua = "Будучи закупореною тисячоліттями, вона переповнена силою." }
    t[143744] = { name = "Благословенні Клинки Рейвенкреста", fen = "A set of blades appearing to contain incredible energy from a priest's blessing. It might be a bit much for one of our new recruits.", fua = "Набір клинків, що, схоже, містить неймовірну енергію жрецького благословення. Для когось із наших новобранців це, можливо, забагато." }
    t[143745] = { name = "Осереддя Висмоктувача Силових Ліній", fen = "Powerful work requires powerful tools.", fua = "Потужна праця вимагає потужних знарядь." }
    t[143746] = { name = "Занурений У Скверну Клинок", fen = "A potent fusion of energies.", fua = "Потужне поєднання енергій." }
    t[143747] = { name = "Ключ До Нічної Твердині", fen = "The key has become much more than a mere key over the millennia. Take it! Use it to unlock power rather than bar others from it.", fua = "За тисячоліття ключ став чимось набагато більшим, ніж простий ключ. Візьми його! Використай, щоб вивільняти силу, а не відмежовувати від неї інших." }
    t[143748] = "Лейлускатий Короп"
    t[143749] = { name = "Зіпсована Матриця Нічнороджених", fen = "The intricate Nightborne talisman has been twisted and corrupted for nefarious deeds. It would be better to drain the power for a better purpose.", fua = "Вигадливий талісман нічнороджених було спотворено й зіпсовано задля лихих діянь. Краще було б витягти з нього силу для шляхетнішої мети." }
