    t[143853] = { name = "Нещасливий Кролик", fen = "Missing a foot.", fua = "Бракує лапки." }
    t[143856] = { name = "Сувій Скверношовку", fen = "The voices of the souls trapped within are haunting.", fua = "Голоси ув'язнених усередині душ наводять моторошний жах." }
    t[143860] = { name = "Камінь Приреченості", fen = "The object of Magatha's affection, as well as endless elemental enhancement.", fua = "Об'єкт прихильності Маґати, а також невичерпне джерело стихійного посилення." }
    t[143868] = "Відзнака досягнення"
    t[143869] = "Відзнака перемоги"
    t[143870] = "Відзнака героїзму"
    t[143871] = "Відзнака міфу"
    t[143888] = { name = "Скверношлак", fen = "Rapidly cooling, but hopefully you're wearing gloves.", fua = "Швидко холоне, та сподіваймося, що ви в рукавичках." }
    t[143889] = "Наплічники Велетенства"
    t[143890] = "Чоботи Стусанів"
