    t[143900] = "Лист від Максиміліана"
    t[143918] = { name = "Стабілізувальний Кристал", fen = "Emits a high-pitched, angry buzz when touched.", fua = "Видає високий, сердитий гул, коли його торкаєшся." }
    t[144071] = { name = "Ріг Гелі", fen = "Powered by the souls of Helya's subjects.", fua = "Живиться душами підданих Гелі." }
    t[144227] = "Душа Криги"
    t[144228] = "Динозавряче Моджо"
    t[144235] = "Чарівна Паличка Розвіювання"
    t[144236] = { name = "Оплічник Майстра-Вбивці", fen = "Fear not what you can see, but what you can't see. -Mathias Shaw, SI:7.", fua = "Бійся не того, що бачиш, а того, чого не бачиш. — Матіас Шоу, ШР:7." }
    t[144238] = { name = "Прадавні Кістки", fen = "Unidentified and undated remains.", fua = "Неопізнані рештки незнаного віку." }
    t[144239] = { name = "Конденсатор Імператора", fen = "Stolen from the Highkeeper Ra-den, the Fallen Keeper of Storms.", fua = "Викрадений у Верховного Хранителя Ра-дена, Полеглого Хранителя Бур." }
    t[144240] = { name = "Сплюндровані Припаси", fen = "Covered in just a bit of fel goop. It's probably fine.", fua = "Вкриті лише трохи скверною слизотою. Мабуть, усе гаразд." }
    t[144241] = { name = "Просякнуті Скверною Останки", fen = "These bones have been ravaged by fel energies.", fua = "Ці кістки спустошені енергіями скверни." }
    t[144242] = { name = "Пестощі Ксоні", fen = "X'oni's mere presence was enough to cheer up her allies. Even though she was one of the most powerful druids to ever exist, many of her tricks were learned from the legendary priest, Phyrix.", fua = "Самої присутності Ксоні було достатньо, щоб підбадьорити її союзників. Хоч вона й була однією з наймогутніших друїдок усіх часів, багатьох своїх хитрощів вона навчилася від легендарного жерця Фірікс." }
    t[144244] = { name = "Кам Ксі'рафф", fen = "Named after a unique priest, whose name no one could utter.", fua = "Названий на честь незрівнянного жерця, чиє ім'я ніхто не міг вимовити." }
    t[144247] = { name = "Прихований Намір Раммала", fen = "Verius quickly became aware of Rammal's motives once he revealed his true form.", fua = "Веріус швидко усвідомив наміри Раммала, щойно той явив свою справжню подобу." }
    t[144249] = { name = "Відроджена Ненависть Архімонда", fen = "Archimonde the Defiler, overlord of the legion army and wielder of limitless magics, has destroyed countless worlds across the infinity of the universes.", fua = "Архімонд Осквернитель, повелитель армії Легіону та володар безмежних магій, знищив незліченні світи в безкраї всесвітів." }
    t[144255] = { name = "Виснажені Скверні Кристали", fen = "Devoid of fel energy.", fua = "Позбавлені енергії скверни." }
    t[144258] = { name = "Прозріння Майбутнього Велена", fen = "Velen the Ageless One, known by his people as the Prophet, blessed with the gift of Sight, and aided by the Light, has led the draenei for over 25,000 years.", fua = "Велен Безвічний, відомий своєму народові як Пророк, благословенний даром Прозріння та ведений Світлом, провадив дренеїв понад 25 000 років." }
    t[144259] = { name = "Палке Бажання Кіл'джедена", fen = "Kil'jaeden the Deceiver, supreme commander of the Burning Legion, has a simple agenda: consume all life and magic, assimilate every race into the Legion's ranks, slay any who dare resist, and destroy all of creation.", fua = "Кіл'джеден Облудник, верховний командувач Палаючого Легіону, має просту мету: поглинути все життя та магію, влити кожен народ до лав Легіону, вбити всіх, хто посміє чинити опір, та знищити все творіння." }
    t[144260] = { name = "Льодова Пора", fen = "They always seem to have something magical up their sleeves.", fua = "Здається, у них завжди напоготові щось чарівне." }
    t[144266] = "Розтрощений Ріг Вартового Гніву"
    t[144267] = "Закривавлене Лезо Сокири Орди"
    t[144268] = "Піхотний клинок Альянсу"
    t[144269] = "Порожня Скалка Душі"
    t[144270] = "Зрита Скверною Надгробна Плита"
    t[144271] = "Пекучий Кіготь Пекельника"
    t[144272] = "Печатка Хоробрості"
    t[144273] = { name = "Передсмертний Подих Маарада", fen = "In the Light, we are one.", fua = "У Світлі ми єдині." }
    t[144274] = { name = "Спіраль Тяжіння", fen = "The existence and mixture of various forces and energies often forms powerful vortices of mana.", fua = "Існування та змішування різних сил та енергій нерідко утворює потужні вири мани." }
    t[144275] = { name = "Рішучість Саруана", fen = "Contrary to the lies of Matis the Cruel, Saruan remained steadfast until his departure from the Light.", fua = "Усупереч брехні Матіса Жорстокого, Саруан лишався непохитним аж до свого відходу від Світла." }
    t[144277] = { name = "Загартовані на Ковадлі Наручі", fen = "They once belonged to Wei Speedstout, master of ale and smithing.", fua = "Колись вони належали Вею Швидкоброду, майстру елю та ковальства." }
    t[144279] = { name = "Манія Величі", fen = "Great power... at any cost.", fua = "Велика сила... за будь-яку ціну." }
    t[144280] = { name = "Смертний Марш", fen = "In this world, nothing is certain except death.", fua = "У цьому світі немає нічого певного, окрім смерті." }
    t[144281] = { name = "Кровоспин Черепоцвіт", fen = "Your blood for my blood.", fua = "Твоя кров за мою кров." }
    t[144282] = "Збруя Грубіяна"
    t[144292] = { name = "Дух Полум'я Темряви", fen = "The Dragon of the Darkness Flame can sometimes damage the wielder horribly. But when controlled, the wielder gains tremendous power.", fua = "Дракон Полум'я Темряви часом може жахливо поранити власника. Та коли його приборкано, власник здобуває величезну силу." }
    t[144293] = { name = "Холодне Ядро Дружини", fen = "And in her dying moments... Sindragosa's final thoughts turned to bitterness, hatred, and revenge.", fua = "І в передсмертні миті... останні думки Синдрагоси сповнилися гіркоти, ненависті та помсти." }
    t[144294] = { name = "Латна Кінська Броня", fen = "This barding should be what Grayson was looking for.", fua = "Саме таку броню, мабуть, і шукав Грейсон." }
    t[144295] = { name = "Пані та Дитя", fen = "Through introspection and perseverance, Archdruid Thom'acos learned to replicate the power of the twin moons.", fua = "Через самозаглиблення та наполегливість архідруїд Том'акос навчився відтворювати силу місяців-близнюків." }
    t[144297] = "Талісман Перемоги"
    t[144303] = { name = "Гіроскопічний Стабілізатор Мод.II", fen = "Through conservation of angular momentum of course! Quite simple, really.", fua = "Завдяки збереженню кутового моменту, звісно! Зовсім просто, насправді." }
