    t[144309] = { name = "Формула: Чар Шиї — Знак Майстра", fen = "Teaches you how to perform the Mark of the Master enchantment more efficiently.", fua = "Навчає вас ефективніше накладати чари «Знак майстра»." }
    t[144310] = { name = "Формула: Чар Шиї — Знак Майстра", fen = "Teaches you how to perform the Mark of the Master enchantment much more efficiently.", fua = "Навчає вас значно ефективніше накладати чари «Знак майстра»." }
