    t[144319] = { name = "Формула: Чар Шиї — Знак Смертоносного", fen = "Teaches you how to perform the Mark of the Deadly enchantment much more efficiently.", fua = "Навчає вас значно ефективніше накладати чари «Знак смертоносного»." }
    t[144326] = { name = "Оплічник Командування", fen = "Disobedient pets end up on the mantle.", fua = "Неслухняні улюбленці опиняються на оплічнику." }
    t[144329] = { name = "Загартоване Скверноскло", fen = "Found in Sprocket Containers, which can obtained by players with the Boon of the Builder enchantment.", fua = "Знаходиться в Контейнерах із Деталями, які можуть здобути гравці з чаром «Благословення Будівничого»." }
    t[144331] = "Кроєні Черепобої"
