    t[144334] = "Важкі Черепопалювачі"
    t[144335] = { name = "Креслення: Пошиті Черепобластери", fen = "Teaches you how to craft Tailored Skullblasters.", fua = "Навчає вас виготовляти Пошиті Черепобластери." }
    t[144336] = { name = "Креслення: Міцні Черепобластери", fen = "Teaches you how to craft Rugged Skullblasters.", fua = "Навчає вас виготовляти Міцні Черепобластери." }
    t[144337] = { name = "Креслення: Кольчужні Черепобластери", fen = "Teaches you how to craft Chain Skullblasters.", fua = "Навчає вас виготовляти Кольчужні Черепобластери." }
    t[144338] = { name = "Креслення: Важкі Черепобластери", fen = "Teaches you how to craft Heavy Skullblasters.", fua = "Навчає вас виготовляти Важкі Черепобластери." }
    t[144340] = { name = "Притулок Рін", fen = "Rin watches over us, as Emperor Shaohao once did for her and for the rest of Pandaria.", fua = "Рін наглядає за нами, як колись імператор Шаохао наглядав за нею та за всією Пандарією." }
    t[144341] = "Перезаряджувана Батарея Рівза"
    t[144343] = { name = "Креслення: Перезаряджувана Батарея Рівза", fen = "Teaches you how to craft a Rechargeable Reaves Battery.", fua = "Навчає вас виготовляти Перезаряджувану Батарею Рівза." }
    t[144354] = { name = "Вогненно-Червоні Калічники", fen = "Cats are capricious. If they walk up to you, it's great. But if you try to walk up them it doesn't always go so well.", fua = "Коти примхливі. Якщо вони підходять до тебе — чудово. Та якщо ти намагаєшся підійти до них, усе не завжди минає так гладко." }
    t[144355] = { name = "Піротексова Запальна Тканина", fen = "Of course you can fight fire with fire. You can fight everything with fire.", fua = "Звісно, можна боротися з вогнем вогнем. Вогнем можна боротися з усім." }
    t[144358] = { name = "З Попелу в Порох", fen = "Ashes... ashes... they all fall down.", fua = "Попіл... попіл... усі вони падуть." }
    t[144361] = { name = "Кістяний Фартух Різника", fen = "Ahhh... Fresh meat...", fua = "Ахх... Свіже м'ясо..." }
    t[144362] = { name = "Пульсуючий Самоцвіт", fen = "Radiating with fel energy.", fua = "Випромінюють енергію скверни." }
    t[144364] = { name = "Жнива й Сівба", fen = "If you reap what you sow... Well, I guess I better get going then.", fua = "Якщо пожинаєш те, що посіяв... Що ж, гадаю, мені краще вже рушати." }
    t[144369] = { name = "Уроки Простору-Часу", fen = "The increase of chaos is what distinguishes the past from the future, giving a direction to time. -Hawking, Professor of Space-Time", fua = "Зростання хаосу — ось що відрізняє минуле від майбутнього, надаючи часові напрямку. — Гокінг, професор простору-часу" }
    t[144385] = { name = "Відданість Пробуджувача", fen = "Thal'kiel was a sorcerer of unmatched talent who led an order of eredar magi called the Wakeners, specialists in the arts of conjuration and binding. This is a symbol of their loyalty even after death.", fua = "Тал'кіель був чаклуном незрівнянного таланту, що очолював орден магів-ередарів на ім'я Пробуджувачі — майстрів прикликання й зв'язування. Це символ їхньої відданості навіть по смерті." }
    t[144391] = "Потужний Боксерський Перстень Кулачного Бійця"
    t[144392] = "Потужний Боксерський Перстень Кулачного Бійця"
    t[144395] = { name = "Огляд Досліджень Артефактів", fen = "An overview of the inital notes on many of the great weapons that have played a role in Azeroth's history.", fua = "Огляд початкових нотаток про численні величні зброї, що відіграли роль в історії Азероту." }
    t[144399] = "Зимова Накидка Аристократа"
    t[144400] = "Пернатий Плащ Перогривих"
    t[144401] = { name = "Плащ Незліченних Піхов", fen = "If you've ever wanted to carry dozens of knives easily, you're in luck.", fua = "Якщо ви завжди хотіли легко носити з собою десятки ножів, вам пощастило." }
    t[144402] = { name = "Уламок Ядра Спустошувача Скверни", fen = "Even a small fragment of a Fel Reaver's core contains vast power.", fua = "Навіть малий уламок ядра скверноплюндрувача містить величезну силу." }
    t[144403] = { name = "Модний Осінній Плащ", fen = "Do not wear in the spring months, lest you be ridiculed.", fua = "Не носіть навесні, щоб не стати посміховиськом." }
    t[144404] = "Мана-Шнур Облуди"
    t[144405] = "Поясна Застібка Безчесної Могутності"
    t[144406] = "Старовинний Пояс Сутінкової Варти"
    t[144407] = "Сяйливий Небесний Пояс"
    t[144431] = { name = "Збірник Досліджень Артефактів: Томи I-III", fen = "Once the Orders began sharing resources, these pages of knowledge became obsolete.", fua = "Щойно ордени почали ділитися ресурсами, ці сторінки знань застаріли." }
    t[144432] = { name = "Жалюгідні Каламбури Дубосерда", fen = "My bark is worse than my bite...", fua = "Моя кора грізніша за мій укус..." }
    t[144433] = { name = "Збірник Досліджень Артефактів: Том I", fen = "Once the Orders began sharing resources, these pages of knowledge became obsolete.", fua = "Щойно ордени почали ділитися ресурсами, ці сторінки знань застаріли." }
    t[144434] = { name = "Збірник Досліджень Артефактів: Томи I та II", fen = "Once the Orders began sharing resources, these pages of knowledge became obsolete.", fua = "Щойно ордени почали ділитися ресурсами, ці сторінки знань застаріли." }
    t[144435] = { name = "Збірник Досліджень Артефактів: Томи I-IV", fen = "Once the Orders began sharing resources, these pages of knowledge became obsolete.", fua = "Щойно ордени почали ділитися ресурсами, ці сторінки знань застаріли." }
    t[144438] = { name = "Винищувач Зека", fen = "You think I'm scared of death? I've done it a million times. I'm great at it. How many times have you died?", fua = "Думаєш, я боюся смерті? Я помирав мільйон разів. Я в цьому майстер. А ти скільки разів помирав?" }
    t[144442] = { name = "Самотня Бабка", fen = "Hard to play with just one and no ball.", fua = "Важко гратися лише однією, та ще й без м'яча." }
