    t[146314] = { name = "Мармуровий Наконечник Стріли", fen = "This arrowhead likely belonged to an ancient Highborne sentinel.", fua = "Цей наконечник, імовірно, належав прадавній вартовій з Високородних." }
    t[146315] = { name = "Місячна Руна Елуни", fen = "This boon was not immune from being strewn.", fua = "Цей дар не був захищений від того, щоб загубитися." }
    t[146316] = { name = "Прадавнє Срібло Сурамару", fen = "This type of coin has not been in circulation in Suramar for at least 7,000 years.", fua = "Такі монети не були в обігу в Сурамарі щонайменше 7000 років." }
    t[146318] = { name = "Стегнова Кістка Біса", fen = "Nearly indistinguishable from an ogre's fingerbone.", fua = "Майже не відрізнити від пальцевої кістки оґра." }
    t[146319] = { name = "Пил Загибелі", fen = "A fetid mix of ash and demon's blood.", fua = "Смердюча суміш попелу й демонічної крові." }
    t[146320] = { name = "Збляклий Зелений Самоцвіт", fen = "Gems like these were often studded into a high-ranking demon's armor or weapon.", fua = "Такими самоцвітами часто оздоблювали броню чи зброю високородних демонів." }
    t[146321] = { name = "Скам'янілий Ріг Сукуби", fen = "A grim silhouette of a long-fallen demon.", fua = "Похмурий силует демона, що загинув давним-давно." }
    t[146322] = { name = "Скверний Грінок", fen = "These ancient demonic rations have been perfectly preserved.", fua = "Ці прадавні демонічні пайки чудово збереглися." }
    t[146323] = { name = "Тріснутий Череп Кобольда", fen = "Missing its candle.", fua = "Бракує свічки." }
    t[146324] = { name = "Закостеніле Перо Птаха-Рок", fen = "When preserved in a dry enough environment, these feathers become hard like bone.", fua = "Якщо зберігати їх у достатньо сухому місці, ці пера тверднуть, мов кістка." }
    t[146325] = { name = "Поточений Хробаками Мішечок із Зерном", fen = "The pouch is full of holes, and the grain is long-gone.", fua = "Мішечок увесь у дірках, а зерна давно немає." }
    t[146326] = { name = "Обвуглений Вогнекамінь", fen = "The remains of a particularly hot-burning funeral pyre.", fua = "Рештки особливо жаркого поховального вогнища." }
    t[146327] = { name = "Скам'янілий Тотем Повітря", fen = "The forgotten totem of a long-dead tauren shaman.", fua = "Забутий тотем давно померлого шамана-таврена." }
