    t[146403] = { name = "Присмерковий Пристрій", fen = "Tendrils of dark energy roil and seethe within the device's core.", fua = "Пасма темної енергії клубочаться й вирують у серцевині пристрою." }
    t[146404] = { name = "Вінець Луміннеллії", fen = "Worn by the ancient high elven kings.", fua = "Носили його прадавні високоельфійські королі." }
    t[146405] = { name = "Кристалізована Сутність Силітидів", fen = "Created from the blood of one thousand silithid magi.", fua = "Створена з крові тисячі магів-силітидів." }
