    t[146408] = { name = "Пошарпаний Тринкет", fen = "Though this brass compass has seen better days, the craftsmanship is of the highest caliber.", fua = "Хоч цей мідний компас і бачив кращі часи, майстерність його виготовлення найвищого ґатунку." }
    t[146409] = { name = "Камінь Душі Нічнонароджених", fen = "Pulses with Kathra'natir's contained anger.", fua = "Пульсує стримуваним гнівом Катранатіра." }
    t[146411] = { name = "Техніка Руни Вантуса: Гробниця Саргераса", fen = "Teaches you how to craft a Vantus Rune: Tomb of Sargeras.", fua = "Навчає вас виготовляти Руну Вантуса: Гробниця Саргераса." }
