    t[146653] = { name = "Прадавня Скалка Прив'язування", fen = "The ancient artifact contains the immense power to bind any living creature to this realm.", fua = "Прадавній артефакт містить незмірну силу, здатну прив'язати будь-яку живу істоту до цього світу." }
    t[146659] = { name = "Сутність Скалок Порожнечі", fen = "Used to craft legendary armor. Can be purchased from Warmage Kath'leen on the Broken Shore, or bought and sold on the Auction House.", fua = "Використовується для виготовлення легендарної броні. Можна придбати в бойової магині Катлін на Зламаному Узбережжі або купити чи продати на аукціоні." }
    t[146662] = { name = "Зілля Питва Зілля", fen = "Allows the drinker to drink potions.", fua = "Дозволяє тому, хто п'є, пити зілля." }
    t[146663] = { name = "Промоклий Гобелен", fen = "Would be worth a fortune if it wasn't ruined.", fua = "Коштував би цілий статок, якби не був зіпсований." }
    t[146664] = { name = "Витончено Оздоблений Самоцвітами Ключ", fen = "It goes to the chest you just opened.", fua = "Він підходить до скрині, яку ви щойно відімкнули." }
    t[146666] = { name = "Целумбра, Двоїстість Ночі", fen = "Shadow and star, darkness and light, despair and hope.", fua = "Тінь і зоря, темрява і світло, відчай і надія." }
    t[146667] = { name = "Невгамовна Відвага Рету", fen = "His bravery was contagious.", fua = "Його хоробрість була заразливою." }
    t[146668] = { name = "Сідало Пильності", fen = "Even in death, the spirits of the owls watch over their masters, so long as they have a steady glove to perch upon.", fua = "Навіть по смерті духи сов наглядають за своїми господарями, доки мають надійну рукавицю, на яку можна сісти." }
    t[146669] = { name = "Вічний Прихисток Вартової", fen = "Her spirit is bound within the leather of these treads, anchoring her to this world.", fua = "Її дух вплетено в шкіру цих чобіт, і це прив'язує її до цього світу." }
