    t[147906] = { name = "Скверне Серце Аргуса", fen = "The Fel Heart of Argus was the secret of High Inquisitor Raalgar's immortality. Though the wells that connected it to Argus were destroyed, it still has significant power to protect anyone who is magically connected to it while on Argus.", fua = "Скверне Серце Аргуса було таємницею безсмертя Верховного Інквізитора Раалгара. Хоч криниці, що поєднували його з Аргусом, було знищено, воно й досі має чималу силу, щоб захищати кожного, хто магічно пов'язаний із ним, перебуваючи на Аргусі." }
