    t[151566] = { name = "Демонічна Шкіра", fen = "A thick, tainted hide, crafted by leatherworkers. Can be bought and sold on the auction house.", fua = "Товста, заражена шкіра, оброблена чинбарями. Можна купувати й продавати на аукціоні." }
    t[151567] = { name = "Світлоткана Тканина", fen = "Delicate to the touch, yet immeasurably strong in its weave. Sometimes kept by demons as trophies of their kills. Can be bought and sold on the auction house.", fua = "Делікатна на дотик, та незмірно міцна у плетінні. Часом демони зберігають її як трофей своїх убивств. Можна купувати й продавати на аукціоні." }
