    t[151636] = { name = "Душа Архідруїда", fen = "The Cenarion Circle reside in the Dreamgrove. They are the guardians of nature, the preservers of balance, and the protectors of all life.", fua = "Коло Кенарія мешкає в Гаю Снів. Вони охоронці природи, берегині рівноваги й захисники всього живого." }
    t[151639] = { name = "Душа Винищувача", fen = "The Illidari reside in the Fel Hammer. They wield the forbidden powers of the demons they slay to fight the forces of chaos - at any cost.", fua = "Іллідарі мешкають у Скверній Кувалді. Вони володіють забороненими силами демонів, яких убивають, щоб боротися з силами хаосу за будь-яку ціну." }
    t[151640] = { name = "Душа Володаря Смерті", fen = "The Knights of the Ebon Blade reside in Acherus, the Ebon Hold. They were once the champions of the scourge. They are now the damned.", fua = "Лицарі Чорного Клинка мешкають в Ахерусі, Чорній Цитаделі. Колись вони були чемпіонами Погибелі. Тепер вони прокляті." }
    t[151641] = { name = "Душа Майстра-Мисливця", fen = "The Unseen Path reside in the Trueshot Lodge. They are the watchers in the wild. They are the eagle on the wind. They walk the lonely road.", fua = "Незримий Шлях мешкає в Ложі Влучного Пострілу. Вони вартові дикої природи. Вони орел на вітрі. Вони простують самотньою дорогою." }
    t[151642] = { name = "Душа Архімага", fen = "The Tirisgarde reside in the Hall of the Guardian. They are the elite mage-guard of Dalaran, called upon in the past by the Council of Tirisfal to do battle in the absence of the Guardian.", fua = "Тирісгарда мешкає в Залі Вартового. Це елітна вартова магів Даларана, яку в минулому скликала Рада Тірісфаля для битви за відсутності Вартового." }
    t[151643] = { name = "Душа Великого Майстра", fen = "The Order of the Broken Temple reside in the Temple of the Five Dawns. They are the bringers of hope to a dim future.", fua = "Орден Зруйнованого Храму мешкає в Храмі П'яти Світанків. Вони несуть надію в похмуре майбутнє." }
    t[151644] = { name = "Душа Верховного Лорда", fen = "The Order of the Silver Hand reside in the Sanctum of Light. They are the united might of the Argent Crusade, the Hand of Argus, the Sunwalkers, and the Blood Knights.", fua = "Орден Срібної Руки мешкає у Святилищі Світла. Це об'єднана міць Срібного Хрестового Походу, Руки Аргуса, Сонцеходів і Лицарів Крові." }
    t[151646] = { name = "Душа Верховного Жерця", fen = "The Conclave reside in the Netherlight Temple. They are the masters of the Light and embracers of the Void - for light cannot exist without darkness, and darkness without light.", fua = "Конклав мешкає в Храмі Нижнього Світла. Вони майстри Світла й приймають Порожнечу, бо світло не може існувати без темряви, а темрява без світла." }
    t[151647] = { name = "Душа Провидця", fen = "The Earthen Ring reside in the Heart of Azeroth. They wield the power of the elemental forces between which they maintain balance. They are the true masters of the elements.", fua = "Земляне Кільце мешкає в Серці Азерота. Вони володіють силою стихійних сил, між якими підтримують рівновагу. Вони справжні майстри стихій." }
    t[151649] = { name = "Душа Володаря Нижнього Світу", fen = "The Council of the Black Harvest reside in the Dreadscar Rift. They are the takers of souls, the commanders of demons, and the masters of the dark arts.", fua = "Рада Чорного Жнива мешкає в Розломі Жахошраму. Вони викрадачі душ, повелителі демонів і майстри темних мистецтв." }
    t[151650] = { name = "Душа Володаря Битв", fen = "The Valarjar reside in the Skyhold. They are the mighty ascended champions of Odyn who protect the world from all threats.", fua = "Валар'яри мешкають у Небесній Твердині. Це могутні піднесені чемпіони Одіна, що захищають світ від усіх загроз." }
    t[151651] = "Капці Гравітаційного Зниження"
    t[151652] = { name = "Генератор Червоточин: Аргус", fen = "The user is responsible for final destinations teleported to, and may not take any legal action against the maker of this device.", fua = "Користувач несе відповідальність за кінцеві пункти телепортації та не може подавати позови проти виробника цього пристрою." }
    t[151653] = "Клаптик Рецепта з Розколотих Островів"
    t[151654] = { name = "Техніка Руни Вантуса: Анторус, Палаючий Трон", fen = "Teaches you how to craft a Vantus Rune: Antorus, the Burning Throne.", fua = "Навчає вас виготовляти Руну Вантуса: Анторус, Палаючий Трон." }
    t[151655] = { name = "Техніка Руни Вантуса: Анторус, Палаючий Трон", fen = "Teaches you how to craft a Vantus Rune: Antorus, The Burning Throne more efficiently.", fua = "Навчає вас виготовляти Руну Вантуса: Анторус, Палаючий Трон ефективніше." }
