    t[151749] = "Підозріла Лампа"
    t[151782] = { name = "Вежа без Вершини", fen = "In the room the men have come and gone, / Talking of Alleria and Turalyon.", fua = "У кімнаті люди йшли й верталися знов, / Розмовляли про Аллерію й Тураліона." }
    t[151783] = { name = "Пісня Хамелеона", fen = "The Keepers maintained peace with the knowledge that nothing endures: not a tree, not love, not even a death by violence.", fua = "Хранителі берегли мир, знаючи, що ніщо не триває вічно: ні дерево, ні любов, ані навіть смерть від насильства." }
    t[151784] = { name = "Двері в Нікуди", fen = "Two paths diverged in the mist, and I... / I took the third, untraveled by.", fua = "Дві стежки розійшлися в тумані, і я... / Я обрав третю, ще не топтану." }
    t[151785] = { name = "Вогонь у Глибині", fen = "And the wrath of the demons would challenge their worth; / And the idols were broke in the shrine of the Earth.", fua = "І лють демонів випробувала їхню вартість; / І ідоли розбилися у святилищі Землі." }
    t[151786] = { name = "Внутрішнє Сяяння", fen = "Lend me your power, and immortality will be ours.", fua = "Дай мені свою силу, і безсмертя буде нашим." }
    t[151787] = { name = "Алебастрова Пані", fen = "When the stars threw down their spears / And water'd heaven with their tears: / Did she smile her work to see?", fua = "Коли зорі склали свої списи / І вмили небеса слізьми: / Чи всміхнулася вона, побачивши творіння своє?" }
    t[151788] = { name = "Останній Подих Штормстаута", fen = "Why do we fight? To protect home and family... To preserve balance and bring harmony.", fua = "Навіщо ми б'ємося? Щоб захистити дім і родину... Щоб зберегти рівновагу й принести гармонію." }
    t[151789] = { name = "Ідентифікатор Захисного Конструкта", fen = "Marks the bearer as one exempt from Annihilation Protocols.", fua = "Позначає носія як того, хто звільнений від Протоколів Знищення." }
    t[151795] = { name = "Скверна Душолупа", fen = "The origins of the Soulflayer remain unknown. There are no mentions of him in any of the Titan records.", fua = "Походження Душолупа лишається невідомим. У жодному з літописів Титанів немає згадки про нього." }
    t[151796] = { name = "Холодне Серце", fen = "The beating of a frozen heart can be heard from a vast distance away, reminding all living things of their inevitable death.", fua = "Биття замерзлого серця чути на величезній відстані, нагадуючи всьому живому про неминучу смерть." }
    t[151798] = { name = "Теорія Хаосу", fen = "Within chaos there exists repetition, feedback loops, and underlying patterns.", fua = "У хаосі існують повторення, петлі зворотного зв'язку й приховані візерунки." }
    t[151799] = { name = "Обійми Забуття", fen = "There is no better guide to the world than oblivion.", fua = "Немає кращого провідника по світу, ніж забуття." }
    t[151800] = { name = "Осяйне Місячне Сяйво", fen = "Doubt thou the stars are fire;\n\nDoubt that the sun doth move.", fua = "Не вір, що зорі — то вогонь;\n\nНе вір, що сонце ходить." }
    t[151801] = { name = "Головний Убір Бегемота", fen = "Don't wake a tiger from its nap.", fua = "Не буди тигра, що спить." }
    t[151802] = { name = "Лють Природи", fen = "Harmony between the natural and supernatural forces may be difficult to achieve, but leads to substantial greatness.", fua = "Гармонії між природними й надприродними силами буває важко досягти, та вона веде до справжньої величі." }
    t[151803] = { name = "Прудкість Віндраннерів", fen = "'Your heart flew straight as any arrow upon the wind, sister. You were the brightest of our Order. You were the most beloved of our kin.' -Sylvanas, to Alleria.", fua = "«Твоє серце летіло прямо, наче стріла на вітрі, сестро. Ти була найяскравішою в нашому Ордені. Ти була найулюбленішою серед рідні.» — Сильвана до Аллерії." }
    t[151805] = { name = "Зміїний Язик", fen = "A rare power usually belonging to those with an affinity for serpents.", fua = "Рідкісний дар, що зазвичай належить тим, хто має спорідненість зі зміями." }
    t[151807] = { name = "Плащ Незримого Хижака", fen = "Even the most powerful enemy has a weakness that can be exposed.", fua = "Навіть у найдужчого ворога є слабкість, яку можна виявити." }
    t[151808] = { name = "Оплічник Першого з Кірін-Тору", fen = "Thousands of years ago, the high elves of Quel'Thalas taught the arcane arts to the humans, who went on to form the Kirin Tor and rule over Dalaran.", fua = "Тисячі років тому високі ельфи Кель'Таласу навчили людей таємних мистецтв, а ті згодом заснували Кірін-Тор і запанували над Даларом." }
    t[151809] = { name = "Приборкане Інфернальне Ядро", fen = "The Infernal Core frequently erupts with jets of flame that burn with enough heat to melt through the toughest of materials.", fua = "Інфернальне Ядро часто вибухає струменями полум'я, гарячого настільки, що воно проплавляє найміцніші матеріали." }
    t[151810] = { name = "Розбиті Уламки Синдрагоси", fen = "Forged from the remnants of Arthas' destruction at Sindragosa's Fall, this sends a chill down the wearer's spine.", fua = "Викуті з решток того, що Артас знищив під час Падіння Синдрагоси, вони проймають хребет носія холодом." }
    t[151811] = { name = "Вітер Віє", fen = "The sun rises, the wind blows, and the mighty fall.", fua = "Сонце сходить, вітер віє, а могутні падають." }
    t[151812] = { name = "Стовпи Найглибшого Світла", fen = "The light shines brightest in those it consumes.", fua = "Світло сяє найяскравіше в тих, кого поглинає." }
    t[151813] = { name = "Кара Багряного Інквізитора", fen = "Can you not see it, brothers and sisters? There is but one way to wipe the Scourge from the face of Azeroth.", fua = "Хіба ви не бачите, брати й сестри? Є лише один спосіб стерти Покруч з лиця Азероту." }
    t[151814] = { name = "Серце Порожнечі", fen = "The Void is not empty. It is full of malice, despair, and death.", fua = "Порожнеча не порожня. Вона повна злоби, відчаю й смерті." }
    t[151815] = { name = "Порожня Корона", fen = "It's hard to put a leash on a dog once you've put a crown on its head.", fua = "Важко надіти повідок на пса, якщо ти вже надів йому на голову корону." }
    t[151817] = { name = "Прокляття Невгамовності", fen = "We get restless easily. We need something to do.", fua = "Нас легко охоплює неспокій. Нам треба чимось зайнятися." }
    t[151818] = { name = "Перший із Мертвих", fen = "Death comes to us all in the end...", fua = "Зрештою смерть приходить до всіх нас..." }
    t[151819] = { name = "Жевріюче Серце", fen = "The essence of thousands of fiery elementals have been imbued in these gloves, yet they are strangely cool to the touch.", fua = "Ці рукавички просякнуті сутністю тисяч вогняних елементалів, та все ж на дотик вони дивовижно прохолодні." }
    t[151821] = { name = "Майстер Жнив", fen = "Out of suffering emerges the strongest of souls.", fua = "Зі страждань постають найдужчі з душ." }
    t[151822] = { name = "Кривавий Свічадо Арарата", fen = "His blood infuses the glimmering steel, spilled by dragons, gods, and demons. Even from beyond, he protects his friends.", fua = "Його кров просякла осяйну крицю, пролита драконами, богами й демонами. Навіть із потойбіччя він захищає своїх друзів." }
    t[151823] = { name = "Око Великого Шторму", fen = "In the eye of the tornado, there's no high and low, no floor and sky.", fua = "В оці торнадо немає ні верху, ні низу, ні землі, ні неба." }
    t[151824] = { name = "Берсерки Валар'ярів", fen = "They aren't known for their subtlety.", fua = "Тонкощі — не їхній коник." }
    t[151825] = { name = "Ріг Гатууна", fen = "Let the call of battle ring out. We strike as one!", fua = "Нехай лунає поклик битви. Ми б'ємо як один!" }
    t[151830] = "Суд Світла"
    t[151837] = { name = "Матриця Закликання", fen = "These long, slender crystals are coveted for their use in focusing the Light into wrathful blasts.", fua = "Ці довгі тонкі кристали цінують за здатність фокусувати Світло в нищівні спалахи." }
    t[151838] = { name = "Ядро Суду", fen = "It is said that the Judgment Core is the crowning achievement of the Army of the Light's artificers.", fua = "Кажуть, що Ядро Суду — найвище досягнення майстрів Армії Світла." }
    t[151839] = { name = "Броня Месника", fen = "The Grand Army's lightforged armor is honed to protect their vindicators from the Legion's fel magic.", fua = "Загартований Світлом обладунок Великої армії викуваний так, щоб захищати її месників від скверної магії Легіону." }
    t[151842] = "Набір Обладунків Крокулів"
    t[151843] = "Комплект Обладунків Ередата"
    t[151844] = "Комплект Обладунків Зенедара"
    t[151845] = { name = "Використана Фіала", fen = "There appear to be traces of some sort of golden fluid in it.", fua = "Усередині наче залишилися сліди якоїсь золотавої рідини." }
    t[151851] = { name = "Бездоганне Скверноядро", fen = "The heart of a pure fel entity, brimming with chaotic energy.", fua = "Серце чистої скверної істоти, що вирує хаотичною енергією." }
    t[151856] = { name = "Зів'яла Астральна Слава", fen = "An unusable version of the herb.", fua = "Непридатна форма цієї трави." }
    t[151857] = { name = "Молода Астральна Слава", fen = "An astral glory sapling.", fua = "Паросток астральної слави." }
    t[151858] = { name = "Кореневий Жмут Астральної Слави", fen = "A small, coccoon-like root ball with hints of energy eminating from the interior.", fua = "Невеликий схожий на кокон кореневий жмут, з нутра якого ледь-ледь струмує енергія." }
    t[151860] = { name = "Брила Покладу Емпірею", fen = "The ore seems to have a starry effect to its surface.", fua = "Поверхня руди наче всипана зорями." }
    t[151861] = { name = "Пил Емпірею", fen = "Small remnants of empyrium ore.", fua = "Дрібні рештки руди емпірею." }
    t[151862] = { name = "Непридатне Ядро Емпірею", fen = "A fractured core of empyrium ore.", fua = "Розколоте ядро руди емпірею." }
    t[151863] = { name = "Брила Жили Емпірею", fen = "The ore seems to have a starry effect to its surface.", fua = "Поверхня руди наче всипана зорями." }
    t[151864] = { name = "Вкраплена Руда Емпірею", fen = "A chunk of empyrium ore with large portions of unusable rock.", fua = "Брила руди емпірею з великою кількістю непридатної породи." }
    t[151865] = { name = "Уламки Емпірею", fen = "Small bits and pieces of empyrium ore.", fua = "Дрібні шматочки руди емпірею." }
    t[151866] = { name = "Опоганений Брухт", fen = "These scraps of fiendish leather appear tainted and emit a very foul smell.", fua = "Цей брухт демонічної шкіри виглядає опоганеним і видає дуже гидкий сморід." }
    t[151867] = { name = "Зіпсута Демонічна Шкіра", fen = "The corruption emitting from the beast was able to spoil this piece of leather.", fua = "Скверна, що виходила від звіра, зіпсувала цей шматок шкіри." }
    t[151868] = { name = "Зіпсутий Зуб", fen = "The corruption from the beast has spread into this tooth, rendering it useless.", fua = "Скверна звіра проникла в цей зуб, зробивши його непридатним." }
    t[151871] = { name = "Ящик Скверносланцю", fen = "A large crate of felslate ore.", fua = "Великий ящик руди скверносланцю." }
    t[151872] = { name = "Емпірейний Нагрудник", fen = "A shimmering piece of gold and white armor.", fua = "Осяйний обладунок із золота й білизни." }
    t[151874] = { name = "Ткацький Верстат Світлоткання", fen = "A dectorative loom with golden etching engraved into it.", fua = "Оздоблений ткацький верстат із золотим гравіруванням." }
    t[151875] = "Поклик до Світла"
    t[151876] = { name = "Книга креслень Ворела", fen = "A large tome filled with different jewelcrafting designs.", fua = "Великий фоліант, повний різноманітних креслень для ювелірної справи." }
    t[151877] = { name = "Діжка Пов'язок на Око", fen = "So Much Fun, You'll Y'aardly Know What To Do With Yourself", fua = "Стільки втіхи, що ти й не знатимеш, за що хапатися!" }
    t[151878] = { name = "Емпірійова Корона", fen = "The crown sparkles like the stars, with each jewel placed just so.", fua = "Корона мерехтить, мов зорі, і кожен самоцвіт у ній вкладено саме так, як треба." }
    t[151879] = { name = "Очищена Бісівська Шкіра", fen = "The purified version of this leather no longer smells or makes you feel uncomfortable to hold it.", fua = "Очищений варіант цієї шкіри більше не смердить і не викликає неприємних відчуттів, коли її тримаєш." }
