    t[236772] = { name = "Стромкар, Зброєлам", fen = "The steel of the barbarian king shall strike the final blow. It shall silence the din of battle, and bring the first kingdom into an age of peace.", fua = "Сталь короля-варвара завдасть останнього удару. Вона змусить замовкнути гуркіт битви й приведе перше королівство в епоху миру." }
    t[237746] = { name = "Бойові Мечі Валар'ярів", fen = "Helya's betrayal shall never be forgiven. Let her rot beneath the waves, far from the Halls of Valor.", fua = "Зраду Гельї ніколи не буде прощено. Хай гниє під хвилями, далеко від Чертогів Звитяги." }
    t[237747] = { name = "Бойові Мечі Валар'ярів", fen = "In truth, it is her power that makes these weapons truly magnificent. Her power, laced with her hatred, crashes endlessly against Odyn's spirit. The tension between those energies will forever permeate these blades...", fua = "Насправді саме її сила робить цю зброю воістину величною. Її сила, сповнена ненависті, безупинно б'ється об дух Одіна. Напруга між цими енергіями навіки пронизуватиме ці клинки..." }
    t[237748] = { name = "Лускоскалка", fen = "Here is whence true strength comes. From deep places... within the world, and within oneself.", fua = "Ось звідки приходить справжня сила. З глибоких місць... у світі та в самому собі." }
    t[237749] = { name = "Луска Землезахисника", fen = "...it was one of Neltharion's cast-off scales. It saved Magnar's life. The blast of flame parted around the black scale, but the sheer force carried Magnar out of the lair, sending him tumbling down the slopes of Highmountain.", fua = "...це була одна зі скинутих лусок Нелтаріона. Вона врятувала Маґнару життя. Спалах полум'я розійшовся навколо чорної луски, але сама його сила винесла Маґнара з лігва, скинувши його котитися схилами Високогір'я." }
    t[237755] = { name = "Трактат про Мудрість Ради", fen = "Kirin Tor Relic", fua = "Реліквія Кірін-Тор" }
