    t[242555] = { name = "Ешбрінгер", fen = "So it was that over the course of time, the man and the weapon seemed as one. Ashbringer became a name of legend, attributed not just to the fearsome blade but also to the relentless knight who wielded it.", fua = "Так із плином часу людина і зброя ніби злилися воєдино. Ешбрінгер став легендарним іменем, що належало не лише грізному клинку, а й невблаганному лицареві, який ним володів." }
    t[242556] = { name = "Клинки-Близнюки Дурисвіта", fen = "Make examples of those foolish enough to oppose you, and the rest of their kind will grovel at your feet.", fua = "Зробіть приклад із тих, хто настільки дурний, щоб протистояти вам, і решта їхнього роду плазуватиме біля ваших ніг." }
    t[242557] = { name = "Клинки-Близнюки Дурисвіта", fen = "The end has come! Let the unravelling of this world commence!", fua = "Кінець настав! Хай почнеться розпад цього світу!" }
    t[242558] = { name = "Алунет", fen = "After many setbacks, Aegwynn finally bound the entity to an enchanted greatstaff. The task of containing Aluneth was done, but it would take the Guardian years to truly harness its power.", fua = "Після багатьох невдач Еґвінн нарешті прив'язала сутність до зачарованого великого посоха. Завдання стримати Алунет було виконане, та Хранительці знадобилися роки, щоб по-справжньому опанувати його силу." }
    t[242559] = { name = "Клинки Полеглого Принца", fen = "When my days have come to an end, you shall be king.", fua = "Коли настане кінець моїх днів, ти станеш королем." }
    t[242560] = { name = "Клинки Полеглого Принца", fen = "I will show you the justice of the grave... and the true meaning of fear.", fua = "Я покажу тобі правосуддя могили... і справжнє значення страху." }
    t[242561] = { name = "Г'Ханір, Материнське Дерево", fen = "At the beginning, there was a source of healing and balance, a place where all life could rest and revive.", fua = "На початку було джерело зцілення й рівноваги, місце, де все живе могло відпочити й відродитися." }
    t[242562] = { name = "Паща Проклятих", fen = "The Maw's thirst is unquenchable. If it is not fed fresh victims, it will not hesitate to drink from its wielder instead.", fua = "Спрага Пащі невгамовна. Якщо її не годувати свіжими жертвами, вона не вагаючись питиме натомість зі свого носія." }
    t[242563] = { name = "Апокаліпсис", fen = "It shall sow destruction and war. Famine and death. It shall tempt with power, and then bring an end to all life.", fua = "Він посіє руйнацію й війну. Голод і смерть. Він спокушатиме могутністю, а тоді покладе край усьому живому." }
    t[242564] = { name = "Ікла Пожирача", fen = "The hound's bite lingers, even long after its death. A surprisingly effective and subtle tool for something so crude.", fua = "Укус гончака триває ще довго після його смерті. Напрочуд дієве й витончене знаряддя як на щось таке грубе." }
    t[242565] = { name = "Ікла Пожирача", fen = "Azhir manari kirel. Akim manari galar!", fua = "Azhir manari kirel. Akim manari galar!" }
    t[242566] = { name = "Кіготь-Пазур", fen = "The Eagle Spear. Spear of the Wild Gods. Talonclaw. Bearing many names and many blessings, this is a weapon of legends.", fua = "Орлиний Спис. Спис Диких Богів. Кіготь-Пазур. Носячи багато імен і багато благословень, це зброя легенд." }
    t[242567] = { name = "Думгаммер", fen = "A stranger will raise the hammer high, and with it justice shall reign.", fua = "Чужинець здійме молот високо, і завдяки йому запанує справедливість." }
    t[242568] = { name = "Фело'мелорн", fen = "...not elven weapons. Not when they are reforged with magic, and hatred, and a burning need for revenge. No, Arthas. Felo'melorn is stronger than ever-as am I. - Kael'thas Sunstrider", fua = "...не ельфійська зброя. Не тоді, коли її перековано з магією, ненавистю й палкою жагою помсти. Ні, Артасе. Фело'мелорн сильніший, ніж будь-коли — як і я. — Кель'тас Сонцеблукач" }
    t[242569] = { name = "Пазурі Урсока", fen = "Ursoc, brother of Ursol and guardian of the furbolg tribes... bearer of the strength of the forest itself.", fua = "Урсок, брат Урсола й охоронець племен фурболгів... носій сили самого лісу." }
    t[242570] = { name = "Пазурі Урсока", fen = "Azeroth will need you. If you do not stand ready, the world may fall.", fua = "Азерот потребуватиме тебе. Якщо не будеш напоготові, світ може загинути." }
    t[242571] = { name = "Срібна Рука", fen = "Tyr replied that he did not consider his argent hand a reminder of defeat. For him it was a symbol of the sacrifice he had made to defend Azeroth, and he wanted the world to see it that way as well.", fua = "Тір відповів, що не вважає свою срібну руку нагадуванням про поразку. Для нього вона була символом жертви, яку він приніс на захист Азероту, і він хотів, щоб світ бачив її саме так." }
    t[242573] = { name = "Т'уре, Маяк Наару", fen = "Blessed are the torchbearers, who bring light to the darkness.", fua = "Благословенні смолоскипоносці, які несуть світло в темряву." }
    t[242574] = { name = "Тас'дора, Спадок Віндраннерів", fen = "When it was retrieved from the Sunwell, the bow radiated power. Talanas was humbled by the gift. He named the weapon Thas'dorah, \"Valor of the Forest.\"", fua = "Коли його дістали із Сонячного Колодязя, лук випромінював міць. Таланас був вражений цим даром. Він назвав зброю Тас'дора — \"Доблесть Лісу\"." }
    t[242575] = { name = "Ксал'атат, Клинок Чорної Імперії", fen = "Xal'atath has a mind of its own. Ignore its maddening whispers. Do not trust the lies it spins. Take from it what you need, but always remember that the dark presence in the blade is not your ally.", fua = "Ксал'атат має власну волю. Не зважайте на її божевільний шепіт. Не вірте брехні, яку вона плете. Беріть від неї те, що вам потрібно, та завжди пам'ятайте, що темна присутність у клинку — не ваш союзник." }
    t[242576] = { name = "Бойові Клинки Алдрахі", fen = "His warblades howled over the clamor of battle, rending anything that came near. Each demon Toranaar vanquished seemed to fill him with renewed vigor and strength. He was an army unto himself.", fua = "Його бойові клинки вили понад гомоном битви, шматуючи все, що наближалося. Кожен демон, якого здолав Торанаар, неначе наповнював його новою снагою й силою. Він був цілою армією у власній особі." }
    t[242577] = { name = "Бойові Клинки Алдрахі", fen = "The Aldrachi were a proud race. Too proud to serve. Millions of demons died before the Aldrachi were wiped out, and it took Sargeras himself to kill their king.", fua = "Алдрачі були гордим народом. Надто гордим, щоб служити. Мільйони демонів полягли, перш ніж алдрачі було винищено, і лише сам Сарґерас зміг убити їхнього короля." }
    t[242578] = { name = "Коса Елуни", fen = "There is power within that would be freed. With balance and control, the wolf may be tamed, but only for a time.", fua = "У ній криється сила, що прагне волі. Через рівновагу й самовладання вовка можна приборкати, та лише на час." }
    t[242579] = { name = "Ікла Ашамани", fen = "She ripped through the demons' ranks and then disappeared into the trees. She crept along the high branches and dove down upon the Legion commanders. She was a terror, a fearsome beast, and she held nothing back, offering no mercy.", fua = "Вона рвала ряди демонів, а тоді зникала між дерев. Вона кралася високими гілками й кидалася згори на командирів Легіону. Вона була жахіттям, грізною звіриною, і не стримувала себе, не даючи пощади." }
    t[242580] = { name = "Ікла Ашамани", fen = "The sacrifice of Ashamane is remembered to this day. We live by her grace, and her children still tread the forests with us as our closest companions.", fua = "Жертву Ашамані пам'ятають донині. Ми живемо її милістю, а її діти й досі блукають лісами поруч із нами, наші найвірніші супутники." }
    t[242581] = { name = "Удар Титана", fen = "A peerless example of techno-magical engineering, infused with the power of storms.", fua = "Неперевершений взірець техномагічної інженерії, наповнений силою бур." }
    t[242582] = { name = "Чорнохолод", fen = "Ebonchill contained only a sliver of Alodi's might, but even that was more than most magi could ever hope of wielding.", fua = "Чорнохолод містив лише крихту могутності Алоді, але навіть цього було більше, ніж будь-коли могли сподіватися опанувати більшість магів." }
    t[242583] = { name = "Сторож Істини", fen = "With the first hammer fall, rivers of magma spilled from the icy mountains. With the second, the sky howled and lightning set the heavens aflame. With the third, a single ray of sunlight pierced the storm clouds and whispered over Truthguard's surface.", fua = "Із першим ударом молота з крижаних гір ринули ріки магми. З другим небо завило, і блискавки запалили небеса. З третім єдиний промінь сонячного світла пронизав грозові хмари й прошелестів над поверхнею Сторожа Істини." }
    t[242584] = { name = "Шукач Клятви", fen = "Killing for the sake of killing... conquering for the sake of conquest... there is no honor in such things. There is only shame and regret.", fua = "Убивати заради вбивства... завойовувати заради завоювання... у цьому немає честі. Лише ганьба й каяття." }
    t[242585] = { name = "Гнів Світла", fen = "It was with our greatest hopes and prayers that we attended the ceremony that day... and it is with our greatest sorrows that we departed it.", fua = "Із найбільшими надіями та молитвами ми були присутні на церемонії того дня... і з найбільшим горем ми її покинули." }
    t[242586] = { name = "Царевбивці", fen = "It was not a pleasant death. But it was fast, quiet, and efficient. When the orc took his last breath, the wound that killed him became irregular. Nobody would be able to tell whether he had died to a knife, an axe, or a spear.", fua = "Це була неприємна смерть. Але швидка, тиха й дієва. Коли орк зробив свій останній подих, рана, що вбила його, стала нерівною. Ніхто не зміг би сказати, чи загинув він від ножа, сокири чи списа." }
    t[242587] = { name = "Царевбивці", fen = "Countless voices hushed, and countless leaders toppled... all at the whim of his foul command. There would be no redemption for these acts, only solitude and sorrow.", fua = "Незліченні голоси змовкли, незліченні вожді повалені... і все це з примхи його лиховісного наказу. За ці діяння не буде спокути — лише самотність і скорбота." }
    t[242588] = { name = "Клинки Жаху", fen = "She saw herself commanding an impossibly large pirate fleet, one that could conquer the high seas and all the nations of Azeroth. Every ship that dared to challenge her burned, and every city gave up its treasures or was destroyed.", fua = "Вона бачила себе на чолі неймовірно великого піратського флоту, здатного підкорити відкрите море і всі народи Азероту. Кожен корабель, що смів кинути їй виклик, палав, а кожне місто віддавало свої скарби або гинуло." }
    t[242589] = { name = "Лють Кам'яної Матері", fen = "Created through the power of Doomhammer and the powerful shaman who wields it.", fua = "Створена силою Молота Долі та могутнього шамана, який ним володіє." }
    t[242591] = { name = "Шарас'дал, Скіпетр Припливів", fen = "They drifted into the abyss, but Azshara and her Highborne remained unbroken. The darkness around them was absolute, and so the queen willed Sharas'dal to bring them light...", fua = "Вони занурилися в безодню, та Азшара і її Високороджені лишилися незламні. Темрява довкола них була цілковита, тож королева наказала Шарас'далу принести їм світло..." }
    t[242592] = { name = "Щит Морської Королеви", fen = "As the ocean crushed the life from their bodies, ancient creatures stirred in the darkness. Their whispers flowed through the currents. Their powers wrapped tight around the queen and her servants.", fua = "Коли океан вичавлював життя з їхніх тіл, у темряві заворушилися прадавні істоти. Їхній шепіт линув течіями. Їхня сила міцно обвила королеву та її слуг." }
    t[242593] = { name = "Кулак Ра-дена", fen = "To seal Al'Akir's demise, Master Ra slammed his fist into the mountaintop. The heavens split wide, and all the fire and fury they contained crashed down atop the Windlord's head.", fua = "Щоб запечатати загибель Аль'Акіра, Майстер Ра вдарив кулаком об вершину гори. Небеса розкололися навпіл, і весь вогонь та лють, що вони містили, обрушилися на голову Володаря Вітру." }
    t[242594] = { name = "Захист Верховного Хранителя", fen = "Ra and Helya crafted a shield, the Highkeeper's Ward, to act as a key to the Elemental Plane. It thrummed with the energies of the four elements, which Ra could call upon whenever he desired.", fua = "Ра і Хелья викували щит, Захист Верховного Хранителя, щоб він слугував ключем до Стихійного Виміру. Він гудів енергіями чотирьох стихій, до яких Ра міг закликати, коли забажає." }
    t[242595] = { name = "Шейлун, Посох Туманів", fen = "You seek the calm, inevitable force of a deep river, the kind that carves canyons into the toughest stone and carries away warriors on its currents without so much as a ripple. Sheilun is the embodiment of that idea.", fua = "Ви прагнете спокійної, неминучої сили глибокої річки, тієї, що вирізає каньйони в найтвердішому камені й несе воїнів своєю течією, не лишаючи й брижів. Шейлун — утілення цієї ідеї." }
    t[242596] = { name = "Фу Цзань, Супутник Мандрівника", fen = "From the beginning, this staff has accompanied legendary creatures and immortal spirits as they carried out important, lasting work all across Azeroth.", fua = "Від самого початку цей посох супроводжував легендарних істот та безсмертних духів, поки вони звершували важливу, тривку справу по всьому Азероту." }
    t[242597] = { name = "Кулаки Небес", fen = "When Irmaat hefted his two weapons and tested the power within them, uncontrollable fury spilled forth.", fua = "Коли Ірмаат здійняв дві свої зброї й випробував силу в них, з них вихлюпнулася некерована лють." }
    t[242598] = { name = "Скіпетр Саргераса", fen = "When at last the moment arrived for Ner'zhul to act, he did so with wild abandon, heedless of the consequences. It mattered not to him if Draenor was destroyed; in fact, he welcomed it as part of his legacy.", fua = "Коли нарешті настала мить Нер'зулу діяти, він зробив це з шаленою нестримністю, не зважаючи на наслідки. Йому було байдуже, чи буде знищено Дренор; ба більше, він вітав це як частину своєї спадщини." }
    t[242599] = { name = "Ултхалеш, Жниварка Мертвого Вітру", fen = "The scythe's master will either overcome Sataiel or be consumed, which will only make the blade more powerful. And then another bearer will take their place. And another.", fua = "Володар коси або здолає Сатаїель, або буде поглинутий, що лише зробить клинок сильнішим. А тоді інший носій посяде його місце. І ще інший." }
    t[242600] = { name = "Череп Ман'арі", fen = "When finally Thal'kiel emerged, he was changed. He had aged by centuries, alone in the dark with his thoughts and his thralls. His back was twisted and stooped, and there was an odd glimmer in his eye. He summoned his Wakeners, and we answered the call...", fua = "Коли Тал'кіель нарешті з'явився, він був змінений. Він постарів на століття, на самоті в темряві зі своїми думками й рабами. Спина його викривилася й згорбилася, а в очах був дивний полиск. Він прикликав своїх Пробудників, і ми відповіли на поклик..." }
    t[242601] = { name = "Кулаки Небес", fen = "There was a great flash of light and a great rush of air, and when it was done, Irmaat could feel his weapons, Al'burq and Alra'ed trembling with elemental power.", fua = "Спалахнуло яскраве світло, війнув потужний порив вітру, а коли все стихло, Ірмаат відчув, як його зброя, Ал'бурк і Алра'ед, тремтить від стихійної сили." }
    t[242602] = { name = "Таємниці Порожнечі", fen = "The moment I touched the blade, a name was spoken in my mind: Xal'atath. I knew then that I could not destroy the dagger. Not yet. How can one defeat a power she does not understand?", fua = "Тієї миті, коли я торкнувся клинка, у моїй свідомості пролунало ім'я: Ксал'атат. Тоді я зрозумів, що не зможу знищити кинджал. Ще ні. Як можна здолати силу, якої не розумієш?" }
    t[242603] = { name = "Серце Фенікса", fen = "When the fighting was done, Dath'Remar stood painted in demon blood. As night fell, we knew that more battles remained, and yet, with this elf and this blade among us, we held out hope that victory did not lie beyond our grasp.", fua = "Коли битву було завершено, Дат'Ремар стояв, заплямований кров'ю демонів. Коли настала ніч, ми знали, що попереду ще багато боїв, і все ж, маючи серед нас цього ельфа й цей клинок, ми плекали надію, що перемога нам по силі." }
    t[242604] = { name = "Клинки Жаху", fen = "No blade can shed the blood of so many innocents and not demand a toll on its wielder as well. They are no treasure.", fua = "Жоден клинок не може пролити кров стількох невинних, не вимагаючи плати й від того, хто ним володіє. Це не скарб." }
    t[242605] = { name = "Хребет Тал'кіеля", fen = "The Wakeners' screams echoed across Argus, as a grim reminder of the price paid for dealing with demons.", fua = "Крики Пробудників лунали над Аргусом похмурим нагадуванням про ціну, заплачену за угоду з демонами." }
    t[242617] = { name = "Дивний Симулякр", fen = "This appears to be the artifact weapon you're already holding. What is this sorcery?", fua = "Здається, це та сама артефактна зброя, яку ви вже тримаєте. Що це за чаклунство?" }
