    t[243366] = { name = "Посох Бігуна Часом", fen = "Manifested by a ripple in time, this weapon seems to adapt to your experience. It doesn't seem very powerful, though.", fua = "Породжений брижами в часі, цей посох ніби пристосовується до вашого досвіду. Утім, він не видається надто потужним." }
