    t[243372] = { name = "Булава Бігуна Часом", fen = "Manifested by a ripple in time, this weapon seems to adapt to your experience. It doesn't seem very powerful, though.", fua = "Породжений брижами в часі, цей посох ніби пристосовується до вашого досвіду. Утім, він не видається надто потужним." }
    t[243373] = { name = "Зброя Бігуна Часом", fen = "Contains weapons for other class specializations.", fua = "Містить зброю для інших спеціалізацій класу." }
    t[243601] = { name = "Цікава Дивовижа", fen = "What is stranger--the curious curio or the person that collects them?", fua = "Що дивніше — чудернацька дивовижа чи той, хто її колекціонує?" }
    t[243604] = { name = "Зігнутий і Пошарпаний Клинок", fen = "If it could but speak, this blade would spin a tale of battles so mighty and numerous that even the titans would be moved to tears.", fua = "Якби цей клинок міг говорити, він розповів би оповідь про такі могутні й численні битви, що навіть титани зронили б сльозу." }
    t[243607] = { name = "Запорошена Кам'яна Табличка", fen = "The touch of eons has erased all but the faintest traces of history from this ancient tablet, leaving naught but a flicker of memory clinging desperately to the present over the abyss of nothingness.", fua = "Дотик еонів стер із цієї прадавньої таблички все, окрім найслабших слідів історії, лишивши тільки мерехтіння спогаду, що відчайдушно чіпляється за сьогодення над безоднею небуття." }
    t[244823] = { name = "Срібний Драконоклинок Опору", fen = "Forged before the War of the Ancients, quenched in the blood of demons and forgotten in the shadows of Blackrook.", fua = "Скутий ще до Війни Прадавніх, загартований у крові демонів і забутий у тінях Блекрука." }
    t[244824] = { name = "Загублений у Часі Лук Жаху Банші", fen = "A faint, haunting melody can be heard from within this temporally-lost relic, the lyrics of the song barely discernable.", fua = "Зсередини цієї загубленої в часі реліквії чути ледь вловиму, бентежну мелодію, слова пісні майже не розібрати." }
