    t[244837] = { name = "Драконоклинок, Скутий Магами", fen = "'Forged by the hand of the magesmith, at the behest of House Ravencrest. May it serve you as well as my blade has served me.' - Kur'talos Ravencrest", fua = "«Скутий рукою маго-коваля на замовлення Дому Рейвенкрест. Нехай він служить тобі так само добре, як мій клинок служив мені.» — Кур'талос Рейвенкрест" }
