    t[245925] = { name = "Артефактіумний Пісок", fen = "Untapped power courses through you as the sand sifts through your fingers.", fua = "Невикористана міць струмує крізь вас, поки пісок просочується між пальцями." }
    t[245996] = { name = "Хаосокуте Намисто", fen = "Forbidden energies swirl within, beckoning endless potential.", fua = "Усередині вирує заборонена енергія, що вабить безмежним потенціалом." }
    t[245997] = "Печатка Імперії Назжатару"
    t[245998] = { name = "Перстень Захисту Розуму", fen = "Given to particularly adept spellcasters as a sign of their prowess, this ring hums with long-forgotten energy.", fua = "Подарований особливо вправним заклинателям на знак їхньої майстерності, цей перстень гуде давно забутою енергією." }
