    t[246013] = { name = "Тас'дора, Спадок Віндраннерів", fen = "When it was retrieved from the Sunwell, the bow radiated power. Talanas was humbled by the gift. He named the weapon Thas'dorah, \"Valor of the Forest.\"", fua = "Коли його дістали із Сонячного Колодязя, лук випромінював міць. Таланас був вражений цим даром. Він назвав зброю Тас'дора — \"Доблесть Лісу\"." }
