    t[253222] = { name = "Спотворений Шип Сну", fen = "In the Emerald Nightmare, even a thorn can blossom into something potent and deadly.", fua = "У Смарагдовому Жахітті навіть шип може розквітнути в щось могутнє й смертоносне." }
    t[253223] = { name = "Фрактальна Скверноскалка", fen = "The Deceiver's might is so great that even a drop of his blood, cooled and crystallized to a sliver, contains near-infinite potential.", fua = "Могутність Облудника така велика, що навіть крапля його крові, охолола й закристалізована в уламок, містить майже безмежний потенціал." }
    t[253224] = { name = "Часточка Зламаного Часу", fen = "A prismatic shard that resonates with this fractured timeline. Simultaneously it takes shape as a corrupted thorn, a warlock's gem, a fel-bright sliver, or an echo of death.", fua = "Призматична скалка, що резонує з цією розколотою лінією часу. Водночас вона набуває форми спотвореного шипа, самоцвіта чорнокнижника, скверно-осяйного уламка чи відлуння смерті." }
    t[253227] = { name = "Бездоганна Нитка Часу", fen = "In the now-collapsing alternate timeline where the infinite dragonflight experiments on the history of the Legion's third invasion, uncorrupted moments are increasingly rare and phenomenally potent.", fua = "У нинішній альтернативній лінії часу, що руйнується, де нескінченний драконяча зграя експериментує над історією третього вторгнення Легіону, неспотворені миттєвості трапляються дедалі рідше й мають феноменальну могутність." }
